def _user_persistent_root() -> Path:
    """同一个人跨次下载/换目录仍保留的数据根目录。"""
    local = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
    if local:
        return Path(local) / "Vpet"
    return Path.home() / ".vpet"


def _migrate_data_dir(src: Path, dst: Path) -> None:
    """把旧版 exe 旁 data 迁到持久目录（仅当目标尚无关键存档时）。"""
    if not src.is_dir() or src.resolve() == dst.resolve():
        return
    markers = ("pet_profile.json", "app_config.json", "music_affinity.json", "leaderboard.json")
    if any((dst / name).is_file() for name in markers):
        return
    try:
        dst.mkdir(parents=True, exist_ok=True)
        for item in src.iterdir():
            target = dst / item.name
            if target.exists():
                continue
            if item.is_dir():
                shutil.copytree(item, target)
            elif item.is_file():
                shutil.copy2(item, target)
    except Exception:
        pass


def _resolve_app_paths() -> tuple[Path, Path]:
    if getattr(sys, "frozen", False):
        bundle = Path(sys._MEIPASS)
        app_dir = Path(sys.executable).resolve().parent
        exe_data = app_dir / "data"
        # 分享/便携包：目录内有 PORTABLE 标记时，存档跟文件夹走（互不共用本机所属人）
        if (app_dir / "PORTABLE").is_file() or (app_dir / "PORTABLE.txt").is_file():
            exe_data.mkdir(parents=True, exist_ok=True)
            return bundle, exe_data
        data = _user_persistent_root() / "userdata"
        data.mkdir(parents=True, exist_ok=True)
        _migrate_data_dir(exe_data, data)
        return bundle, data
    root = Path(__file__).resolve().parent
    return root, root / "data"


def _read_build_stamp() -> str:
    app_dir = Path(sys.executable).resolve().parent if getattr(sys, "frozen", False) else Path(__file__).resolve().parent
    stamp_file = app_dir / "BUILD_STAMP.txt"
    if stamp_file.exists():
        try:
            return stamp_file.read_text(encoding="utf-8").strip()
        except Exception:
            return ""
    return ""


def _note_build_stamp(app_config: dict) -> bool:
    """记录当前构建戳。不再因版本更新强制重弹操作说明（所属人/说明仅首次）。"""
    stamp = _read_build_stamp()
    if not stamp:
        return False
    prev = str(app_config.get("last_build_stamp") or "").strip()
    if prev == stamp:
        return False
    app_config["last_build_stamp"] = stamp
    return True


# 兼容旧调用名
def _reset_operation_guide_if_updated(app_config: dict) -> bool:
    return _note_build_stamp(app_config)

