def _pack_developer_corner(parent: tk.Misc, *, pady: tuple[int, int] = (14, 2)) -> tk.Label:
    """操作说明 / 关于：开发者署名用更小字贴在下方角落。"""
    base = PIXEL_FONT
    family = base[0] if isinstance(base, tuple) and base else "Courier New"
    size = int(base[1]) if isinstance(base, tuple) and len(base) > 1 else 12
    corner_font = (family, max(8, size - 3))
    lbl = tk.Label(
        parent,
        text=f"作者：{ABOUT_DEVELOPER}",
        font=corner_font,
        fg="#666666",
        bg=MENU_BG,
    )
    lbl.pack(anchor=tk.SE, pady=pady)
    return lbl


def _pack_web_link(
    parent: tk.Misc,
    text: str,
    url: str,
    *,
    prefix: str = "",
) -> None:
    row = tk.Frame(parent, bg=MENU_BG)
    row.pack(anchor=tk.W, fill=tk.X)
    if prefix:
        tk.Label(row, text=prefix, font=PIXEL_FONT, fg=MENU_FG, bg=MENU_BG).pack(side=tk.LEFT)
    link = tk.Label(row, text=text, font=PIXEL_FONT, fg=THEME_BLUE, bg=MENU_BG, cursor="hand2")
    link.pack(side=tk.LEFT)

    def _open(_event=None, target: str = url) -> None:
        try:
            webbrowser.open(target)
        except Exception:
            pass

    link.bind("<Button-1>", _open)
    link.bind("<Enter>", lambda _e: link.config(fg=THEME_PINK))
    link.bind("<Leave>", lambda _e: link.config(fg=THEME_BLUE))


def _pack_community_follow_blurb(
    parent: tk.Misc,
    *,
    wraplength: int = GUIDE_TEXT_WRAP,
    pady: tuple[int, int] = (0, 6),
) -> tk.Text:
    """关注/源码文案：B站、小红书、GitHub、戏剧性谋杀为可点超链接。"""
    box = tk.Text(
        parent,
        font=GUIDE_FONT,
        fg=MENU_FG,
        bg=MENU_BG,
        relief=tk.FLAT,
        highlightthickness=0,
        bd=0,
        wrap=tk.WORD,
        cursor="arrow",
        height=6,
        width=max(24, wraplength // 10),
    )
    box.pack(anchor=tk.W, fill=tk.X, pady=pady)
    link_n = 0
    for line_i, segments in enumerate(COMMUNITY_FOLLOW_LINES):
        if line_i:
            box.insert(tk.END, "\n\n")
        for text, url in segments:
            if url:
                tag = f"cmlink_{link_n}"
                link_n += 1
                box.insert(tk.END, text, tag)
                box.tag_config(tag, foreground=THEME_BLUE, underline=True)

                def _on_enter(_e, t=tag) -> None:
                    box.tag_config(t, foreground=THEME_PINK)
                    box.config(cursor="hand2")

                def _on_leave(_e, t=tag) -> None:
                    box.tag_config(t, foreground=THEME_BLUE)
                    box.config(cursor="arrow")

                def _on_click(_e, target=url) -> None:
                    try:
                        webbrowser.open(target)
                    except Exception:
                        pass

                box.tag_bind(tag, "<Enter>", _on_enter)
                box.tag_bind(tag, "<Leave>", _on_leave)
                box.tag_bind(tag, "<Button-1>", _on_click)
            else:
                box.insert(tk.END, text)
    box.config(state=tk.DISABLED)
    try:
        lines = int(float(box.index("end-1c").split(".")[0]))
        box.config(height=max(4, min(10, lines + 1)))
    except Exception:
        pass
    return box


# 滚轮目标栈：Enter 武装、Leave 解除，避免给上百个子控件逐个 bind（长列表滑动卡顿主因之一）
_SCROLL_WHEEL_STACK: list[tk.Canvas] = []
_SCROLL_WHEEL_BOUND = False


def _scroll_temp_opaque(win: tk.Misc | None) -> None:
    """半透明窗滚动时短暂不透明，减轻 Win32 layered 合成卡顿；停滚后再恢复玻璃。"""
    if win is None:
        return
    try:
        if not win.winfo_exists():
            return
    except Exception:
        return
    if getattr(win, "_vpet_no_glass", False):
        return
    if not getattr(win, "_vpet_panel_glass", False):
        return
    try:
        if not getattr(win, "_scroll_opaque_temp", False):
            win.attributes("-alpha", 1.0)
            setattr(win, "_scroll_opaque_temp", True)
    except Exception:
        return
    job = getattr(win, "_scroll_opaque_job", None)
    if job is not None:
        try:
            win.after_cancel(job)
        except Exception:
            pass

    def _restore() -> None:
        try:
            setattr(win, "_scroll_opaque_job", None)
            if not getattr(win, "_scroll_opaque_temp", False):
                return
            setattr(win, "_scroll_opaque_temp", False)
            if getattr(win, "_vpet_no_glass", False):
                return
            if getattr(win, "_vpet_panel_glass", False):
                _try_set_window_alpha(win, PANEL_WINDOW_ALPHA)
        except Exception:
            pass

    try:
        setattr(win, "_scroll_opaque_job", win.after(140, _restore))
    except Exception:
        _restore()


def _scroll_wheel_global(event: tk.Event) -> str | None:
    stack = _SCROLL_WHEEL_STACK
    while stack:
        canvas = stack[-1]
        try:
            if canvas.winfo_exists():
                break
        except Exception:
            pass
        stack.pop()
    if not stack:
        return None
    canvas = stack[-1]
    delta = int(getattr(event, "delta", 0) or 0)
    if delta == 0:
        return None
    steps = int(-1 * (delta / 120))
    if not steps:
        steps = -1 if delta > 0 else 1
    try:
        _scroll_temp_opaque(canvas.winfo_toplevel())
    except Exception:
        pass
    try:
        # 每格多滚一点：同样距离更少事件，长列表更跟手
        canvas.yview_scroll(steps * 3, "units")
    except Exception:
        return None
    return "break"


def _scroll_arm_canvas(wrap: tk.Misc, canvas: tk.Canvas) -> None:
    """指针进入滚动区时接管滚轮；离开整区才解除（子控件间移动不解除）。"""

    def _enter(_event=None) -> None:
        global _SCROLL_WHEEL_BOUND
        while canvas in _SCROLL_WHEEL_STACK:
            try:
                _SCROLL_WHEEL_STACK.remove(canvas)
            except ValueError:
                break
        _SCROLL_WHEEL_STACK.append(canvas)
        if not _SCROLL_WHEEL_BOUND:
            try:
                wrap.winfo_toplevel().bind_all("<MouseWheel>", _scroll_wheel_global)
            except Exception:
                try:
                    canvas.bind_all("<MouseWheel>", _scroll_wheel_global)
                except Exception:
                    return
            _SCROLL_WHEEL_BOUND = True

    def _leave(_event=None) -> None:
        try:
            x = int(wrap.winfo_pointerx()) - int(wrap.winfo_rootx())
            y = int(wrap.winfo_pointery()) - int(wrap.winfo_rooty())
            if 0 <= x < int(wrap.winfo_width()) and 0 <= y < int(wrap.winfo_height()):
                return
        except Exception:
            pass
        while canvas in _SCROLL_WHEEL_STACK:
            try:
                _SCROLL_WHEEL_STACK.remove(canvas)
            except ValueError:
                break

    try:
        wrap.bind("<Enter>", _enter, add="+")
        wrap.bind("<Leave>", _leave, add="+")
    except Exception:
        pass


def _make_scrollable_frame(
    parent: tk.Misc,
    *,
    width: int,
    height: int,
    bg: str = MENU_BG,
    motif: str | None = None,
    motif_line: str | None = None,
) -> tuple[tk.Frame, tk.Frame, tk.Canvas]:
    """返回 (外层容器, 可滚动内层, canvas)。内层用于放置内容；仅纵向滚轮，无横向滚动。"""
    wrap = tk.Frame(parent, bg=bg)
    canvas = tk.Canvas(wrap, width=width, height=height, bg=bg, highlightthickness=0)
    scroll = tk.Scrollbar(wrap, orient=tk.VERTICAL, command=canvas.yview)
    # 滚动条位置合并到 idle，避免每格滚轮都同步重绘滑块
    _sb_pending: tuple | None = None
    _sb_job: str | None = None

    def _sb_set(*args) -> None:
        nonlocal _sb_pending, _sb_job
        _sb_pending = args
        if _sb_job is not None:
            return

        def _flush() -> None:
            nonlocal _sb_job, _sb_pending
            _sb_job = None
            pending = _sb_pending
            _sb_pending = None
            if pending is None:
                return
            try:
                scroll.set(*pending)
            except Exception:
                pass

        try:
            _sb_job = wrap.after_idle(_flush)
        except Exception:
            _flush()

    canvas.configure(yscrollcommand=_sb_set, yscrollincrement=28)
    scroll.pack(side=tk.RIGHT, fill=tk.Y)
    canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
    # 内容区略透出暗纹：内层用同色底，暗纹画在 canvas 上并压到窗口之下
    inner = tk.Frame(canvas, bg=bg)
    win_id = canvas.create_window((0, 0), window=inner, anchor=tk.NW)
    _sync_job: str | None = None
    _motif_size = (0, 0)

    def _do_sync_scroll() -> None:
        nonlocal _sync_job
        _sync_job = None
        try:
            canvas.configure(scrollregion=canvas.bbox("all"))
            # 内层铺满可见宽度，避免文字/按钮被夹在画布外
            canvas.itemconfigure(win_id, width=max(canvas.winfo_width(), 1))
        except Exception:
            pass

    def _sync_scroll(_event=None) -> None:
        nonlocal _sync_job
        if _sync_job is not None:
            try:
                wrap.after_cancel(_sync_job)
            except Exception:
                pass
            _sync_job = None
        try:
            _sync_job = wrap.after_idle(_do_sync_scroll)
        except Exception:
            _do_sync_scroll()

    def _paint_motif() -> None:
        nonlocal _motif_size
        if not motif:
            return
        try:
            size = (max(int(canvas.winfo_width()), 1), max(int(canvas.winfo_height()), 1))
        except Exception:
            return
        if size == _motif_size and canvas.find_withtag("motif"):
            return
        _motif_size = size
        line = motif_line or DIARY_PAPER_LINE
        _paint_theme_motif_watermark(canvas, motif, line, bg)
        try:
            canvas.tag_lower("motif")
        except Exception:
            pass

    def _on_canvas_cfg(event: tk.Event) -> None:
        try:
            canvas.itemconfigure(win_id, width=max(int(event.width), 1))
        except Exception:
            pass
        _paint_motif()

    inner.bind("<Configure>", _sync_scroll)
    canvas.bind("<Configure>", _on_canvas_cfg)
    _scroll_arm_canvas(wrap, canvas)

    def _refresh_binds(_event=None) -> None:
        # 兼容旧调用：内容变更后只需刷新 scrollregion（滚轮已用 Enter 武装，不必全树重绑）
        _sync_scroll()

    wrap.after_idle(_refresh_binds)
    try:
        setattr(wrap, "_refresh_mousewheel", _refresh_binds)
        setattr(wrap, "_scroll_canvas", canvas)
        setattr(wrap, "_scroll_inner", inner)
    except Exception:
        pass
    return wrap, inner, canvas


def _fit_panel_wh(
    win: tk.Misc,
    width: int = PANEL_FIXED_W,
    height: int = PANEL_FIXED_H,
) -> tuple[int, int]:
    """把面板钳到屏幕内的固定宽高，并写入 win._panel_fixed_size。"""
    try:
        sw = int(win.winfo_screenwidth())
        sh = int(win.winfo_screenheight())
    except Exception:
        sw, sh = 1280, 720
    w = min(int(width), max(280, sw - 80))
    h = min(int(height), max(240, sh - 100))
    try:
        win.geometry(f"{w}x{h}")
        win.minsize(min(260, w), min(180, h))
    except Exception:
        pass
    try:
        setattr(win, "_panel_fixed_size", (w, h))
    except Exception:
        pass
    return w, h


def _mark_game_play_panel(win: tk.Misc) -> None:
    """正式游玩窗：按内容撑开显示全，不走固定滚动壳。"""
    try:
        setattr(win, "_panel_full_size", True)
        setattr(win, "_panel_game_play", True)
    except Exception:
        pass
    try:
        if hasattr(win, "_panel_fixed_size"):
            delattr(win, "_panel_fixed_size")
    except Exception:
        pass


def _apply_label_wraplength(root: tk.Misc, wrap: int) -> None:
    """给子孙 Label 统一 wraplength，保证横向换行而不是裁字。"""
    wrap = max(120, int(wrap))

    def walk(w: tk.Misc) -> None:
        if isinstance(w, tk.Label):
            try:
                w.configure(wraplength=wrap)
            except Exception:
                pass
        for child in w.winfo_children():
            walk(child)

    walk(root)


def _finalize_guide_panel_layout(
    win: tk.Misc,
    scroll_wrap: tk.Misc,
    inner: tk.Frame,
    *,
    max_height: int = GUIDE_PANEL_H,
    text_wrap: int = GUIDE_TEXT_WRAP,
) -> None:
    """操作指南：横向按内容加宽到显示全；高度固定，纵向滑轮。"""
    _apply_label_wraplength(inner, text_wrap)
    try:
        win.update_idletasks()
    except Exception:
        pass
    canvas = getattr(scroll_wrap, "_scroll_canvas", None)
    try:
        sw = int(win.winfo_screenwidth())
        sh = int(win.winfo_screenheight())
    except Exception:
        sw, sh = 1280, 720
    need_inner = max(text_wrap, int(inner.winfo_reqwidth() or 0))
    chrome_x = 10 * 2 + 28  # padx*2 + 滚动条约宽
    chrome_y = 8 * 2 + 8
    # 以指南基准宽为准，内容再宽也钳住（大字号靠换行+纵向滚动）
    cap_w = min(GUIDE_PANEL_W, max(320, sw - 60))
    want_w = min(cap_w, max(320, min(need_inner + chrome_x, cap_w)))
    want_h = min(int(max_height), max(240, sh - 80))
    try:
        setattr(win, "_panel_fixed_size", (want_w, want_h))
        win.geometry(f"{want_w}x{want_h}")
        win.minsize(min(300, want_w), min(200, want_h))
    except Exception:
        pass
    if isinstance(canvas, tk.Canvas):
        try:
            canvas.configure(width=max(200, want_w - chrome_x), height=max(160, want_h - chrome_y))
        except Exception:
            pass
    refresh = getattr(scroll_wrap, "_refresh_mousewheel", None)
    if callable(refresh):
        try:
            win.after_idle(refresh)
        except Exception:
            refresh()


def _pack_fixed_scroll_panel(
    win: tk.Misc,
    *,
    width: int = PANEL_FIXED_W,
    height: int = PANEL_FIXED_H,
    bg: str = MENU_BG,
    padx: int = 10,
    pady: int = 8,
    glass: bool = False,
    motif: str | None = None,
    motif_line: str | None = None,
) -> tuple[tk.Frame, tk.Frame]:
    """固定大小面板壳 + 可滚动内容区。返回 (outer, scroll_inner)；内容放进 scroll_inner。

    默认不透明：Win32 半透明 layered 窗滚动长列表极易卡；需要玻璃感可显式 glass=True。
    """
    w, h = _fit_panel_wh(win, width, height)
    signs_dir = resolve_signs_dir(BUNDLE_DIR)
    shell = pack_panel_shell(win, bg=bg, signs_dir=signs_dir, padx=padx, pady=pady)
    inner_w = max(200, w - padx * 2 - 36)
    scroll_wrap, inner, _canvas = _make_scrollable_frame(
        shell,
        width=inner_w,
        height=max(160, h - pady * 2 - 20),
        bg=bg,
        motif=motif,
        motif_line=motif_line,
    )
    scroll_wrap.pack(fill=tk.BOTH, expand=True)
    try:
        setattr(win, "_panel_scroll_installed", True)
        setattr(win, "_panel_scroll_wrap", scroll_wrap)
        setattr(win, "_panel_scroll_inner", inner)
        setattr(win, "_vpet_panel_glass", bool(glass))
        setattr(win, "_panel_fixed_size", (w, h))
        if not glass:
            setattr(win, "_vpet_no_glass", True)
    except Exception:
        pass
    if glass:
        _try_set_window_alpha(win, PANEL_WINDOW_ALPHA)
    else:
        try:
            win.attributes("-alpha", 1.0)
        except Exception:
            pass
    return shell, inner


def _pack_guide_scroll_panel(
    win: tk.Misc,
    *,
    width: int = GUIDE_PANEL_W,
    height: int = GUIDE_PANEL_H,
    bg: str = MENU_BG,
) -> tuple[tk.Frame, tk.Frame, tk.Misc]:
    """操作指南专用：纵向滑轮；调用方填完内容后需 _finalize_guide_panel_layout。"""
    outer, inner = _pack_fixed_scroll_panel(win, width=width, height=height, bg=bg)
    scroll_wrap = getattr(win, "_panel_scroll_wrap", outer)
    return outer, inner, scroll_wrap


