def _weather_code_info(code: int) -> tuple[str, str]:
    """返回 (中文描述, 图标键)。"""
    c = int(code)
    if c == 0:
        return "晴朗", "sunny"
    if c in (1, 2):
        return "多云", "partly"
    if c == 3:
        return "阴天", "cloudy"
    if c in (45, 48):
        return "有雾", "fog"
    if c in (51, 53, 55, 56, 57):
        return "毛毛雨", "drizzle"
    if c in (61, 63, 65, 66, 67, 80, 81, 82):
        return "降雨", "rain"
    if c in (71, 73, 75, 77, 85, 86):
        return "降雪", "snow"
    if c in (95, 96, 99):
        return "雷暴", "storm"
    return "未知", "cloudy"


def _draw_pixel_weather_icon(kind: str, px: int = 48) -> Image.Image:
    """程序生成像素天气图标（NEAREST 放大，偏复古）。"""
    base = 16
    scale = max(1, px // base)
    img = Image.new("RGBA", (base, base), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    sky = (40, 56, 96, 255)
    sun = (255, 210, 72, 255)
    cloud = (220, 228, 240, 255)
    cloud_d = (160, 176, 200, 255)
    rain = (110, 180, 255, 255)
    snow = (240, 248, 255, 255)
    fog = (180, 190, 200, 180)
    bolt = (255, 230, 90, 255)

    def px_rect(x0, y0, x1, y1, fill) -> None:
        d.rectangle([x0, y0, x1, y1], fill=fill)

    if kind == "sunny":
        px_rect(6, 6, 10, 10, sun)
        for x, y in ((3, 3), (8, 2), (12, 3), (2, 8), (13, 8), (3, 12), (8, 13), (12, 12)):
            px_rect(x, y, x, y, sun)
    elif kind == "partly":
        px_rect(3, 3, 6, 6, sun)
        px_rect(5, 8, 13, 11, cloud)
        px_rect(7, 6, 11, 8, cloud)
        px_rect(4, 9, 6, 11, cloud_d)
    elif kind == "cloudy":
        px_rect(2, 8, 13, 12, cloud)
        px_rect(4, 5, 11, 8, cloud)
        px_rect(3, 10, 6, 12, cloud_d)
        px_rect(10, 9, 13, 12, cloud_d)
    elif kind == "fog":
        for y in (5, 8, 11):
            px_rect(2, y, 13, y + 1, fog)
    elif kind in ("drizzle", "rain"):
        px_rect(3, 4, 12, 8, cloud)
        px_rect(5, 2, 10, 4, cloud)
        step = 2 if kind == "drizzle" else 1
        for i, x in enumerate(range(4, 13, step + 1)):
            y0 = 9 + (i % 2)
            px_rect(x, y0, x, y0 + (1 if kind == "drizzle" else 3), rain)
    elif kind == "snow":
        px_rect(3, 4, 12, 8, cloud)
        px_rect(5, 2, 10, 4, cloud)
        for x, y in ((4, 10), (7, 11), (10, 10), (5, 13), (9, 13)):
            px_rect(x, y, x, y, snow)
            px_rect(x - 1, y, x + 1, y, snow)
            px_rect(x, y - 1, x, y + 1, snow)
    elif kind == "storm":
        px_rect(2, 3, 13, 8, cloud_d)
        px_rect(4, 1, 11, 3, cloud)
        px_rect(7, 8, 9, 10, bolt)
        px_rect(5, 10, 8, 11, bolt)
        px_rect(6, 11, 7, 14, bolt)
        for x in (3, 6, 10):
            px_rect(x, 9, x, 12, rain)
    else:
        px_rect(4, 6, 11, 11, cloud)

    # 淡底色方块，更像像素贴图
    out = Image.new("RGBA", (base, base), (*sky[:3], 40))
    out.alpha_composite(img)
    return out.resize((base * scale, base * scale), Image.NEAREST)


def _weather_icon_photo(kind: str, px: int = 48) -> ImageTk.PhotoImage:
    key = (kind, int(px))
    photo = _WEATHER_ICON_CACHE.get(key)
    if photo is None:
        photo = ImageTk.PhotoImage(_draw_pixel_weather_icon(kind, px))
        _WEATHER_ICON_CACHE[key] = photo
    return photo


def _fetch_open_meteo_weather(lat: float, lon: float, *, days: int = 7) -> dict:
    params = urllib.parse.urlencode(
        {
            "latitude": f"{lat:.4f}",
            "longitude": f"{lon:.4f}",
            "current": "temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m,apparent_temperature",
            "daily": "weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max",
            "timezone": "auto",
            "forecast_days": max(1, min(7, int(days))),
        }
    )
    url = f"https://api.open-meteo.com/v1/forecast?{params}"
    req = urllib.request.Request(url, headers={"User-Agent": "VpetWeather/1.0"})
    with urllib.request.urlopen(req, timeout=12) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
    data = json.loads(raw)
    if not isinstance(data, dict):
        raise ValueError("天气数据格式异常")
    return data


def _geocode_city_name(name: str) -> tuple[str, float, float] | None:
    q = (name or "").strip()
    if not q:
        return None
    if q in WEATHER_CITIES:
        lat, lon = WEATHER_CITIES[q]
        return q, lat, lon
    params = urllib.parse.urlencode({"name": q, "count": 1, "language": "zh", "format": "json"})
    url = f"https://geocoding-api.open-meteo.com/v1/search?{params}"
    req = urllib.request.Request(url, headers={"User-Agent": "VpetWeather/1.0"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        data = json.loads(resp.read().decode("utf-8", errors="replace"))
    results = data.get("results") if isinstance(data, dict) else None
    if not results:
        return None
    hit = results[0]
    label = str(hit.get("name") or q)
    admin = hit.get("admin1") or hit.get("country")
    if admin and str(admin) not in label:
        label = f"{label}·{admin}"
    return label[:18], float(hit["latitude"]), float(hit["longitude"])


def _format_pet_id(pet_id: int) -> str:
    s = f"{max(0, int(pet_id)):08d}"
    return f"{s[:4]} {s[4:]}"


def _allocate_local_pet_id() -> int:
    """仅本地递增（未配置全球服务时的后备，不做跨设备唯一保证）。"""
    registry: dict = {"next_id": 0}
    if PET_ID_REGISTRY_FILE.exists():
        try:
            data = json.loads(PET_ID_REGISTRY_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                registry = data
        except Exception:
            pass
    pet_id = int(registry.get("next_id", 0))
    registry["next_id"] = pet_id + 1
    PET_ID_REGISTRY_FILE.write_text(json.dumps(registry, ensure_ascii=False, indent=2), encoding="utf-8")
    return pet_id


def _fetch_cloud_pet_id(app_config: dict | None = None) -> dict | None:
    """联网按设备指纹自动领取/找回桌宠编号；失败返回 None。"""
    api = resolve_pet_id_api_url(app_config)
    if not api:
        return None
    machine_id = get_or_create_machine_id(DATA_DIR)
    try:
        result = register_pet_id(api, machine_id=machine_id)
        return {
            "pet_id": int(result["pet_id"]),
            "reclaimed": bool(result.get("reclaimed")),
            "via": "register",
        }
    except Exception:
        return None


def _normalize_profile_pet_id(data: dict) -> dict:
    pid = data.get("pet_id")
    if isinstance(pid, str):
        try:
            data["pet_id"] = int(pid.strip().replace(" ", ""))
        except ValueError:
            data["pet_id"] = None
    elif isinstance(pid, float):
        data["pet_id"] = int(pid)
    elif pid is not None and not isinstance(pid, int):
        data["pet_id"] = None
    return data


def _normalize_gift_pixels(raw) -> list[int]:
    """礼物像素画：一维色板下标，长度 GIFT_PIXEL_SIZE²。"""
    n = GIFT_PIXEL_SIZE * GIFT_PIXEL_SIZE
    max_idx = 23  # 基础色板 + 会话自选色
    out: list[int] = []
    if isinstance(raw, list):
        for i in range(n):
            try:
                v = int(raw[i]) if i < len(raw) else 0
            except Exception:
                v = 0
            out.append(max(0, min(max_idx, v)))
    else:
        out = [0] * n
    if len(out) < n:
        out.extend([0] * (n - len(out)))
    return out[:n]


def _gift_pixels_has_paint(cells: list[int] | None) -> bool:
    return any(int(c or 0) > 0 for c in (cells or ()))


def _gift_pixels_to_photo(cells: list[int], *, scale: int = 6) -> ImageTk.PhotoImage | None:
    if not _gift_pixels_has_paint(cells):
        return None
    scale = max(3, int(scale))
    side = GIFT_PIXEL_SIZE * scale
    img = Image.new("RGB", (side, side), (255, 0, 255))
    px = img.load()
    for y in range(GIFT_PIXEL_SIZE):
        for x in range(GIFT_PIXEL_SIZE):
            idx = int(cells[y * GIFT_PIXEL_SIZE + x] or 0)
            color = GIFT_PIXEL_PALETTE[idx] if 0 <= idx < len(GIFT_PIXEL_PALETTE) else None
            if not color:
                continue
            r = int(color[1:3], 16)
            g = int(color[3:5], 16)
            b = int(color[5:7], 16)
            for dy in range(scale):
                for dx in range(scale):
                    px[x * scale + dx, y * scale + dy] = (r, g, b)
    return ImageTk.PhotoImage(img)


def _load_pet_profile() -> dict:
    """加载桌宠档案（所属人 / 生日祝福 / 可选旧编号）。"""
    mid = get_or_create_machine_id(DATA_DIR)
    profile: dict = {}
    if PET_PROFILE_FILE.exists():
        try:
            data = json.loads(PET_PROFILE_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                profile = data
        except Exception:
            profile = {}

    profile.setdefault("records", {})
    profile.setdefault("machine_id", mid)
    profile.setdefault("created", datetime.now().strftime("%Y-%m-%d %H:%M"))
    # 所属人 / 生日
    if "owner_name" in profile and profile.get("owner_name") is not None:
        profile["owner_name"] = str(profile.get("owner_name") or "").strip()[:OWNER_NAME_MAX_LEN]
    else:
        profile["owner_name"] = ""
    profile.setdefault("owner_set_at", "")
    if "owner_welcome_done" not in profile:
        # 老存档已有所属人：视为欢迎过，避免升级后重复认主欢迎词
        profile["owner_welcome_done"] = bool(str(profile.get("owner_name") or "").strip())
    else:
        profile["owner_welcome_done"] = bool(profile.get("owner_welcome_done"))
    profile.setdefault("last_launch_at", "")
    profile.setdefault("bless_month", 0)
    profile.setdefault("bless_day", 0)
    profile.setdefault("bless_message", "")
    profile.setdefault("gift_text", "")
    profile["gift_pixels"] = _normalize_gift_pixels(profile.get("gift_pixels"))
    profile.setdefault("active_gift_art_id", "")
    profile.setdefault("last_owner_bday_ymd", "")
    profile.setdefault("last_pet_bday_ymd", "")
    profile.setdefault("last_pet_bday_nudge_ymd", "")
    profile.setdefault("wear_flower", False)
    profile["wear_flower"] = bool(profile.get("wear_flower"))
    profile["outfit_decors"] = pet_outfit.normalize_decors(profile.get("outfit_decors"))

    if PET_ID_FEATURE:
        profile = _normalize_profile_pet_id(profile)
        app_cfg = _load_app_config()
        if profile.get("pet_id") is not None:
            stored_mid = str(profile.get("machine_id") or "")
            if stored_mid and stored_mid != mid:
                profile["pet_id_source"] = profile.get("pet_id_source") or "shared"
                profile["pet_id_shared_from"] = stored_mid
                profile["pet_id_pending"] = False
            else:
                cloud = _fetch_cloud_pet_id(app_cfg)
                if cloud and cloud.get("pet_id") is not None:
                    profile["pet_id"] = int(cloud["pet_id"])
                    profile["pet_id_source"] = "cloud"
                    profile["pet_id_pending"] = False
                    if cloud.get("reclaimed"):
                        profile["pet_id_reclaimed"] = True
                elif not profile.get("pet_id_source"):
                    profile["pet_id_source"] = "local"
            profile["machine_id"] = mid
        else:
            cloud = _fetch_cloud_pet_id(app_cfg)
            if cloud and cloud.get("pet_id") is not None:
                profile["pet_id"] = int(cloud["pet_id"])
                profile["pet_id_source"] = "cloud"
                profile["pet_id_pending"] = False
                if cloud.get("reclaimed"):
                    profile["pet_id_reclaimed"] = True
            else:
                profile["pet_id"] = _allocate_local_pet_id()
                profile["pet_id_source"] = "local"
                profile["pet_id_pending"] = bool(resolve_pet_id_api_url(app_cfg))
            profile["machine_id"] = mid

    _save_pet_profile(profile)
    return profile


def _save_pet_profile(profile: dict) -> None:
    PET_PROFILE_FILE.parent.mkdir(parents=True, exist_ok=True)
    PET_PROFILE_FILE.write_text(json.dumps(profile, ensure_ascii=False, indent=2), encoding="utf-8")


def _owner_display_name(profile: dict | None) -> str:
    name = str((profile or {}).get("owner_name") or "").strip()
    return name[:OWNER_NAME_MAX_LEN]


def _pet_birthday_ordinal(profile: dict) -> int:
    """所属人登记后，一起过的第几个桌宠生日（至少为 1）。"""
    raw = str(profile.get("owner_set_at") or profile.get("created") or "")
    try:
        start = datetime.strptime(raw[:10], "%Y-%m-%d")
    except Exception:
        start = datetime.now()
    now = datetime.now()
    first = datetime(start.year, PET_BIRTHDAY_MONTH, PET_BIRTHDAY_DAY)
    if first.date() < start.date():
        first = datetime(start.year + 1, PET_BIRTHDAY_MONTH, PET_BIRTHDAY_DAY)
    if now.date() < first.date():
        return 1
    return max(1, now.year - first.year + 1)


def _normalize_md(month: int, day: int) -> tuple[int, int] | None:
    try:
        m, d = int(month), int(day)
    except Exception:
        return None
    if not (1 <= m <= 12 and 1 <= d <= 31):
        return None
    # 粗校验：用今年拼日期，非法则失败
    try:
        datetime(datetime.now().year, m, d)
    except ValueError:
        try:
            datetime(datetime.now().year + 1 if m == 2 else datetime.now().year, m, d)
        except ValueError:
            return None
    return m, d


def _format_md(month: int, day: int) -> str:
    return f"{int(month)}月{int(day)}日"


