    def _ensure_first_play_guide(self, key: str, on_continue, *, on_show=None) -> None:
        """首次进入某玩法：用 toast 提示要点（不用弹窗文本框）；完整说明见 F1。"""
        hint_key = f"first_play:{key}"
        if self._hint_seen(hint_key):
            on_continue()
            return
        info = FIRST_PLAY_GUIDES.get(key) or GUIDE_TOPICS.get(key)
        if not info:
            self._mark_hint_seen(hint_key)
            on_continue()
            return
        if not DEMO_ALWAYS_SHOW_GUIDES:
            self._mark_hint_seen(hint_key)
        title = str(info.get("title", "操作提示"))
        body = str(info.get("body", "")).strip()
        # toast 只取前几行要点，避免大段说明占文本框
        lines = [ln.strip() for ln in body.replace("\r", "").split("\n") if ln.strip()]
        tip = " · ".join(lines[:3])
        if len(tip) > 96:
            tip = tip[:94] + "…"
        self._show_toast(f"{title}\n{tip}\n（完整说明见 F1）", "#88ccff", duration_ms=4200)
        if on_show:
            try:
                on_show()
            except Exception:
                pass
        on_continue()

    def _poll_hotkey(self) -> None:
        if not self._alive():
            self._hotkey_polling = False
            return
        # 物理键兜底：即使 RegisterHotKey 失败/启动卡住也能强制退出
        self._poll_force_quit_chord()
        self._poll_display_power_messages()
        if self.hotkey_ids:
            msg = wintypes.MSG()
            # hwnd=0：取本线程全部 WM_HOTKEY（Tk 窗口句柄有时对不上）
            while ctypes.windll.user32.PeekMessageW(
                ctypes.byref(msg), 0, WM_HOTKEY, WM_HOTKEY, 1
            ):
                if msg.message == WM_HOTKEY:
                    for hotkey_id, _key, action in HOTKEY_ACTIONS:
                        if msg.wParam == hotkey_id:
                            self._handle_hotkey_action(action)
                            break
        self._safe_after(120, self._poll_hotkey)

    def _alive(self) -> bool:
        if self._closing:
            return False
        try:
            return self.root.winfo_exists()
        except tk.TclError:
            return False

    def _cancel_timer_job(self, attr: str) -> None:
        job = getattr(self, attr, None)
        if not job:
            return
        try:
            self.root.after_cancel(job)
        except Exception:
            pass
        setattr(self, attr, None)

    def _safe_after(self, ms: int, fn) -> str | None:
        if not self._alive():
            return None

        def wrapped() -> None:
            if not self._alive():
                return
            try:
                fn()
            except tk.TclError:
                pass

        try:
            return self.root.after(ms, wrapped)
        except tk.TclError:
            return None

    def _cancel_follow_chain(self) -> None:
        self.follow_animating = False
        self._cancel_timer_job("follow_tick_job")
        self._cancel_timer_job("follow_anim_job")

    def _schedule_follow_tick(self, ms: int | None = None) -> None:
        if ms is None:
            ms = FOLLOW_MOVE_INTERVAL_MS
        self._cancel_timer_job("follow_tick_job")
        if self.mode != "follow" or not self._alive():
            return
        self.follow_tick_job = self._safe_after(ms, self._follow_tick)

    def _place_window(self, *, light: bool = False) -> None:
        display_y = self.y + self.click_bounce_offset + int(getattr(self, "happy_bounce_offset", 0) or 0)
        self.root.geometry(f"{self.display_size}x{self.display_size}+{self.x}+{display_y}")
        # 拖动/走动：只做轻量位置更新，避免每帧重排一层特效导致卡顿
        self._reposition_pet_attached_popups(force=False)
        self._place_head_flower()
        self._place_outfit_layer()
        if light:
            return
        self._place_ai_chat()
        self._place_interact_fx()
        self._place_music_wave()
        self._place_happy_fx()
        self._place_rain_fx()
        self._place_bulb_fx()
        self._place_food_fx()
        self._place_shy_fx()
        self._place_like_fx()
        self._place_wink_fx()
        self._place_bixin_fx()
        self._place_follow_dizzy_fx()
        self._place_all_mini_pet_waves()
        self._sync_all_mini_pet_bg_fx(place_only=True)
        self._place_wait_hint()
        self._lift_pet_above_bg_fx()

    def _peer_presence_path(self) -> Path:
        return PEER_PRESENCE_DIR / f"{self._peer_instance_id}.json"

    def _publish_peer_presence(self) -> None:
        try:
            display_y = int(self.y + self.click_bounce_offset)
            key = (int(self.x), display_y, int(self.display_size))
            now_ms = int(time.time() * 1000)
            last = getattr(self, "_peer_presence_last", None)
            # 位置未变则最多 2s 写一次盘，减轻多开轮询卡顿
            if (
                isinstance(last, tuple)
                and len(last) == 2
                and last[0] == key
                and (now_ms - int(last[1] or 0)) < 2000
            ):
                return
            PEER_PRESENCE_DIR.mkdir(parents=True, exist_ok=True)
            payload = {
                "id": self._peer_instance_id,
                "pid": os.getpid(),
                "x": key[0],
                "y": key[1],
                "size": key[2],
                "ts": now_ms,
            }
            self._peer_presence_path().write_text(
                json.dumps(payload, ensure_ascii=False),
                encoding="utf-8",
            )
            self._peer_presence_last = (key, now_ms)
        except Exception:
            pass

    def _clear_peer_presence(self) -> None:
        try:
            path = self._peer_presence_path()
            if path.is_file():
                path.unlink()
        except Exception:
            pass

    def _save_achievements_soon(self, delay_ms: int = 900) -> None:
        """合并短时间内的成就写盘，减轻卡顿。"""
        # 工作运送热路径再拉长合并窗口，避免到站频繁落盘
        if self.state == "work":
            delay_ms = max(int(delay_ms), 1600)
        job = getattr(self, "_achievements_save_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        self._achievements_save_job = self.root.after(
            max(120, int(delay_ms)), self._flush_achievements_save
        )

    def _flush_achievements_save(self) -> None:
        self._achievements_save_job = None
        if self._closing:
            return
        try:
            _save_achievements(self.achievements)
        except Exception:
            pass

    def _note_user_activity(self) -> None:
        self._last_user_activity_ms = int(time.time() * 1000)

    def _install_display_power_watch(self) -> None:
        """订阅显示器亮/灭/变暗（Win8+），供「屏幕暗了」类 meta 使用。"""
        if sys.platform != "win32" or self._closing:
            return
        if self._display_power_notify:
            return
        try:
            hwnd = int(self.root.winfo_id())
            hwnd = int(ctypes.windll.user32.GetAncestor(hwnd, 2) or hwnd)
        except Exception:
            return

        class _GUID(ctypes.Structure):
            _fields_ = [
                ("Data1", wintypes.DWORD),
                ("Data2", wintypes.WORD),
                ("Data3", wintypes.WORD),
                ("Data4", wintypes.BYTE * 8),
            ]

        def _parse_guid(text: str) -> _GUID:
            from uuid import UUID

            raw = UUID(text)
            g = _GUID()
            g.Data1 = raw.time_low
            g.Data2 = raw.time_mid
            g.Data3 = raw.time_hi_version
            for i, b in enumerate(raw.bytes[8:]):
                g.Data4[i] = b
            return g

        user32 = ctypes.windll.user32
        for guid_s in (_GUID_CONSOLE_DISPLAY_STATE, _GUID_SESSION_DISPLAY_STATUS):
            try:
                g = _parse_guid(guid_s)
                handle = user32.RegisterPowerSettingNotification(hwnd, ctypes.byref(g), 0)
                if handle:
                    self._display_power_notify.append(handle)
            except Exception:
                pass
        # 保证热键轮询在跑（顺带抽电源消息）
        if not getattr(self, "_hotkey_polling", False):
            self._hotkey_polling = True
            self.root.after(80, self._poll_hotkey)

    def _uninstall_display_power_watch(self) -> None:
        if sys.platform != "win32":
            self._display_power_notify = []
            return
        user32 = ctypes.windll.user32
        for handle in list(self._display_power_notify):
            try:
                user32.UnregisterPowerSettingNotification(handle)
            except Exception:
                pass
        self._display_power_notify = []

    def _set_display_power_state(self, state: int) -> None:
        """state: 0=灭 1=亮 2=变暗。"""
        try:
            state = int(state)
        except Exception:
            return
        if state not in (0, 1, 2):
            return
        prev = int(getattr(self, "_display_power_state", 1) or 1)
        self._display_power_state = state
        now = int(time.time() * 1000)
        if state in (0, 2):
            if prev == 1 or not int(getattr(self, "_display_dark_since_ms", 0) or 0):
                self._display_dark_since_ms = now
        else:
            self._display_dark_since_ms = 0

    def _poll_display_power_messages(self) -> None:
        if sys.platform != "win32" or not self._display_power_notify:
            return
        try:
            msg = wintypes.MSG()
            while ctypes.windll.user32.PeekMessageW(
                ctypes.byref(msg), 0, WM_POWERBROADCAST, WM_POWERBROADCAST, 1
            ):
                if int(msg.message) != WM_POWERBROADCAST:
                    continue
                if int(msg.wParam) != PBT_POWERSETTINGCHANGE:
                    continue
                if not msg.lParam:
                    continue
                # POWERBROADCAST_SETTING: GUID(16) + DataLength(4) + Data…
                try:
                    data_len = ctypes.c_uint32.from_address(int(msg.lParam) + 16).value
                    if data_len < 1:
                        continue
                    data = ctypes.c_uint8.from_address(int(msg.lParam) + 20).value
                    self._set_display_power_state(int(data))
                except Exception:
                    pass
        except Exception:
            pass

    def _is_screensaver_running(self) -> bool:
        if sys.platform != "win32":
            return False
        try:
            flag = ctypes.c_int(0)
            ok = ctypes.windll.user32.SystemParametersInfoW(
                SPI_GETSCREENSAVERRUNNING, 0, ctypes.byref(flag), 0
            )
            return bool(ok) and bool(flag.value)
        except Exception:
            return False

    def _is_display_darkish(self) -> bool:
        """屏幕灭/变暗/屏保：才允许「屏幕暗了」类 meta。"""
        if self._is_screensaver_running():
            return True
        return int(getattr(self, "_display_power_state", 1) or 1) in (0, 2)

    def _meta_banter_state(self) -> dict:
        stats = self.achievements.setdefault("stats", {})
        state = stats.get("meta_banter")
        if not isinstance(state, dict):
            state = {"last_ms": 0, "event_last": {}, "used": {}}
            stats["meta_banter"] = state
        if not isinstance(state.get("event_last"), dict):
            state["event_last"] = {}
        if not isinstance(state.get("used"), dict):
            state["used"] = {}
        return state

    def _meta_banter_allowed(self, *, allow_dragging: bool = False) -> bool:
        if self._closing or not getattr(self, "_startup_ready", False):
            return False
        if self.mode == "loading":
            return False
        if self.dragging and not allow_dragging:
            return False
        if self.state == "action":
            return False
        if self.speech_dialog and self.speech_dialog.winfo_exists():
            return False
        if getattr(self, "voice_subtitle_win", None) and self._voice_subtitle_active:
            try:
                if self.voice_subtitle_win.winfo_exists() and not self._win_is_withdrawn(self.voice_subtitle_win):
                    return False
            except Exception:
                pass
        return True

    def _pick_meta_banter_line(self, event: str) -> str | None:
        lines = META_BANTER_LINES.get(event) or ()
        if not lines:
            return None
        state = self._meta_banter_state()
        used_map = state.setdefault("used", {})
        used = [str(x) for x in (used_map.get(event) or []) if str(x)]
        unused = [ln for ln in lines if ln not in used]
        if not unused:
            used = []
            unused = list(lines)
        line = random.choice(unused)
        used.append(line)
        used_map[event] = used
        return line

    def _maybe_meta_banter(self, event: str, *, chance: float | None = None) -> bool:
        """低频 meta 台词；全局冷却 + 事件冷却；同句不重复。"""
        if event not in META_BANTER_LINES:
            return False
        # 「屏幕暗了」类：亮屏绝不触发
        if event == "idle_long" and not self._is_display_darkish():
            return False
        allow_drag = event == "drag_long"
        if not self._meta_banter_allowed(allow_dragging=allow_drag):
            return False
        roll = META_BANTER_CHANCE.get(event, 0.3) if chance is None else float(chance)
        if random.random() >= max(0.0, min(1.0, roll)):
            return False
        now = int(time.time() * 1000)
        state = self._meta_banter_state()
        if now - int(state.get("last_ms") or 0) < META_BANTER_GLOBAL_COOLDOWN_MS:
            return False
        event_last = state.setdefault("event_last", {})
        ev_cd = int(META_BANTER_EVENT_COOLDOWN_MS.get(event, 180_000))
        if now - int(event_last.get(event) or 0) < ev_cd:
            return False
        line = self._pick_meta_banter_line(event)
        if not line:
            return False
        state["last_ms"] = now
        event_last[event] = now
        try:
            self._save_achievements_soon()
        except Exception:
            pass
        self._show_speech_dialog(line, auto_hide_ms=2800, use_border5=False)
        return True

    def _start_meta_idle_poll(self) -> None:
        if self._closing or not getattr(self, "_startup_ready", False):
            return
        if self._meta_idle_job:
            return
        self._meta_idle_tick()

    def _stop_meta_idle_poll(self) -> None:
        if self._meta_idle_job:
            try:
                self.root.after_cancel(self._meta_idle_job)
            except Exception:
                pass
            self._meta_idle_job = None

    def _meta_idle_tick(self) -> None:
        self._meta_idle_job = None
        if self._closing or not self._alive():
            return
        try:
            # 屏保也算暗
            if self._is_screensaver_running() and int(getattr(self, "_display_power_state", 1) or 1) == 1:
                if not int(getattr(self, "_display_dark_since_ms", 0) or 0):
                    self._display_dark_since_ms = int(time.time() * 1000)
            now = int(time.time() * 1000)
            # 仅屏幕灭/变暗/屏保后触发；亮屏不因「闲置」乱说「屏幕暗了」
            if self._is_display_darkish():
                dark_since = int(getattr(self, "_display_dark_since_ms", 0) or 0)
                if dark_since <= 0:
                    self._display_dark_since_ms = now
                    dark_since = now
                if now - dark_since >= META_BANTER_DARK_HOLD_MS:
                    if self._maybe_meta_banter("idle_long", chance=0.72):
                        # 说过一次后推迟下一次，避免暗屏期间连催
                        self._display_dark_since_ms = now
        except Exception:
            pass
        self._meta_idle_job = self._safe_after(META_BANTER_IDLE_CHECK_MS, self._meta_idle_tick)

    def _is_at_screen_edge(self, *, margin: int = 4) -> bool:
        sw, sh = self._screen_wh()
        return (
            self.x <= margin
            or self.y <= margin
            or self.x >= sw - self.display_size - margin
            or self.y >= sh - self.display_size - margin
        )

    def _stop_peer_meet_poll(self) -> None:
        if self._peer_meet_job:
            try:
                self.root.after_cancel(self._peer_meet_job)
            except Exception:
                pass
            self._peer_meet_job = None
        self._clear_peer_presence()

    def _start_peer_meet_poll(self) -> None:
        if self._closing or not getattr(self, "_startup_ready", False):
            return
        if self._peer_meet_job:
            return
        self._peer_meet_tick()

    def _peer_meet_allowed(self) -> bool:
        if self._closing or not getattr(self, "_startup_ready", False):
            return False
        if self.dragging:
            return False
        if self.mode in ("loading", "game"):
            return False
        if self.state == "action":
            return False
        if self.speech_dialog and self.speech_dialog.winfo_exists():
            return False
        return True

    def _peer_meet_tick(self) -> None:
        self._peer_meet_job = None
        if self._closing or not self._alive():
            self._clear_peer_presence()
            return
        self._publish_peer_presence()
        try:
            self._maybe_trigger_peer_meet()
        except Exception:
            pass
        self._peer_meet_job = self._safe_after(PEER_MEET_POLL_MS, self._peer_meet_tick)

    def _maybe_trigger_peer_meet(self) -> None:
        if not self._peer_meet_allowed():
            return
        now = int(time.time() * 1000)
        if now - int(self._peer_meet_last_ms or 0) < PEER_MEET_COOLDOWN_MS:
            return
        if not PEER_PRESENCE_DIR.is_dir():
            return
        ax, ay = int(self.x), int(self.y + self.click_bounce_offset)
        asz = int(self.display_size)
        for path in list(PEER_PRESENCE_DIR.glob("*.json")):
            if path.name == f"{self._peer_instance_id}.json":
                continue
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                continue
            if not isinstance(data, dict):
                continue
            ts = int(data.get("ts") or 0)
            if now - ts > PEER_STALE_MS:
                try:
                    path.unlink()
                except Exception:
                    pass
                continue
            bx = int(data.get("x") or 0)
            by = int(data.get("y") or 0)
            bsz = max(16, int(data.get("size") or asz))
            # 略放宽容差：靠近也算相遇
            pad = max(8, min(asz, bsz) // 6)
            if not self._rects_overlap(
                ax - pad, ay - pad, asz + pad * 2, asz + pad * 2,
                bx - pad, by - pad, bsz + pad * 2, bsz + pad * 2,
            ):
                continue
            self._peer_meet_last_ms = now
            if self._maybe_meta_banter("peer_meet"):
                return
            line = random.choice(PEER_MEET_LINES)
            self._show_speech_dialog(line, auto_hide_ms=2800, use_border5=False)
            return

    def _screen_wh(self) -> tuple[int, int]:
        now = time.time()
        if now - getattr(self, "_screen_cache_ts", 0) > 1.5:
            try:
                self._screen_w = int(self.root.winfo_screenwidth())
                self._screen_h = int(self.root.winfo_screenheight())
            except Exception:
                self._screen_w = getattr(self, "_screen_w", 1280)
                self._screen_h = getattr(self, "_screen_h", 720)
            self._screen_cache_ts = now
        return int(getattr(self, "_screen_w", 1280)), int(getattr(self, "_screen_h", 720))

    def _raise_speech_popups(self) -> None:
        """文本框压在桌宠/伴侣之下；轻量压层，避免全量 restack 频闪。"""
        self._stack_speech_under_sprites()

    def _iter_bg_fx_windows(self) -> list[tk.Misc]:
        """氛围/光圈/加载等「应处于桌宠后方」的窗口。"""
        names = (
            "interact_fx_win",
            "like_fx_win",
            "shy_fx_win",
            "wink_fx_win",
            "rain_fx_win",
            "happy_fx_win",
            "food_fx_win",
            "gift_pixel_fx_win",
            "music_wave_win",
            "bulb_fx_win",
            "follow_dizzy_fx_win",
            "companion_loading_win",
            "sleep_zzz_win",
            "sleep_end_btn_win",
            # 头顶花不在此列：须压在立绘之上，见 _lift_head_flower_above_pet
            # 工作道具单独由 _stack_work_props_under_pet 排层，避免与 restack 互抢闪屏
        )
        out: list[tk.Misc] = []
        for name in names:
            win = getattr(self, name, None)
            try:
                if win is not None and win.winfo_exists():
                    out.append(win)
            except Exception:
                pass
        for box in list(getattr(self, "game_boxes", []) or []):
            win = box.get("win") if isinstance(box, dict) else None
            try:
                if win is not None and win.winfo_exists():
                    out.append(win)
            except Exception:
                pass
        for entry in list(getattr(self, "mini_pets", []) or []):
            for key in ("bg_fx_win", "wave_win"):
                win = entry.get(key)
                try:
                    if win is not None and win.winfo_exists():
                        out.append(win)
                except Exception:
                    pass
        return out

    def _lift_wins(self, wins: list[tk.Misc | None]) -> None:
        for win in wins:
            if win is None:
                continue
            try:
                if win.winfo_exists():
                    win.lift()
            except Exception:
                pass

    def _companion_fx_wins(self) -> list[tk.Misc]:
        out: list[tk.Misc] = []
        for entry in list(getattr(self, "mini_pets", []) or []):
            if not isinstance(entry, dict):
                continue
            for key in ("bg_fx_win", "wave_win", "happy_win", "rain_win", "bulb_win", "shy_win", "like_win", "wink_win"):
                w = entry.get(key)
                try:
                    if w is not None and w.winfo_exists():
                        out.append(w)
                except Exception:
                    pass
        return out

    def _companion_sprite_wins(self) -> list[tk.Misc]:
        out: list[tk.Misc] = []
