        tk.Button(
            frame,
            text="全曲",
            command=lambda: start(0),
            font=PIXEL_FONT,
            bg=MENU_ACTIVE,
            fg=MENU_FG,
            relief=tk.FLAT,
            padx=12,
            pady=4,
        ).pack(fill=tk.X, pady=2)
        tk.Button(
            frame,
            text="90 秒",
            command=lambda: start(RHYTHM_SHORT_CAP_MS),
            font=PIXEL_FONT,
            bg=MENU_ACTIVE,
            fg=MENU_FG,
            relief=tk.FLAT,
            padx=12,
            pady=4,
        ).pack(fill=tk.X, pady=2)
        self._chrome_icon_btn(frame, "cancel", close_win).pack(anchor=tk.E, pady=(6, 0))
        win.protocol("WM_DELETE_WINDOW", close_win)
        self._place_panel_popup(win)
        try:
            win.lift()
            win.focus_force()
        except Exception:
            pass
        self._raise_interactive_panels()

