    def _open_vocab_notebook_menu(self) -> None:
        book = _load_vocab_notebook()
        items: list[tuple[str, callable]] = []
        for lang in ("中文", "英语", "日语"):
            n = len(book.get(lang, []))
            items.append((f"{lang}（{n}）", lambda L=lang: self._open_vocab_notebook(L)))
        self._show_sub_menu(items, offset_x=180)

    def _close_vocab_notebook(self) -> None:
        if self.vocab_notebook_win and self.vocab_notebook_win.winfo_exists():
            self.vocab_notebook_win.destroy()
        self.vocab_notebook_win = None

    def _open_vocab_notebook(self, lang: str) -> None:
        self._hide_main_menu()
        self._close_vocab_notebook()
        book = _load_vocab_notebook()
        rows = list(book.get(lang, []))
        win = tk.Toplevel(self.root)
        self.vocab_notebook_win = win
        win.title(f"生词本 · {lang}")
        self._apply_window_layer(win)
        win.configure(bg=MENU_BG)
        win.protocol("WM_DELETE_WINDOW", self._close_vocab_notebook)
        w, h = _fit_panel_wh(win, PANEL_FIXED_W, PANEL_FIXED_H)
        frame = tk.Frame(win, bg=MENU_BG, padx=10, pady=8)
        frame.pack(fill=tk.BOTH, expand=True)
        tk.Label(frame, text=f"生词本 · {lang}（{len(rows)}）", font=PIXEL_FONT, fg=PIXEL_COLOR, bg=MENU_BG).pack(
            anchor=tk.W
        )
        tk.Label(
            frame,
            text="答错会自动收录；复习答对后移出。",
            font=PIXEL_FONT,
            fg="#888888",
            bg=MENU_BG,
        ).pack(anchor=tk.W, pady=(2, 6))

        btns = tk.Frame(frame, bg=MENU_BG)
        btns.pack(fill=tk.X, pady=(0, 6))

        def review() -> None:
            if not rows:
                self._show_toast("生词本是空的", "#ff8844")
                return
            self._close_vocab_notebook()
            self._open_vocab_game(lang, pool=rows, from_notebook=True)

        def clear_all() -> None:
            _clear_vocab_notebook_lang(lang)
            self._show_toast(f"已清空{lang}生词本", "#88ccff")
            self._open_vocab_notebook(lang)

        tk.Button(btns, text="复习", command=review, font=PIXEL_FONT, bg="#334466", fg="#ffcc66", relief=tk.FLAT).pack(
            side=tk.LEFT, padx=(0, 6)
        )
        tk.Button(btns, text="清空", command=clear_all, font=PIXEL_FONT, bg="#553333", fg="#ffaaaa", relief=tk.FLAT).pack(
            side=tk.LEFT
        )

        scroll_wrap, inner, _canvas = _make_scrollable_frame(
            frame, width=max(200, w - 48), height=max(160, h - 120), bg=MENU_BG
        )
        scroll_wrap.pack(fill=tk.BOTH, expand=True)
        setattr(win, "_panel_scroll_installed", True)
        if not rows:
            tk.Label(inner, text="（暂无生词）", font=PIXEL_FONT, fg="#666666", bg=MENU_BG).pack(anchor=tk.W, pady=8)
        else:
            for item in rows:
                row = tk.Frame(inner, bg=MENU_BG)
                row.pack(fill=tk.X, pady=3)
                txt = f"{item.get('word', '')}\n{item.get('meaning', '')}"
                tk.Label(
                    row,
                    text=txt,
                    font=PIXEL_FONT,
                    fg=MENU_FG,
                    bg=MENU_BG,
                    justify=tk.LEFT,
                    wraplength=240,
                    anchor=tk.W,
                ).pack(side=tk.LEFT, fill=tk.X, expand=True)

                def remove_one(w=str(item.get("word", "")), L=lang) -> None:
                    _remove_vocab_notebook_item(L, w)
                    self._open_vocab_notebook(L)

                tk.Button(
                    row,
                    text="删",
                    command=remove_one,
                    font=PIXEL_FONT,
                    bg="#444444",
                    fg=MENU_FG,
                    relief=tk.FLAT,
                    padx=4,
                ).pack(side=tk.RIGHT, padx=(4, 0))
        self._place_panel_popup(win)

    def _toggle_music_mode(self) -> None:
        self._toggle_music_interact()

    def _food_inventory_total(self) -> int:
        return sum(self.food_inventory.values())

    def _format_food_counts(self, counts: dict[str, int]) -> str:
        parts = [f"{FOODS[fid]['label']}×{cnt}" for fid, cnt in counts.items() if cnt > 0 and fid in FOODS]
        return "  ".join(parts) if parts else "无"

    def _add_food_to_inventory(self, food_id: str, amount: int = 1) -> None:
        if food_id not in FOODS:
            return
        self.food_inventory[food_id] = self.food_inventory.get(food_id, 0) + amount
        self.game_session_food[food_id] = self.game_session_food.get(food_id, 0) + amount
        self._persist_food_inventory()
        self._refresh_panel()

    def _exit_to_free(self, _event=None) -> None:
        """按 Esc 退出游戏/AI 对话/日程/互动等，回到自由模式。"""
        self._cancel_pending_mode_switch()
        self._hide_main_menu()
        self._hide_toast()
        self._close_ai_chat()
        if self.preset_dialog_job:
            try:
                self.root.after_cancel(self.preset_dialog_job)
            except Exception:
                pass
            self.preset_dialog_job = None
        if self.schedule_win and self.schedule_win.winfo_exists():
            self.schedule_win.destroy()
            self.schedule_win = None
        self._close_home()
        for attr in (
            "diary_win",
            "weather_win",
            "music_track_picker_win",
            "gallery_win",
            "home_win",
            "panel_backpack_win",
            "phonograph_win",
            "typing_game_win",
            "vocab_game_win",
            "vocab_notebook_win",
            "panel_settings_win",
            "about_win",
            "feedback_win",
            "creator_hub_win",
            "creator_upload_win",
            "creator_intro_win",
            "rhyme_fight_win",
            "operation_guide_win",
            "work_custom_win",
            "leaderboard_win",
            "rhythm_win",
        ):
            win = getattr(self, attr, None)
            if win and win.winfo_exists():
                win.destroy()
            setattr(self, attr, None)
        self._settings_ui = None
        self.gallery_photos.clear()
        self._stop_phonograph_playback()
        self._phonograph_refresh = None
        self._close_rhyme_fight(resume=False)
        self._close_typing_game(resume=False)
        self._close_vocab_game(resume=False)
        self._close_rhythm_game(resume=False)
        self._hide_speech_dialog()
        self._hide_voice_subtitle()
        self._stop_call_audio()
        self._cancel_action_end()
        self._cancel_idle_chain()
        self.sleep_interact_active = False
        self._hide_size_loading()
        self._hide_companion_loading()
        self._hide_food_fx()
        self._hide_happy_fx()
        # 装扮 / 头顶花佩戴常驻，不随 Esc 清场销毁（回自由后再 sync）
        self._hide_rain_fx()
        self._hide_bulb_fx()
        self._hide_game_clear()
        self._cancel_expose_qte()
        self._cancel_yesno_overlay()
        self._cancel_food_drag()
        self._hide_interact_fx()
        self._hide_like_fx()
        self._hide_shy_fx()
        self._hide_wink_fx()
        self._hide_bixin_fx()
        self._hide_follow_dizzy_fx()
        self._stop_music_wave_fx()
        self.music_sprite_mode = False
        self.music_ambient_only = False
        self._stop_bg_music()
        self._sync_voice_player()
        if self.angry_anim_job:
            self.root.after_cancel(self.angry_anim_job)
            self.angry_anim_job = None
        was_game = self.mode == "game"
        if self.mode == "game":
            caught = self.game_catches
            session_food = dict(self.game_session_food)
            self._stop_game_mode()
            if caught > 0:
                detail = self._format_food_counts(session_food)
                toast = f"已回到自由模式\n本局获得 {caught} 个食物\n{detail}"
            else:
                toast = "已回到自由模式"
        elif self.mode == "quiet":
            self._leave_quiet_mode()
            toast = "已回到自由模式"
        elif self.mode == "follow":
            self.follow_animating = False
            toast = "已回到自由模式"
        elif self.mode == "work":
            toast = "已回到自由模式"
        else:
            toast = "已回到自由模式"
        if self.state == "work":
            self._stop_work_mode()
        if self.state == "sleep":
            self._wake_from_sleep()
        if self.state == "action":
            self.action_name = ""
        self.mode = "free"
        self.state = "stand"
        self._set_image(self.sprites.stand)
        self._place_window()
        self._sync_outfit_layer(force_redraw=True)
        if self._wearing_flower():
            self._show_head_flower()
        self._sync_mode_time_bucket()
        self._show_toast(toast, PIXEL_COLOR, duration_ms=3500 if was_game else 2000)
        self._resume_idle()

    def _clear_mini_pet_fx_for_gather(self) -> None:
        """采集时伴侣仍可见跟随，但不同步晕眩等氛围特效（避免像双人一起晕）。"""
        for entry in list(getattr(self, "mini_pets", []) or []):
            entry["gather_hidden"] = False
            self._stop_mini_pet_bg_fx(entry)
            win = entry.get("win")
            try:
                if win is not None and win.winfo_exists():
                    win.deiconify()
            except Exception:
                pass

    def _restore_mini_pets_after_gather(self) -> None:
        for entry in list(getattr(self, "mini_pets", []) or []):
            entry["gather_hidden"] = False
            win = entry.get("win")
            try:
                if win is not None and win.winfo_exists():
                    win.deiconify()
            except Exception:
                pass
            try:
                self._mini_pet_follow_tick(entry)
            except Exception:
                pass

    def _stop_game_mode(self) -> None:
        if self.game_spawn_job:
            self.root.after_cancel(self.game_spawn_job)
            self.game_spawn_job = None
        if self.game_tick_job:
            self.root.after_cancel(self.game_tick_job)
            self.game_tick_job = None
        for box in self.game_boxes:
            if box.get("win") and box["win"].winfo_exists():
                box["win"].destroy()
        self.game_boxes.clear()
        self._end_game_dizzy_stun()
        if self.game_hud_win and self.game_hud_win.winfo_exists():
            self.game_hud_win.destroy()
        self.game_hud_win = None
        self.game_hud_label = None
        self.game_overlay = None
        self.game_canvas = None
        self._restore_mini_pets_after_gather()

    def _ensure_mode_exclusive_cleanup(self, target: str) -> None:
        """工作/采集互斥：进入一方前硬停另一方并清残留窗口。"""
        self._cancel_game_countdown()
        if target in ("work", "game"):
            if self.mode == "game" or self.game_boxes or self.game_spawn_job or self.game_tick_job:
                self._stop_game_mode()
            if target == "game" and (self.mode == "work" or self.state == "work"):
                self._stop_work_mode()
            if target == "work" and self.mode == "game":
                self._stop_game_mode()
        if target == "work" and self.state == "work" and self.mode != "work":
            self._stop_work_mode()

    def _cancel_work_loops(self) -> None:
        for attr in ("work_move_job", "work_anim_job", "_work_boot_job"):
            job = getattr(self, attr, None)
            if job:
                try:
                    self.root.after_cancel(job)
                except Exception:
                    pass
                setattr(self, attr, None)

    def _begin_work_boot_busy(self) -> None:
        """进入工作前先出等待条（分帧建旗/箱时主线程会顿一下）。"""
        if self._work_boot_busy:
            self._show_wait_hint("进入工作中")
            self._flush_wait_hint_now()
            return
        self._work_boot_busy = True
        self._enter_ui_busy("进入工作中")
        # _enter_ui_busy 已 flush 提示；勿再整树 update_idletasks

    def _end_work_boot_busy(self) -> None:
        if not self._work_boot_busy:
            return
        self._work_boot_busy = False
        self._exit_ui_busy()

    def _stop_work_mode(self, *, leave_mode: bool = True) -> None:
        self._cancel_work_loops()
        self._end_work_boot_busy()
        self.work_animating = False
        self.work_continuous = False
        self.work_session_kind = ""
        self._pending_work_start = False
        if self.work_encourage_job:
            try:
                self.root.after_cancel(self.work_encourage_job)
            except Exception:
                pass
            self.work_encourage_job = None
        self.work_boxes_since_banter = 0
        self.work_banter_last_ms = 0
        self._clear_work_anchored_boxes()
        self._hide_work_overlay(destroy=False)
        if self.work_start_box_win and self.work_start_box_win.winfo_exists():
            try:
                self.work_start_box_win.withdraw()
            except Exception:
                try:
                    self.work_start_box_win.destroy()
                except Exception:
                    pass
                self.work_start_box_win = None
        self._hide_work_end_button()
        self._hide_work_flag_drag_handle()
        self.work_phase = ""
        self.work_carrying = False
        self.work_has_start_box = False
        self._hide_desk_clock("work")
        self._work_session_start_ms = 0
        # 避免 mode=work 但 state 已非 work 的空壳（站死、结束钮消失、无法再进）
        if leave_mode and self.mode == "work":
            self.mode = "free"

    def _cancel_idle_chain(self) -> None:
        self._cancel_follow_chain()
        for attr in (
            "idle_job",
            "walk_move_job",
            "walk_anim_job",
            "action_anim_job",
            "move_land_job",
            "food_fx_job",
            "happy_job",
            "expression_bounce_job",
            "sleep_interact_end_job",
        ):
            job = getattr(self, attr, None)
            if job:
                try:
                    self.root.after_cancel(job)
                except Exception:
                    pass
                setattr(self, attr, None)
        self._expression_bounce_left = 0

    def _mode_switch_needs_full_interrupt(self) -> bool:
        """空闲走动切模式时可走轻量路径；有动作/特效/重模式才全量清场。"""
        if self.mode in ("work", "quiet", "game") or self.state in ("work", "sleep", "rest", "action"):
            return True
        if self.action_name or self.rhythm_active or self.sleep_interact_active:
            return True
        if self.game_boxes or self.game_spawn_job or self.game_tick_job:
            return True
        if self.angry_anim_job or self.rest_peek_job or self.follow_dizzy or self.follow_dizzy_job:
            return True
        for attr in (
            "happy_fx_win",
            "food_fx_win",
            "rain_fx_win",
            "bulb_fx_win",
            "interact_fx_win",
            "like_fx_win",
            "shy_fx_win",
            "wink_fx_win",
            "bixin_fx_win",
            "follow_dizzy_fx_win",
            "gift_pixel_fx_win",
            "sleep_zzz_win",
            "speech_dialog",
            "voice_subtitle_win",
            "_companion_heart_win",
        ):
            if getattr(self, attr, None) is not None:
                return True
        return False

    def _interrupt_current_interaction(self, *, reset_y: bool = True) -> None:
        """切换按键/动作时立刻结束当前效果（最高优先级）。"""
        self._pause_bg_fx_notify()
        try:
            self.interaction_token += 1
            self._cancel_idle_chain()
            self._hide_size_loading()
            # 正在加载智能伴侣时不要掐掉（否则开伴侣后的开心互动会把莲取消掉）
            if not (self.companion_loading_active and self.companion_bar_enabled):
                self._hide_companion_loading()
            self._cancel_food_drag()
            self._cancel_action_end()
            self._cancel_action_defer()
            self._hide_speech_dialog()
            self._hide_voice_subtitle()
            self._stop_call_audio()
            # 头顶花与装扮同属佩戴态，打断互动时不销毁
            # 开伴侣时的送爱心不要被开心 interrupt 清掉
            if not getattr(self, "_companion_heart_protect", False):
                self._hide_companion_heart_transfer()
            self._clear_all_action_fx()
            self._cancel_expose_qte()
            self._cancel_game_countdown()
            self._stop_drag_move()
            self._stop_rest_bobble()
            self.sleep_interact_active = False
            if self.angry_anim_job:
                self.root.after_cancel(self.angry_anim_job)
                self.angry_anim_job = None
            if self.rest_peek_job:
                self.root.after_cancel(self.rest_peek_job)
                self.rest_peek_job = None
            if self.state == "sleep":
                self._wake_from_sleep()
            elif self.state == "work":
                self._stop_work_mode()
            self.click_bounce_offset = 0
            if reset_y and self.angry_lift_offset:
                self.y = self.angry_base_y
                self.angry_lift_offset = 0
            # 侧踢/wink/shy 上弹中打断时收回
            if reset_y:
                if self.action_name == "kick":
                    self._restore_kick_y()
                elif self.action_name == "wink":
                    base = getattr(self, "wink_base_y", None)
                    if base is not None and abs(self.y - base) <= WINK_BOUNCE_PX + 1:
                        self.y = base
                elif self.action_name == "shy":
                    base = getattr(self, "shy_base_y", None)
                    if base is not None and abs(self.y - base) <= SHY_BOUNCE_PX + 1:
                        self.y = base
                elif self.action_name == "happy":
                    # 开心弹动用 offset，打断时清零（勿改 self.y）
                    self.happy_bounce_offset = 0
            self.angry_walk_phase = False
            self.state = "stand"
            self.action_name = ""
            if self.mode != "game":
                self._set_image(self._current_stand_sprite())
                self._place_window(light=True)
            self._sync_head_flower()
        finally:
            self._resume_bg_fx_notify()

    def _interrupt_for_mode_switch(self) -> None:
        """切换模式时打断睡眠/工作/互动等，模式切换优先。"""
        try:
            self._cancel_hold_allmate_approach()
        except Exception:
            pass
        self._cancel_pomodoro_if_external(toast=True)
        if not self._mode_switch_needs_full_interrupt():
            # 自由/跟随/漫步空闲：停走动 + 清前一动作/表情背景特效
            self._mode_switch_light_prepare()
            self._cancel_follow_chain()
            self.follow_dizzy = False
            self.follow_spin_dir = 0
            self.follow_spin_steps = 0
            self.follow_dir_change_times.clear()
            self.follow_last_dir = ""
            self._reset_walk_turn_tracker()
            self.state = "stand"
            self.action_name = ""
            return
        self._interrupt_current_interaction()
        if self.follow_dizzy_job:
            self.root.after_cancel(self.follow_dizzy_job)
            self.follow_dizzy_job = None
        self._cancel_follow_chain()
        self._end_drag_dizzy()
        self._hide_follow_dizzy_fx()
        self.follow_dizzy = False
        self.follow_spin_dir = 0
        self.follow_spin_steps = 0
        self.follow_dir_change_times.clear()
        self.follow_last_dir = ""
        self._reset_walk_turn_tracker()
        self._hide_shy_fx()
        self._cancel_game_countdown()
        if self.mode == "game" or self.game_boxes or self.game_spawn_job or self.game_tick_job:
            self._stop_game_mode()
        if self.mode == "work" or self.state == "work":
            self._stop_work_mode()
        if self.rhythm_active:
            self._close_rhythm_game(resume=False)

    def _mode_switch_take_pre_cleaned(self) -> bool:
        """via-free 已清场则跳过二次 interrupt。"""
        cleaned = bool(getattr(self, "_mode_switch_pre_cleaned", False))
        self._mode_switch_pre_cleaned = False
        return cleaned

    def _mode_switch_light_prepare(self) -> None:
        """进目标模式前轻量清场：停走动，并去掉前一动作/表情背景特效。"""
        self.interaction_token += 1
        self._cancel_idle_chain()
        self._cancel_action_end()
        self._cancel_action_defer()
        self.follow_animating = False
        self.work_animating = False
        self._clear_all_action_fx()
        # 目标若是安静会再 show；其它模式不得残留 Zzz
        self._hide_sleep_zzz()

    def _apply_work_mode(self) -> None:
        # via-free 已清场，或本来就在自由：只停走动，避免再整段 interrupt
        if self._mode_switch_take_pre_cleaned() or self.mode == "free":
            self._mode_switch_light_prepare()
            self._ensure_mode_exclusive_cleanup("work")
        else:
            self._ensure_mode_exclusive_cleanup("work")
            self._interrupt_for_mode_switch()
            self._leave_quiet_mode()
        self._begin_work_mode_when_ready()

    def _begin_work_mode_when_ready(self, tries: int = 0, *, prepared: bool = True) -> None:
        """等拖拽结束再真正进入工作，避免 mode=work 空壳卡住。"""
        if self._closing:
            self._end_work_boot_busy()
            return
        if self.dragging:
            if tries == 0:
                self._begin_work_boot_busy()
                self._show_toast("松开后再开始工作…", "#ffcc66", duration_ms=1600)
            if tries >= 100:
                self._show_toast("请先松开鼠标再开始工作", "#ff8866", duration_ms=2200)
                self._pending_work_start = False
                self._end_work_boot_busy()
                return
            self._pending_work_start = True
            self.root.after(
                50,
                lambda t=tries + 1, p=prepared: self._begin_work_mode_when_ready(t, prepared=p),
            )
            return
        self._pending_work_start = False
        self.mode = "work"
        # prepared：上游已清场则跳过二次 interrupt；空壳重启须 False
        self._start_work_impl(
            WORK_BOX_TOTAL_DEFAULT,
            flag_movable=True,
            continuous=True,
            kind="free",
            prepared=prepared,
        )

    def _enable_work(self) -> None:
        # 已在正常工作中：忽略；空壳 mode=work：允许重启
        if self.mode == "work" and self.state == "work":
            return
        self._begin_work_boot_busy()
        if self.mode == "work" and self.state != "work":
            self._begin_work_mode_when_ready(prepared=False)
            return
        # 工作已有 boot busy，勿再叠一层切模式 busy（双 flush 更顿）
        self._request_mode_switch(self._apply_work_mode, show_busy=False)

    def _leave_quiet_mode(self) -> None:
        if self.mode != "quiet":
            return
        self._complete_mode_timed_session("sleep")
        if self.rest_peek_job:
            self.root.after_cancel(self.rest_peek_job)
            self.rest_peek_job = None
        self._stop_rest_bobble()
        self._hide_sleep_zzz()
        self._hide_sleep_end_button()
        self._hide_desk_clock("sleep")
        if self.state == "rest":
            self.state = "stand"
            self._set_image(self.sprites.stand)

    def _cancel_pending_mode_switch(self) -> None:
        if self.mode_switch_job:
            try:
                self.root.after_cancel(self.mode_switch_job)
            except Exception:
                pass
            self.mode_switch_job = None

    def _apply_free_transition(self, *, resume: bool = True) -> None:
        """切回自由模式（清理当前非自由状态）。via-free 进其它模式时 resume=False，避免先走两步又打断。"""
        self._cancel_pending_mode_switch()
        self._interrupt_for_mode_switch()
        self._leave_quiet_mode()
        # interrupt 已停工作/采集，此处不再二次 stop
        self.mode = "free"
        self.follow_animating = False
        self.work_animating = False
        self._wake_from_sleep()
        self.state = "stand"
        self.action_name = ""
        self._set_image(self._current_stand_sprite())
        self._place_window(light=True)
        if resume:
            self._resume_idle(quick=True)

    def _exit_work_to_free(self, *, reason: str = "done", celebrate: bool = False) -> None:
        """箱数到 / 定时到 / 点结束：清工作并回到自由走动。"""
        if self.state != "work" and self.mode != "work":
            return
        if getattr(self, "_exiting_work", False):
            return
        if (
            getattr(self, "_pomodoro_active", False)
            and not getattr(self, "_pomodoro_transitioning", False)
            and reason != "pomodoro_end"
        ):
            self._cancel_pomodoro_if_external(toast=True)
        self._exiting_work = True
        try:
            self._complete_work_session(reason=reason)
            self._stop_work_mode(leave_mode=True)
            self.mode = "free"
            self.state = "stand"
            self.work_animating = False
            self.action_name = ""
            self._set_image(self._current_stand_sprite())
            self._place_window(light=True)
            if celebrate and not self.dragging and not self.music_sprite_mode:
                # _play_happy 结束后会 _resume_idle(quick=True)
                self._play_happy()
            else:
                self._resume_idle(quick=True)
        finally:
            self._exiting_work = False

    def _request_mode_switch(self, apply_fn: callable, *, show_busy: bool = True) -> None:
        """非自由 → 非自由：清场一次再进目标；已在自由则直接进目标。

        show_busy=False：跟随/漫步/睡眠等轻量切换，不弹等待提示（否则建窗+flush 比切换本身更慢）。
        """
        self._cancel_pending_mode_switch()
        self._hide_main_menu()
        self.mode_switch_token += 1
        tok = self.mode_switch_token
        self._mode_switch_pre_cleaned = False
        via_free = self.mode != "free"
        if show_busy:
            self._enter_ui_busy("切换模式中")

        def run_target() -> None:
            if tok != self.mode_switch_token:
                if show_busy:
                    self._exit_ui_busy()
                return
            self.mode_switch_job = None
            try:
                apply_fn()
            finally:
                if show_busy:
                    self._exit_ui_busy()

        if not via_free:
            run_target()
            return
        # 只清场、不恢复走动；目标 apply 若已 pre_cleaned 则跳过二次 interrupt
        self._apply_free_transition(resume=False)
        self._mode_switch_pre_cleaned = True
        if show_busy:
            # 给 Tk 一拍画等待提示
            self.mode_switch_job = self.root.after(0, run_target)
        else:
            # 轻量切换：同调用栈直接进目标，少一帧 after 延迟
            run_target()

    def _apply_follow_mode(self) -> None:
        if self._mode_switch_take_pre_cleaned():
            self._mode_switch_light_prepare()
        else:
            self._interrupt_for_mode_switch()
            self._leave_quiet_mode()
        self.mode = "follow"
        self.follow_animating = False
        self.follow_spin_dir = 0
        self.follow_spin_steps = 0
        self.state = "stand"
        self._set_image(self.sprites.stand)
        self._resume_idle()
        self._note_mode_for_achievement("follow")

    def _apply_stroll_mode(self) -> None:
        if self._mode_switch_take_pre_cleaned():
            self._mode_switch_light_prepare()
        else:
            self._interrupt_for_mode_switch()
            self._leave_quiet_mode()
        self.mode = "stroll"
        self.follow_animating = False
        self._wake_from_sleep()
        self.state = "stand"
        self._set_image(self._current_stand_sprite())
        self._resume_idle()
        self._note_mode_for_achievement("stroll")

    def _apply_quiet_mode(self) -> None:
        if self._mode_switch_take_pre_cleaned():
            self._mode_switch_light_prepare()
        else:
            self._interrupt_for_mode_switch()
        self.mode = "quiet"
        self.follow_animating = False
        self.rest_base_y = self.y
        self.state = "rest"
        self._set_image(self.sprites.sleep[1])
        self._show_sleep_zzz()
        self._schedule_rest_bobble()
        # 延后播 sleep：避免模式切换 interrupt / 关菜单 的同帧收尾掐掉刚排队的语音
        self._schedule_quiet_sleep_voice()
        self._sync_sleep_end_button()
        self._note_mode_for_achievement("quiet")

    def _schedule_quiet_sleep_voice(self) -> None:
        """模式→睡眠：补播 sleep 语音（与互动→动作→睡眠同源）。"""
        tok = self.interaction_token
        gen = int(getattr(self, "_quiet_sleep_voice_gen", 0)) + 1
        self._quiet_sleep_voice_gen = gen

        def play(expected: int = gen, inter_tok: int = tok) -> None:
            if expected != getattr(self, "_quiet_sleep_voice_gen", 0):
                return
            if inter_tok != self.interaction_token:
                return
            if self.mode != "quiet" or self.state != "rest":
                return
            if not self._voice_enabled():
                self._show_interact_banter_dialog("sleep")
                return
            # 强制场景播 sleep；失败则退回打字句
            if self._vpet_voice_category_ready("sleep"):
                if self._addon_voice_vpet("sleep", chain=False, interrupt_busy=True):
                    return
            self._show_interact_banter_dialog("sleep")

        self.root.after(90, play)

    def _enable_follow(self) -> None:
        if self.mode == "follow":
            return
        self._request_mode_switch(self._apply_follow_mode, show_busy=False)

    def _enable_free(self) -> None:
        self._cancel_pending_mode_switch()
        self.mode_switch_token += 1
        self._hide_main_menu()
        # 互动/自定义工作可能 mode 仍是 free 但 state=work，必须先停工作
        if self.state == "work" or self.mode == "work":
            self._exit_work_to_free(reason="done", celebrate=False)
            return
        if self.mode == "free":
            self._resume_idle(quick=True)
            return
        self._apply_free_transition()

    def _enable_stroll(self) -> None:
        if self.mode == "stroll":
            return
        self._request_mode_switch(self._apply_stroll_mode, show_busy=False)

    def _enable_quiet(self) -> None:
        if self.mode == "quiet":
            # 已在睡眠模式：再点一次仍应补播 sleep（上次可能被打断）
            self._schedule_quiet_sleep_voice()
            self._hide_main_menu()
            return
        self._request_mode_switch(self._apply_quiet_mode, show_busy=False)

    def _enable_game(self) -> None:
        if self.mode == "game":
            return

        def begin() -> None:
            if self.mode in ("work",) or self.state == "work":
                return
            self._ensure_mode_exclusive_cleanup("game")
            if self._mode_switch_take_pre_cleaned():
                self._mode_switch_light_prepare()
            else:
                self._interrupt_for_mode_switch()
                self._leave_quiet_mode()
            if self.mode in ("work",) or self.state == "work":
                return
            self.mode = "game"
            self.state = "game"
            self.game_score = 0
            self.game_catches = 0
            self.game_misses = 0
            self.game_session_food = {}
            self.game_start_ms = int(time.time() * 1000)
            self.game_boxes.clear()
            self._end_game_dizzy_stun()
            # 采集：伴侣保持可见；只清同步特效，并拉开间距躲开晕眩窗
            self._clear_mini_pet_fx_for_gather()
            self._sync_all_mini_pet_bg_fx()
            for entry in list(getattr(self, "mini_pets", []) or []):
                try:
                    self._mini_pet_follow_tick(entry)
                except Exception:
                    pass
            self._set_image(self.sprites.stand)
            self._show_game_hud()
            self._mark_hint_seen("game_mode")
            self._sync_mode_time_bucket()
            self._game_tick()
            self._game_spawn_box()

        def after_guide() -> None:
            self._request_mode_switch(lambda: self._start_game_countdown(begin))

        self._ensure_first_play_guide("gather", after_guide)

    def _game_time_left_ms(self) -> int:
        elapsed = int(time.time() * 1000) - self.game_start_ms
        return max(0, GAME_DURATION_MS - elapsed)

    def _show_game_hud(self) -> None:
        if self.game_hud_win and self.game_hud_win.winfo_exists():
            self.game_hud_win.destroy()
        self.game_hud_win = tk.Toplevel(self.root)
        self.game_hud_win.overrideredirect(True)
        self._apply_window_layer(self.game_hud_win)
        self.game_hud_win.configure(bg="#111122")
        border = tk.Frame(self.game_hud_win, bg="#88ccff", padx=1, pady=1)
        border.pack()
        inner = tk.Frame(border, bg="#111122", padx=10, pady=6)
        inner.pack()
        self.game_hud_label = tk.Label(
            inner, text="", font=PIXEL_FONT, fg="#88ccff", bg="#111122", justify=tk.LEFT
        )
        self.game_hud_label.pack()
        self._update_game_hud()

    def _update_game_hud(self) -> None:
        if not self.game_hud_label or not self.game_hud_win or not self.game_hud_win.winfo_exists():
            return
        left_ms = self._game_time_left_ms()
        sec = left_ms // 1000
        text = (
            f"⏱ {sec:02d}s    食物 {self.game_catches}\n"
            f"接住 {self.game_catches}  错过 {self.game_misses}  库存 {self._food_inventory_total()}"
        )
        if getattr(self, "_game_hud_text", None) != text:
            self._game_hud_text = text
            self.game_hud_label.config(text=text)
        hud_pos = (self.x, max(0, self.y - 52))
        if getattr(self, "_game_hud_pos", None) != hud_pos:
            self._game_hud_pos = hud_pos
            self._place_popup(self.game_hud_win, hud_pos[0], hud_pos[1])

    # —— 桌面秒表 / 计时器（数字框 + 绕圈小人）——

    def _timers_display_enabled(self) -> bool:
        return bool(self.app_config.get("show_timers", True))

    def _set_timers_display(self, on: bool) -> None:
        self.app_config["show_timers"] = bool(on)
        self._defer_save_app_config()
        self._show_toast(f"时间显示：{'开' if on else '关'}", PIXEL_COLOR)
        # 统一由 sync：关秒表面板；音乐模式仍保留媒体键
        self._sync_auto_desk_clocks()

    def _set_launch_at_login(self, on: bool) -> None:
        on = bool(on)
        self.app_config["launch_at_login"] = on
        self.app_config["spawn_on_launcher_start"] = on
        self._defer_save_app_config()
        try:
            import vpet_launcher

            vpet_launcher.set_launch_at_login(on)
        except Exception:
            pass
        self._show_toast(f"开机自启：{'开' if on else '关'}", PIXEL_COLOR)

    def _desk_clock_active(self, slot: str) -> bool:
        info = self._desk_clocks.get(slot)
        if not info:
            return False
        win = info.get("win")
        try:
            return bool(win and win.winfo_exists())
        except Exception:
            return False

    def _desk_clock_metrics(self) -> dict[str, int | float]:
        """随桌宠 display_size 同步缩放（以「中」128px 为基准）。"""
        base = float(SIZE_PRESETS.get("中", 128) or 128)
        s = max(0.55, min(1.75, float(self.display_size) / base))
        return {
            "scale": s,
            "pad": max(16, int(round(30 * s))),
            "inner_w": max(96, int(round(148 * s))),
            "inner_h": max(30, int(round(44 * s))),
            "font": max(11, int(round(16 * s))),
            "walker": max(14, int(round(26 * s))),
            "ctrl_extra": max(28, int(round(32 * s))),
            "btn_font": max(10, int(round(12 * s))),
        }

    def _ensure_desk_clock_walkers(self, style: str = "walk") -> dict[str, list[ImageTk.PhotoImage]]:
        key = str(style or "walk").strip().lower()
        if key not in ("walk", "work", "music"):
            key = "walk"
        wsize = int(self._desk_clock_metrics()["walker"])
        cache_key = f"{key}@{wsize}"
        cached = self._desk_clock_walkers.get(cache_key)
        if cached:
            return cached
        try:
            frames = desktop_clock.load_walker_frames(SPRITES_DIR, size=wsize, style=key)
        except Exception:
            frames = {"front": [], "back": [], "left": [], "right": []}
        self._desk_clock_walkers[cache_key] = frames
        return frames

    def _desk_clock_walker_style(self, slot: str) -> str:
        """时钟环绕小人贴图：音乐→music，工作→work，其余普通 walk。"""
        if slot == "music":
            return "music"
        if slot == "work":
            return "work"
        return "walk"

    def _ensure_desk_clock_sleep_frames(self) -> list[ImageTk.PhotoImage]:
        wsize = int(self._desk_clock_metrics()["walker"])
        cached = getattr(self, "_desk_clock_sleep_frames", None)
        cached_size = int(getattr(self, "_desk_clock_sleep_size", 0) or 0)
        if cached and cached_size == wsize:
            return cached
        try:
            self._desk_clock_sleep_frames = desktop_clock.load_sleep_frames(SPRITES_DIR, size=wsize)
        except Exception:
            self._desk_clock_sleep_frames = []
        self._desk_clock_sleep_size = wsize
        return self._desk_clock_sleep_frames

    def _desk_clock_slot_index(self, slot: str) -> int:
        order = ("tool_sw", "tool_cd", "work", "sleep", "music", "pomodoro_rest")
        try:
            return order.index(slot)
        except ValueError:
            return len(order)

    def _default_desk_clock_pos(self, slot: str) -> tuple[int, int]:
        sw = int(self.root.winfo_screenwidth())
        sh = int(self.root.winfo_screenheight())
        m = self._desk_clock_metrics()
        box_w = int(m["inner_w"]) + int(m["pad"]) * 2
        box_h = int(m["inner_h"]) + int(m["pad"]) * 2 + int(m["ctrl_extra"])
        # 任务栏预留，避免贴底被挡住
        y_max = max(8, sh - box_h - 80)
        x_right = max(8, sw - box_w - 24)

        # 音乐 / 番茄休息：贴在桌宠旁，勿按固定序号堆到屏幕最底
        if slot in ("music", "pomodoro_rest"):
            try:
                px = int(getattr(self, "x", 0) or 0)
                py = int(getattr(self, "y", 0) or 0)
                pw = int(getattr(self, "display_size", 128) or 128)
                ph = pw
            except Exception:
                px, py, pw, ph = 40, 80, 128, 128
            left_x = px - box_w - 12
            right_x = px + pw + 12
            if left_x >= 8:
                x = left_x
            elif right_x + box_w <= sw - 8:
                x = right_x
            else:
                x = max(8, min(x_right, px))
            # 与宠垂直居中；休息钟略上移，音乐略下移，避免重叠
            y = py + max(0, (ph - box_h) // 2)
            if slot == "pomodoro_rest":
                y = max(8, py - 8)
            elif slot == "music":
                y = min(y_max, py + max(0, ph // 4))
            x = max(8, min(x, sw - box_w - 8))
            y = max(8, min(y, y_max))
            return x, y

        idx = self._desk_clock_slot_index(slot)
        y = 48 + idx * (box_h + 10)
        return x_right, max(8, min(y, y_max))

    def _ensure_desk_clock_on_screen(self, slot: str) -> None:
        """若时钟落到任务栏附近 / 屏外，挪回默认安全位置。"""
        info = self._desk_clocks.get(slot)
        if not info:
            return
        win = info.get("win")
        if win is None:
            return
        try:
            if not win.winfo_exists():
                return
            geo = win.geometry()
            parts = geo.split("+")
            if len(parts) < 3:
                return
            x, y = int(parts[1]), int(parts[2])
            sw = int(self.root.winfo_screenwidth())
            sh = int(self.root.winfo_screenheight())
            box_w = int(info.get("win_w") or 120)
            box_h = int(info.get("win_h") or 80)
            y_max = max(8, sh - box_h - 80)
            bad = y > y_max or y < 0 or x < -20 or x > sw - 40
            if bad:
                nx, ny = self._default_desk_clock_pos(slot)
                win.geometry(f"+{nx}+{ny}")
        except Exception:
            pass

    def _icon_transport_btn(
        self,
        parent: tk.Misc,
        glyph: str,
        command,
        *,
        primary: bool = False,
        tip: str = "",
        font: tuple | None = None,
        tone: str | None = None,
        transparency: float | None = None,
        key_chrome: str | None = None,
    ) -> tk.Button:
        """音乐/时钟控件：类播放器图标键（蓝粉白黄像素配色）。
        transparency：色键窗上用抖动挖空做轻微透明；key_chrome 为键色（默认品红）。
        """
        # tone: blue | pink | white | yellow | end；primary 兼容旧调用→粉
        tones = {
            "blue": ("#4a90d8", "#6aacf0", "#ffffff"),
            "pink": ("#f090b8", "#ffa8cc", "#ffffff"),
            "white": ("#f4f7ff", "#ffffff", "#3a4a6a"),
            "yellow": ("#f0c85a", "#ffe08a", "#ffffff"),
            "end": ("#ff9ec0", "#ffb8d4", "#ffffff"),
        }
        key = (tone or ("pink" if primary else "blue")).strip().lower()
        if key not in tones:
            key = "blue"
        bg, abg, fg = tones[key]
        use_glass = transparency is not None and float(transparency) > 0.01
        chrome = (key_chrome or "magenta").strip() or "magenta"
        btn_bg = chrome if use_glass else bg
        btn_abg = chrome if use_glass else abg
        btn = tk.Button(
            parent,
            text=glyph,
            font=font or ("Segoe UI Symbol", 12),
            bg=btn_bg,
            fg=fg,
            activebackground=btn_abg,
            activeforeground=fg,
            relief=tk.FLAT,
            bd=0,
            highlightthickness=0 if use_glass else 1,
            highlightbackground="#ffffff",
            highlightcolor="#ffe08a",
            padx=10,
            pady=2,
            cursor="hand2",
            command=command,
        )
        if use_glass:
            try:
                fnt = font or ("Segoe UI Symbol", 12)
                try:
                    size_pt = int(fnt[1]) if len(fnt) > 1 else 12
                except Exception:
                    size_pt = 12
                bw = max(34, size_pt * 2 + 18)
                bh = max(24, size_pt + 12)
                chip = desktop_clock.make_keyed_fill(
                    bw,
                    bh,
                    bg,
                    transparency=float(transparency),
                    key_rgb=(255, 0, 255),
                )
                photo = ImageTk.PhotoImage(chip)
                btn.configure(image=photo, compound=tk.CENTER, padx=4, pady=1)
                btn._glass_photo = photo  # type: ignore[attr-defined]
            except Exception:
                btn.configure(bg=bg, activebackground=abg, highlightthickness=1)
        if tip:
            try:
                btn.configure(takefocus=0)
                btn._tip = tip  # type: ignore[attr-defined]
            except Exception:
                pass
        return btn

    def _chrome_icon_btn(
        self,
        parent: tk.Misc,
        role: str,
        command,
        *,
        font: tuple | None = None,
    ) -> tk.Button:
        """通用面板图标键：关闭/返回/确认/取消/开始/停止（无文字也能辨认）。"""
        roles = {
            "close": ("×", "关闭", "white"),
            "back": ("←", "返回", "blue"),
            "ok": ("✓", "知道了", "pink"),
            "cancel": ("×", "取消", "white"),
            "start": ("▶", "开始", "pink"),
            "stop": ("⏹", "停止", "white"),
        }
        glyph, tip, tone = roles.get(role, ("×", role, "white"))
        return self._icon_transport_btn(
            parent, glyph, command, tip=tip, tone=tone, font=font or ("Segoe UI Symbol", 12),
        )

    def _start_desk_clock(
        self,
        slot: str,
        *,
        kind: str,
        title: str,
        duration_ms: int = 0,
        force: bool = False,
        with_controls: bool = False,
        controls_armed: bool = False,
        with_media: bool = False,
        show_timer_face: bool = True,
        on_done=None,
    ) -> None:
        """kind: stopwatch | countdown。force=工具打开时无视显示开关。
        with_controls：秒表/计时器/番茄 显示 ⏸▶⏹。
        controls_armed：有控件但开局即走（番茄工作/休息）；否则等点 ▶。
        with_media：音乐模式下方 ⏮ ⏯ ⏭ ⏹（⏹ 结束回自由）。
        show_timer_face：是否显示秒表数字/绕圈小人；关「时间显示」时音乐可仅留媒体键。"""
        show_face = bool(show_timer_face)
        # 音乐媒体栏在关时间显示时仍要建（仅无秒表面）
        if (
            not force
            and not self._timers_display_enabled()
            and slot not in ("tool_sw", "tool_cd")
            and not (slot == "music" and with_media and not show_face)
        ):
            return
        self._hide_desk_clock(slot)
        now = int(time.time() * 1000)
        if slot == "sleep":
            self._sleep_session_start_ms = now
        elif slot == "music":
            self._music_session_start_ms = now
        m = self._desk_clock_metrics()
        pad = int(m["pad"])
        inner_w, inner_h = int(m["inner_w"]), int(m["inner_h"])
        font_px = int(m["font"])
        win_w = inner_w + pad * 2
        if show_face:
            win_h = inner_h + pad * 2
        else:
            win_h = 4
            inner_h = 0
        if with_controls or with_media:
            win_h += int(m["ctrl_extra"])
        x0, y0 = self._default_desk_clock_pos(slot)
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)
        try:
            setattr(win, "_vpet_no_glass", True)
        except Exception:
            pass
        clock_chrome = "magenta"
        win.configure(bg=clock_chrome)
        try:
            win.wm_attributes("-transparentcolor", clock_chrome)
        except Exception:
            pass
        self._apply_window_layer(win)
        win.geometry(f"{win_w}x{win_h}+{x0}+{y0}")
        canvas = None
        if show_face:
            canvas = tk.Canvas(
                win,
                width=win_w,
                height=inner_h + pad * 2,
                bg=clock_chrome,
                highlightthickness=0,
            )
            canvas.pack()
        try:
            self._win32_refresh_transparent_color(win)
        except Exception:
            pass
        running = (not with_controls) or bool(controls_armed)
        info = {
            "win": win,
            "canvas": canvas,
            "kind": kind,
            "title": title,
            "start_ms": now,
            "duration_ms": max(0, int(duration_ms)),
            "pad": pad,
            "inner_w": inner_w,
            "inner_h": inner_h,
            "font": font_px,
            "win_w": win_w,
            "win_h": win_h,
            "display_size": int(self.display_size),
            "on_done": on_done,
            "done": False,
            "photos": [],
            "with_controls": bool(with_controls),
            "with_media": bool(with_media),
            "show_timer_face": show_face,
            "controls_armed": bool(controls_armed),
            "force": bool(force),
            "running": running,
            "accum_ms": 0,
            "segment_start_ms": now if running else 0,
        }
        self._desk_clocks[slot] = info

        btn_font = ("Segoe UI Symbol", int(m["btn_font"]))
        glass = float(DESK_CLOCK_BTN_TRANSPARENCY)
        if with_controls:
            bf = tk.Frame(win, bg="#1a2030")
            bf.pack(fill=tk.X, padx=6, pady=(0, 4))
            self._icon_transport_btn(
                bf, "▶", lambda s=slot: self._desk_clock_control(s, "start"),
                tip="开始", font=btn_font, tone="pink",
            ).pack(side=tk.LEFT, padx=(0, 4))
            self._icon_transport_btn(
                bf, "⏸", lambda s=slot: self._desk_clock_control(s, "pause"),
                tip="暂停", font=btn_font, tone="blue",
            ).pack(side=tk.LEFT, padx=(0, 4))
            self._icon_transport_btn(
                bf, "⏹", lambda s=slot: self._desk_clock_control(s, "end"),
                tip="结束", font=btn_font, tone="white",
            ).pack(side=tk.LEFT, padx=(0, 4))

        if with_media:
            mf = tk.Frame(win, bg=clock_chrome)
            mf.pack(fill=tk.X, padx=6, pady=(0, 4))
            mid = tk.Frame(mf, bg=clock_chrome)
            mid.pack(anchor=tk.CENTER)
            self._icon_transport_btn(
                mid, "⏮", self._bg_music_prev_track,
                tip="上一首", font=btn_font, tone="blue",
                transparency=glass, key_chrome=clock_chrome,
            ).pack(side=tk.LEFT, padx=3)
            play_glyph = "▶" if getattr(self, "bg_music_user_paused", False) else "⏸"
            play_btn = self._icon_transport_btn(
                mid,
                play_glyph,
                self._bg_music_toggle_pause,
                tip="播放/暂停",
                font=btn_font,
                tone="pink",
                transparency=glass,
                key_chrome=clock_chrome,
            )
            play_btn.pack(side=tk.LEFT, padx=3)
            info["media_play_btn"] = play_btn
            self._icon_transport_btn(
                mid, "⏭", self._bg_music_next_track,
                tip="下一首", font=btn_font, tone="white",
                transparency=glass, key_chrome=clock_chrome,
            ).pack(side=tk.LEFT, padx=3)
            self._icon_transport_btn(
                mid, "⏹", self._apply_music_off,
                tip="结束音乐 · 回自由", font=btn_font, tone="white",
                transparency=glass, key_chrome=clock_chrome,
            ).pack(side=tk.LEFT, padx=(8, 3))

        def on_press(e: tk.Event, s=slot) -> None:
            try:
                gx = int(e.x_root)
                gy = int(e.y_root)
                geo = self._desk_clocks[s]["win"].geometry()
                parts = geo.split("+")
                wx, wy = int(parts[1]), int(parts[2])
                self._desk_clock_drag[s] = (gx, gy, wx, wy)
            except Exception:
                pass

        def on_drag(e: tk.Event, s=slot) -> None:
            drag = self._desk_clock_drag.get(s)
            if not drag:
                return
            gx0, gy0, wx, wy = drag
            nx = wx + (int(e.x_root) - gx0)
            ny = wy + (int(e.y_root) - gy0)
            try:
                self._desk_clocks[s]["win"].geometry(f"+{nx}+{ny}")
            except Exception:
                pass

        def on_release(_e: tk.Event, s=slot) -> None:
            self._desk_clock_drag.pop(s, None)

        bind_targets = [win]
        if canvas is not None:
            bind_targets.append(canvas)
        for w in bind_targets:
            w.bind("<ButtonPress-1>", on_press)
            w.bind("<B1-Motion>", on_drag)
            w.bind("<ButtonRelease-1>", on_release)
            # 音乐媒体栏勿右键关掉（关时间显示后仍要能控歌）
            if not with_media:
                w.bind("<Button-3>", lambda _e, s=slot: self._hide_desk_clock(s))

        self._ensure_desk_clock_tick()
        if show_face:
            self._draw_desk_clock(slot)
        self._restack_display_z()

    def _desk_clock_control(self, slot: str, action: str) -> None:
        """秒表/计时器/番茄：▶ 开始 / ⏸ 暂停 / ⏹ 结束。"""
        info = self._desk_clocks.get(slot)
        if not info or not info.get("with_controls"):
            return
        now = int(time.time() * 1000)
        if action == "start":
            if not info.get("running"):
                info["segment_start_ms"] = now
                info["running"] = True
                info.pop("_last_draw_text", None)
        elif action == "pause":
            if info.get("running"):
                seg = int(info.get("segment_start_ms") or now)
                info["accum_ms"] = int(info.get("accum_ms") or 0) + max(0, now - seg)
                info["running"] = False
                info["segment_start_ms"] = 0
        elif action == "end":
            # 番茄工作/休息时钟：⏹ 结束整轮番茄
            if getattr(self, "_pomodoro_active", False) and slot in ("work", "pomodoro_rest"):
                self._end_pomodoro(toast=True, interrupted=False)
                return
            kind = str(info.get("kind") or "stopwatch")
            self._hide_desk_clock(slot)
            if kind == "countdown" or slot == "tool_cd":
                self._show_toast("计时器已结束", "#8899aa")
            else:
                self._show_toast("秒表已停止", "#8899aa")
            return
        if slot == "pomodoro_rest" and action in ("start", "pause"):
            try:
                left = int(self._desk_clock_elapsed_ms(info) or 0)
                self._pomodoro_rest_deadline_ms = now + max(0, left)
            except Exception:
                pass
        self._draw_desk_clock(slot)

    def _refresh_music_media_play_btn(self) -> None:
        info = self._desk_clocks.get("music")
        if not info:
            return
        btn = info.get("media_play_btn")
        if not btn:
            return
        try:
            if not btn.winfo_exists():
                return
            btn.config(text="▶" if getattr(self, "bg_music_user_paused", False) else "⏸")
        except Exception:
            pass

    def _hide_desk_clock(self, slot: str) -> None:
        info = self._desk_clocks.pop(slot, None)
        self._desk_clock_drag.pop(slot, None)
        if not info:
            return
        win = info.get("win")
        try:
            if win and win.winfo_exists():
                win.destroy()
        except Exception:
            pass
        if not self._desk_clocks:
            self._stop_desk_clock_tick()

    def _hide_all_desk_clocks(self) -> None:
        for slot in list(self._desk_clocks.keys()):
            self._hide_desk_clock(slot)

    def _ensure_desk_clock_tick(self) -> None:
        if self._desk_clock_job:
            return

        def tick() -> None:
            self._desk_clock_job = None
            if self._closing or not self._alive():
                return
            clocks = getattr(self, "_desk_clocks", None) or {}
            if not clocks:
                return
            any_running = False
            for slot in list(clocks.keys()):
                info = clocks.get(slot)
                if info and info.get("running"):
                    any_running = True
                try:
                    self._draw_desk_clock(slot)
                except Exception as exc:
                    try:
                        tip = str(exc).strip() or type(exc).__name__
                        print(f"[Vpet] desk_clock draw {slot}: {tip}", flush=True)
                    except Exception:
                        pass
            # 运行中稍密；全暂停则少刷，少抢走路主线程
            gap = 420 if any_running else 1000
            self._desk_clock_job = self._safe_after(gap, tick)

        self._desk_clock_job = self._safe_after(420, tick)

    def _stop_desk_clock_tick(self) -> None:
        if self._desk_clock_job:
            try:
                self.root.after_cancel(self._desk_clock_job)
            except Exception:
                pass
            self._desk_clock_job = None

    def _desk_clock_elapsed_ms(self, info: dict) -> int:
        now = int(time.time() * 1000)
        accum = int(info.get("accum_ms") or 0)
        if info.get("running"):
            seg = int(info.get("segment_start_ms") or now)
            accum += max(0, now - seg)
        kind = str(info.get("kind") or "stopwatch")
        if kind == "countdown":
            left = int(info.get("duration_ms") or 0) - accum
            return max(0, left)
        return max(0, accum)

    def _desk_clock_progress_ms(self, info: dict) -> int:
        """绕圈动画用的已走时间（暂停时冻结）。"""
        kind = str(info.get("kind") or "stopwatch")
        if kind == "countdown":
            return max(0, int(info.get("duration_ms") or 0) - self._desk_clock_elapsed_ms(info))
        return self._desk_clock_elapsed_ms(info)

    def _draw_desk_clock(self, slot: str) -> None:
        info = self._desk_clocks.get(slot)
        if not info:
            return
        if not info.get("show_timer_face", True):
            return
        canvas = info.get("canvas")
        win = info.get("win")
        if not canvas or not win:
            return
        try:
            if not win.winfo_exists():
                self._desk_clocks.pop(slot, None)
                return
        except Exception:
            self._desk_clocks.pop(slot, None)
            return

        kind = str(info.get("kind") or "stopwatch")
        ms = self._desk_clock_elapsed_ms(info)
        if kind == "countdown" and ms <= 0 and info.get("running") and not info.get("done"):
            info["done"] = True
            cb = info.get("on_done")
            title = str(info.get("title") or "计时器")
            self._hide_desk_clock(slot)
            if callable(cb):
                try:
                    cb()
                except Exception:
                    pass
            else:
                self._show_toast(f"{title}时间到！", "#ffcc66", duration_ms=2800)
            return

        pad = int(info["pad"])
        iw, ih = int(info["inner_w"]), int(info["inner_h"])
        font_px = int(info.get("font") or self._desk_clock_metrics()["font"])
        time_text = desktop_clock.format_clock_ms(ms)
        items = info.get("items")
        # 暂停时数字不变则跳过尾迹/小人重算，减轻主线程
        if (
            not info.get("running")
            and isinstance(items, dict)
            and items.get("time")
            and info.get("_last_draw_text") == time_text
        ):
            return
        info["_last_draw_text"] = time_text

        progressed = self._desk_clock_progress_ms(info)
        t = desktop_clock.walker_progress(progressed)
        px, py, edge = desktop_clock.perimeter_point(t, left=pad, top=pad, width=iw, height=ih)
        trail = desktop_clock.trail_points(
            t,
            left=pad,
            top=pad,
            width=iw,
            height=ih,
            count=len(DESK_CLOCK_TRAIL_COLORS),
            spacing=0.014,
        )
        photo = None
        if slot in ("sleep", "pomodoro_rest"):
            # 睡眠 / 番茄休息：同一套 sleep1/sleep2 小人
            sleep_frames = self._ensure_desk_clock_sleep_frames()
            if sleep_frames:
                photo = sleep_frames[(progressed // 480) % len(sleep_frames)]
                info["photos"] = list(sleep_frames)
        else:
            walkers = self._ensure_desk_clock_walkers(self._desk_clock_walker_style(slot))
            facing = desktop_clock.edge_to_facing(edge)
            frames = walkers.get(facing) or walkers.get("front") or []
            if frames:
                frame_i = (progressed // 210) % len(frames)
                photo = frames[frame_i]
                info["photos"] = [photo]

        def _sync_trail(item_map: dict) -> None:
            ids = item_map.get("trail")
            if not isinstance(ids, list) or len(ids) != len(trail):
                for old in list(ids or []):
                    try:
                        canvas.delete(old)
                    except Exception:
                        pass
                ids = []
                for i, (tx, ty, _idx) in enumerate(trail):
                    # 近亮大、远暗小：像素方块流星尾
                    half = max(1, 4 - i // 2)
                    color = DESK_CLOCK_TRAIL_COLORS[min(i, len(DESK_CLOCK_TRAIL_COLORS) - 1)]
                    rid = canvas.create_rectangle(
                        tx - half,
                        ty - half,
                        tx + half,
                        ty + half,
                        fill=color,
                        outline="",
                        width=0,
                    )
                    ids.append(rid)
                item_map["trail"] = ids
            else:
                for i, (tx, ty, _idx) in enumerate(trail):
                    half = max(1, 4 - i // 2)
                    try:
                        canvas.coords(ids[i], tx - half, ty - half, tx + half, ty + half)
                    except Exception:
                        pass
            # 尾迹压在底板之上、数字/小人之下（勿 tag_lower 到最底否则会钻进渐变下）
            try:
                anchor = item_map.get("time")
                if anchor:
                    for rid in ids:
                        canvas.tag_lower(rid, anchor)
                if item_map.get("walker"):
                    canvas.tag_raise(item_map["walker"])
            except Exception:
                pass

        items = info.get("items")
        # 增量更新：避免每 tick delete("all") 造成时钟区闪一下
        if not isinstance(items, dict) or not items.get("time"):
            canvas.delete("all")
            try:
                grad = desktop_clock.make_panel_gradient(
                    iw,
                    ih,
                    left_hex=DESK_CLOCK_GRAD_LEFT,
                    right_hex=DESK_CLOCK_GRAD_RIGHT,
                    transparency=DESK_CLOCK_BG_TRANSPARENCY,
                    key_rgb=(255, 0, 255),
                )
                bg_photo = ImageTk.PhotoImage(grad)
            except Exception:
                bg_photo = None
            info["bg_photo"] = bg_photo
            if bg_photo is not None:
                canvas.create_image(pad, pad, image=bg_photo, anchor="nw")
            canvas.create_rectangle(
                pad,
                pad,
                pad + iw,
                pad + ih,
                fill="" if bg_photo is not None else DESK_CLOCK_GRAD_LEFT,
                outline=DESK_CLOCK_OUTLINE,
                width=2,
            )
            items = {
                "time": canvas.create_text(
                    pad + iw // 2,
                    pad + ih // 2,
                    text=time_text,
                    fill=DESK_CLOCK_TIME_FG,
                    font=("Courier New", font_px, "bold"),
                ),
                "walker": canvas.create_image(px, py, image=photo) if photo else None,
                "trail": [],
            }
            info["items"] = items
            _sync_trail(items)
            return

        canvas.itemconfig(items["time"], text=time_text)
        _sync_trail(items)
        if photo is not None:
            wid = items.get("walker")
            if wid is None:
                items["walker"] = canvas.create_image(px, py, image=photo)
            else:
                canvas.coords(wid, px, py)
                canvas.itemconfig(wid, image=photo)
            try:
                canvas.tag_raise(items["walker"])
            except Exception:
                pass
        elif items.get("walker") is not None:
            try:
                canvas.delete(items["walker"])
            except Exception:
                pass
            items["walker"] = None

    def _resync_desk_clocks_for_size(self) -> None:
        """桌宠尺寸变更后：重建秒表/计时器窗，保留计时状态与屏幕位置。"""
        snaps: list[dict] = []
        for slot, info in list(getattr(self, "_desk_clocks", {}) or {}).items():
            if not isinstance(info, dict):
                continue
            wx = wy = None
            win = info.get("win")
            try:
                if win is not None and win.winfo_exists():
                    geo = win.geometry()
                    parts = geo.split("+")
                    if len(parts) >= 3:
                        wx, wy = int(parts[1]), int(parts[2])
            except Exception:
                pass
            # 冻结当前已走时长，重建后按暂停态接上再决定是否继续跑
            now = int(time.time() * 1000)
            accum = int(info.get("accum_ms") or 0)
            if info.get("running"):
                seg = int(info.get("segment_start_ms") or now)
                accum += max(0, now - seg)
            snaps.append(
                {
                    "slot": slot,
                    "kind": str(info.get("kind") or "stopwatch"),
                    "title": str(info.get("title") or ""),
                    "duration_ms": int(info.get("duration_ms") or 0),
                    "force": bool(info.get("force")),
                    "with_controls": bool(info.get("with_controls")),
                    "controls_armed": bool(info.get("controls_armed")),
                    "with_media": bool(info.get("with_media")),
                    "show_timer_face": bool(info.get("show_timer_face", True)),
                    "on_done": info.get("on_done"),
                    "running": bool(info.get("running")),
                    "accum_ms": accum,
                    "done": bool(info.get("done")),
                    "x": wx,
                    "y": wy,
                }
            )
        if not snaps:
            # 清缓存，下次打开用新尺寸小人
            try:
                self._desk_clock_walkers.clear()
            except Exception:
                pass
            self._desk_clock_sleep_frames = None
            self._desk_clock_sleep_size = 0
            return
        sleep_sess = getattr(self, "_sleep_session_start_ms", 0)
        music_sess = getattr(self, "_music_session_start_ms", 0)
        try:
            self._desk_clock_walkers.clear()
        except Exception:
            pass
        self._desk_clock_sleep_frames = None
        self._desk_clock_sleep_size = 0
        for snap in snaps:
            slot = snap["slot"]
            self._hide_desk_clock(slot)
            self._start_desk_clock(
                slot,
                kind=snap["kind"],
                title=snap["title"],
                duration_ms=snap["duration_ms"],
                force=True if slot in ("tool_sw", "tool_cd", "music") else bool(snap["force"]),
                with_controls=bool(snap["with_controls"]),
                controls_armed=False,  # 先不自动跑，恢复 accum 后再决定
                with_media=bool(snap["with_media"]),
                show_timer_face=bool(snap.get("show_timer_face", True)),
                on_done=snap["on_done"],
            )
            info = self._desk_clocks.get(slot)
            if not info:
                continue
            info["accum_ms"] = int(snap["accum_ms"] or 0)
            info["done"] = bool(snap["done"])
            info["running"] = False
            info["segment_start_ms"] = 0
            if snap["running"] and not snap["done"]:
                info["running"] = True
                info["segment_start_ms"] = int(time.time() * 1000)
            if snap["x"] is not None and snap["y"] is not None:
                try:
                    info["win"].geometry(f"+{int(snap['x'])}+{int(snap['y'])}")
                except Exception:
                    pass
            self._draw_desk_clock(slot)
        # 尺寸重建不应重置本局睡眠/音乐会话起点
        try:
            self._sleep_session_start_ms = sleep_sess
            self._music_session_start_ms = music_sess
        except Exception:
            pass

    def _sync_auto_desk_clocks(self) -> None:
        """按当前模式同步睡眠/音乐/工作自动时钟（受「时间显示」开关控制）。"""
        if not getattr(self, "_startup_ready", False) or self._closing:
            return
        show = self._timers_display_enabled()

        # 睡眠（番茄休息段用独立倒计时，不叠睡眠秒表）
        pomo_rest = (
            getattr(self, "_pomodoro_active", False)
            and str(getattr(self, "_pomodoro_phase", "") or "") == "rest"
        )
        if show and self.mode == "quiet" and not pomo_rest:
            if not self._desk_clock_active("sleep"):
                self._start_desk_clock("sleep", kind="stopwatch", title="睡眠")
        else:
            self._hide_desk_clock("sleep")

        # 音乐：时间显示关只去掉秒表面，媒体键 ⏮⏯⏭⏹ 必须保留
        if getattr(self, "music_sprite_mode", False):
            want_face = show
            info = self._desk_clocks.get("music")
            active = self._desk_clock_active("music")
            face_ok = bool(info and bool(info.get("show_timer_face", True)) == want_face)
            media_ok = bool(info and info.get("with_media"))
            if not active or not media_ok or not face_ok:
                music_sess = int(getattr(self, "_music_session_start_ms", 0) or 0)
                wx = wy = None
                if active and info:
                    win = info.get("win")
                    try:
                        if win is not None and win.winfo_exists():
                            parts = win.geometry().split("+")
                            if len(parts) >= 3:
                                wx, wy = int(parts[1]), int(parts[2])
                    except Exception:
                        pass
                self._start_desk_clock(
                    "music",
                    kind="stopwatch",
                    title="音乐",
                    force=True,
                    with_media=True,
                    show_timer_face=want_face,
                )
                if music_sess > 0:
                    self._music_session_start_ms = music_sess
                info2 = self._desk_clocks.get("music")
                if info2 and wx is not None and wy is not None:
                    try:
                        info2["win"].geometry(f"+{wx}+{wy}")
                    except Exception:
                        pass
            else:
                self._ensure_desk_clock_on_screen("music")
        else:
            self._hide_desk_clock("music")

        # 番茄休息倒计时：工具功能，不受「时间显示」影响
        if pomo_rest:
            if not self._desk_clock_active("pomodoro_rest"):
                rem = int(getattr(self, "_pomodoro_rest_deadline_ms", 0) or 0) - int(time.time() * 1000)
                if rem <= 0:
                    rem = int(getattr(self, "_pomodoro_rest_ms", 0) or 0)
                rem = max(1000, rem)
                self._start_desk_clock(
                    "pomodoro_rest",
                    kind="countdown",
                    title=self._pomodoro_clock_title("rest"),
                    duration_ms=rem,
                    force=True,
                    with_controls=True,
                    controls_armed=True,
                    on_done=self._on_pomodoro_rest_done,
                )
            else:
                self._ensure_desk_clock_on_screen("pomodoro_rest")
        elif not getattr(self, "_pomodoro_transitioning", False):
            if str(getattr(self, "_pomodoro_phase", "") or "") != "rest":
                self._hide_desk_clock("pomodoro_rest")

        # 工作：自由秒表仅 show 时；自定义/番茄倒计时为到点结束所必需，仍显示
        if self.state == "work":
            kind = getattr(self, "_work_timer_kind", "stopwatch") or "stopwatch"
            dur = int(getattr(self, "_work_timer_duration_ms", 0) or 0)
            pomo = bool(getattr(self, "_pomodoro_active", False))
            need_countdown = kind == "countdown" and dur > 0
            if show or need_countdown:
                if not self._desk_clock_active("work"):
                    if need_countdown:
                        self._start_desk_clock(
                            "work",
                            kind="countdown",
                            title=self._pomodoro_clock_title("work") if pomo else "工作·定时",
                            duration_ms=dur,
                            force=True,
                            with_controls=pomo,
                            controls_armed=pomo,
                            on_done=self._on_work_countdown_done,
                        )
                    elif show:
                        self._start_desk_clock("work", kind="stopwatch", title="工作")
            else:
                self._hide_desk_clock("work")
        else:
            self._hide_desk_clock("work")

    def _toggle_tool_stopwatch(self) -> None:
        self._hide_main_menu()
        if self._desk_clock_active("tool_sw"):
            self._hide_desk_clock("tool_sw")
            self._show_toast("秒表已关闭", "#8899aa")
            return
        self._start_desk_clock("tool_sw", kind="stopwatch", title="秒表", force=True, with_controls=True)
        self._note_achievement_flag("timer_use")
        self._show_toast("秒表已开启（⏸ 暂停 · ▶ 开始 · ⏹ 停止 · 可拖动）", "#88ffcc")

    def _open_tool_timer_dialog(self) -> None:
        self._hide_main_menu()
        old = getattr(self, "timer_setup_win", None)
        if old and old.winfo_exists():
            try:
                old.lift()
                old.focus_force()
            except Exception:
                pass
            return
        win = tk.Toplevel(self.root)
        self.timer_setup_win = win
        win.title("计时器")
        self._apply_window_layer(win)
        win.configure(bg=MENU_BG)
        frame = tk.Frame(win, bg=MENU_BG, padx=12, pady=10)
        frame.pack()
        tk.Label(frame, text="计时器", font=PIXEL_FONT, fg=THEME_PINK, bg=MENU_BG).pack(anchor=tk.W)
        tk.Label(frame, text="设定倒计时（到点提示）", font=("Courier New", 8), fg="#8899aa", bg=MENU_BG).pack(
            anchor=tk.W, pady=(2, 6)
        )
        row = tk.Frame(frame, bg=MENU_BG)
        row.pack(fill=tk.X)
        tk.Label(row, text="分", font=PIXEL_FONT, fg=MENU_FG, bg=MENU_BG).pack(side=tk.LEFT)
        mins = tk.Entry(row, width=4, font=PIXEL_FONT)
        mins.pack(side=tk.LEFT, padx=(4, 10))
        mins.insert(0, "25")
        tk.Label(row, text="秒", font=PIXEL_FONT, fg=MENU_FG, bg=MENU_BG).pack(side=tk.LEFT)
        secs = tk.Entry(row, width=4, font=PIXEL_FONT)
        secs.pack(side=tk.LEFT, padx=(4, 0))
        secs.insert(0, "0")

        def start() -> None:
            try:
                m = max(0, int(mins.get().strip() or "0"))
                s = max(0, min(59, int(secs.get().strip() or "0")))
            except ValueError:
                self._show_toast("请输入有效时间", "#ff8866")
                return
            total_ms = (m * 60 + s) * 1000
            if total_ms < 1000:
                self._show_toast("至少 1 秒", "#ff8866")
                return
            try:
                win.destroy()
            except Exception:
                pass
            self.timer_setup_win = None
            self._start_desk_clock(
                "tool_cd",
                kind="countdown",
                title="计时器",
                duration_ms=total_ms,
                force=True,
                with_controls=True,
            )
            self._note_achievement_flag("timer_use")
            self._show_toast(
                f"计时器 {desktop_clock.format_duration_cn(total_ms / 1000)}（点 ▶ 开始）",
                "#ffcc66",
            )

        self._icon_transport_btn(frame, "▶", start, primary=True, tip="开始").pack(
            anchor=tk.E, pady=(10, 0),
        )
        self._place_panel_popup(win)

    def _open_pomodoro_dialog(self) -> None:
        self._hide_main_menu()
        if getattr(self, "_pomodoro_active", False):
            self._end_pomodoro(toast=True, interrupted=False)
            return
        old = getattr(self, "pomodoro_setup_win", None)
        if old and old.winfo_exists():
            try:
                old.lift()
                old.focus_force()
            except Exception:
                pass
            return
        win = tk.Toplevel(self.root)
        self.pomodoro_setup_win = win
        win.title("番茄钟")
        self._apply_window_layer(win)
        win.configure(bg=MENU_BG)
        frame = tk.Frame(win, bg=MENU_BG, padx=12, pady=10)
        frame.pack()
        tk.Label(frame, text="番茄钟", font=PIXEL_FONT, fg=THEME_PINK, bg=MENU_BG).pack(anchor=tk.W)
        tk.Label(
            frame,
            text="工作=运送 · 休息=睡眠；到点自动循环，可随时结束",
            font=("Courier New", 8),
            fg="#8899aa",
            bg=MENU_BG,
        ).pack(anchor=tk.W, pady=(2, 8))

        def _row(label: str, default_m: str) -> tk.Entry:
            r = tk.Frame(frame, bg=MENU_BG)
            r.pack(fill=tk.X, pady=2)
            tk.Label(r, text=label, font=PIXEL_FONT, fg=MENU_FG, bg=MENU_BG, width=8, anchor=tk.W).pack(side=tk.LEFT)
            e = tk.Entry(r, width=4, font=PIXEL_FONT)
            e.pack(side=tk.LEFT, padx=(4, 4))
            e.insert(0, default_m)
            tk.Label(r, text="分", font=PIXEL_FONT, fg=MENU_FG, bg=MENU_BG).pack(side=tk.LEFT)
            return e

        work_e = _row("工作", "25")
        rest_e = _row("休息", "5")

        def start() -> None:
            try:
                wm = max(0, int(work_e.get().strip() or "0"))
                rm = max(0, int(rest_e.get().strip() or "0"))
            except ValueError:
                self._show_toast("请输入有效分钟数", "#ff8866")
                return
            work_ms = wm * 60 * 1000
            rest_ms = rm * 60 * 1000
            if work_ms < 1000 or rest_ms < 1000:
                self._show_toast("工作与休息至少各 1 秒", "#ff8866")
                return
            try:
                win.destroy()
            except Exception:
                pass
            self.pomodoro_setup_win = None
            self._start_pomodoro(work_ms, rest_ms)

        self._icon_transport_btn(frame, "▶", start, primary=True, tip="开始").pack(
            anchor=tk.E, pady=(10, 0),
        )
        self._place_panel_popup(win)

    def _start_pomodoro(self, work_ms: int, rest_ms: int) -> None:
        self._pomodoro_token = int(getattr(self, "_pomodoro_token", 0)) + 1
        self._pomodoro_active = True
        self._pomodoro_phase = "work"
        self._pomodoro_work_ms = max(1000, int(work_ms))
        self._pomodoro_rest_ms = max(1000, int(rest_ms))
        self._pomodoro_transitioning = False
        self._pomodoro_round = 1
        self._pomodoro_completed = 0
        self._hide_desk_clock("pomodoro_rest")
        self._note_achievement_flag("timer_use")
        self._show_toast(
            f"番茄钟开始 · 第 1 轮 · 工作 {desktop_clock.format_duration_cn(self._pomodoro_work_ms / 1000)}"
            f" / 休息 {desktop_clock.format_duration_cn(self._pomodoro_rest_ms / 1000)}",
            "#ff8866",
            duration_ms=2800,
        )
        self._pomodoro_begin_work()

    def _pomodoro_clock_title(self, phase: str) -> str:
        rnd = max(1, int(getattr(self, "_pomodoro_round", 1) or 1))
        if phase == "rest":
            return f"番茄·休息 ·第{rnd}轮"
        return f"番茄·工作 ·第{rnd}轮"

    def _pomodoro_begin_work(self) -> None:
        if not getattr(self, "_pomodoro_active", False):
            return
        tok = int(getattr(self, "_pomodoro_token", 0))
        self._pomodoro_phase = "work"
        self._hide_desk_clock("pomodoro_rest")
        if self.mode == "quiet":
            self._pomodoro_transitioning = True
            try:
                self._leave_quiet_mode()
                self.mode = "free"
                self.state = "stand"
                self.action_name = ""
                self._set_image(self._current_stand_sprite())
            finally:
                self._pomodoro_transitioning = False
        if tok != getattr(self, "_pomodoro_token", 0) or not self._pomodoro_active:
            return
        self._begin_work_boot_busy()
        self._start_work_impl(
            WORK_BOX_TOTAL_DEFAULT,
            flag_movable=True,
            continuous=True,
            kind="pomodoro",
            timer_kind="countdown",
            timer_duration_ms=self._pomodoro_work_ms,
        )

    def _pomodoro_begin_rest(self) -> None:
        if not getattr(self, "_pomodoro_active", False):
            return
        tok = int(getattr(self, "_pomodoro_token", 0))
        self._pomodoro_phase = "rest"
        self._pomodoro_transitioning = True
        try:
            if self.state == "work" or self.mode == "work":
                self._complete_work_session(reason="pomodoro")
                self._stop_work_mode(leave_mode=True)
                self.mode = "free"
                self.state = "stand"
                self.work_animating = False
                self.action_name = ""
                self._set_image(self._current_stand_sprite())
                self._place_window(light=True)
            if tok != getattr(self, "_pomodoro_token", 0) or not self._pomodoro_active:
                return
            # 直接进睡眠，避免再弹一层模式 busy
            if self._mode_switch_take_pre_cleaned():
                self._mode_switch_light_prepare()
            else:
                self.interaction_token += 1
                self._cancel_idle_chain()
            self.mode = "quiet"
            self.follow_animating = False
            self.rest_base_y = self.y
            self.state = "rest"
            self._set_image(self.sprites.sleep[1])
            self._show_sleep_zzz()
            self._schedule_rest_bobble()
            self._schedule_quiet_sleep_voice()
            self._sync_sleep_end_button()
            self._note_mode_for_achievement("quiet")
            self._hide_desk_clock("sleep")
            self._pomodoro_rest_deadline_ms = int(time.time() * 1000) + int(self._pomodoro_rest_ms)
            self._start_desk_clock(
                "pomodoro_rest",
                kind="countdown",
                title=self._pomodoro_clock_title("rest"),
                duration_ms=self._pomodoro_rest_ms,
                force=True,
                with_controls=True,
                controls_armed=True,
                on_done=self._on_pomodoro_rest_done,
            )
            rnd = max(1, int(getattr(self, "_pomodoro_round", 1) or 1))
            self._show_toast(
                f"第 {rnd} 轮休息 {desktop_clock.format_duration_cn(self._pomodoro_rest_ms / 1000)} · 到点继续",
                "#88ccff",
                duration_ms=2400,
            )
        finally:
            self._pomodoro_transitioning = False

    def _on_pomodoro_work_done(self) -> None:
        if not getattr(self, "_pomodoro_active", False):
            return
        if str(getattr(self, "_pomodoro_phase", "") or "") != "work":
            return
        rnd = max(1, int(getattr(self, "_pomodoro_round", 1) or 1))
        self._show_toast(f"第 {rnd} 轮工作结束，进入休息", "#ffcc66", duration_ms=1800)
        self._pomodoro_begin_rest()

    def _on_pomodoro_rest_done(self) -> None:
        if not getattr(self, "_pomodoro_active", False):
            return
        if str(getattr(self, "_pomodoro_phase", "") or "") != "rest":
            return
        done = int(getattr(self, "_pomodoro_completed", 0) or 0) + 1
        self._pomodoro_completed = done
        self._pomodoro_round = done + 1
        self._show_toast(f"第 {done} 轮番茄完成 · 开始第 {self._pomodoro_round} 轮", "#88ffcc", duration_ms=2400)
        if done > 0 and done % 4 == 0:
            self.root.after(
                800,
                lambda n=done: self._show_toast(
                    f"本会话已完成 {n} 轮番茄，节奏不错！",
                    "#ffcc66",
                    duration_ms=2800,
                ),
            )
        self._pomodoro_begin_work()

    def _clear_pomodoro_flags(self) -> None:
        self._pomodoro_active = False
        self._pomodoro_phase = ""
        self._pomodoro_transitioning = False
        self._pomodoro_rest_deadline_ms = 0
        self._hide_desk_clock("pomodoro_rest")

    def _cancel_pomodoro_if_external(self, *, toast: bool = True) -> None:
        """被其它模式/打断切走时清番茄状态。"""
        if not getattr(self, "_pomodoro_active", False):
            return
        if getattr(self, "_pomodoro_transitioning", False):
            return
        self._pomodoro_token = int(getattr(self, "_pomodoro_token", 0)) + 1
        self._clear_pomodoro_flags()
        if toast:
            self._show_toast("番茄钟已中断", "#8899aa")

    def _end_pomodoro(self, *, toast: bool = True, interrupted: bool = False) -> None:
        if not getattr(self, "_pomodoro_active", False) and not getattr(self, "_pomodoro_phase", ""):
            if toast:
                self._show_toast("番茄钟未在运行", "#8899aa")
            return
        self._pomodoro_token = int(getattr(self, "_pomodoro_token", 0)) + 1
        phase = str(getattr(self, "_pomodoro_phase", "") or "")
        self._pomodoro_transitioning = True
        try:
            self._clear_pomodoro_flags()
            if phase == "work" or self.state == "work" or self.mode == "work":
                if self.state == "work" or self.mode == "work":
                    self._exit_work_to_free(reason="pomodoro_end", celebrate=False)
            elif phase == "rest" or self.mode == "quiet":
                if self.mode == "quiet":
                    self._leave_quiet_mode()
                    self.mode = "free"
                    self.state = "stand"
                    self.action_name = ""
                    self._set_image(self._current_stand_sprite())
                    self._place_window(light=True)
                    self._resume_idle()
            if toast:
                tip = "番茄钟已中断" if interrupted else "番茄钟已结束"
                self._show_toast(tip, "#8899aa")
        finally:
            self._pomodoro_transitioning = False

    def _work_total_seconds_stat(self) -> float:
        return self._mode_session_total_seconds("work")

    def _add_work_total_seconds(self, seconds: float) -> float:
        return self._add_mode_session_total_seconds("work", seconds)

    def _mode_session_total_seconds(self, kind: str) -> float:
        key = _MODE_SESSION_TOTAL_KEYS.get(kind, f"{kind}_total_seconds")
        stats = self.achievements.setdefault("stats", {})
        stored = float(stats.get(key) or 0)
        mode_key = {"work": "work", "sleep": "quiet", "music": "music"}.get(kind, kind)
        bucket = stats.get("mode_seconds") if isinstance(stats.get("mode_seconds"), dict) else {}
        live = float(bucket.get(mode_key) or 0)
        return max(stored, live)

    def _add_mode_session_total_seconds(self, kind: str, seconds: float) -> float:
        key = _MODE_SESSION_TOTAL_KEYS.get(kind, f"{kind}_total_seconds")
        stats = self.achievements.setdefault("stats", {})
        cur = self._mode_session_total_seconds(kind) + max(0.0, float(seconds))
        stats[key] = cur
        mode_key = {"work": "work", "sleep": "quiet", "music": "music"}.get(kind)
        if mode_key:
            bucket = stats.setdefault("mode_seconds", {})
            if not isinstance(bucket, dict):
                bucket = {}
                stats["mode_seconds"] = bucket
            bucket[mode_key] = max(float(bucket.get(mode_key) or 0), cur)
        try:
            _save_achievements(self.achievements)
        except Exception:
            pass
        return cur

    def _mode_session_finish_message(self, kind: str, session_sec: float) -> str:
        owner = _owner_display_name(self.pet_profile) or self.owner_name or "你"
        session_sec = max(0.0, float(session_sec or 0))
        try:
            # 结算前刷入当前模式时长，与所属人页的 mode_seconds 对齐
            self._flush_mode_time(save=False)
        except Exception:
            pass
        mode_key = {"work": "work", "sleep": "quiet", "music": "music"}.get(kind, kind)
        stats = self.achievements.setdefault("stats", {})
        bucket = stats.setdefault("mode_seconds", {})
        if not isinstance(bucket, dict):
            bucket = {}
            stats["mode_seconds"] = bucket
        legacy_key = _MODE_SESSION_TOTAL_KEYS.get(kind, f"{kind}_total_seconds")
        live = float(bucket.get(mode_key) or 0)
        stored = float(stats.get(legacy_key) or 0)
        base = max(live, stored)
        # mode 桶通常已含本局；若明显偏小则补上，避免重复累加
        if base + 1.0 < session_sec:
            total = session_sec
        elif base + 1.0 < stored + session_sec and live + 1.0 < stored + session_sec:
            # 会话键曾丢过、mode 桶也偏旧：按「旧累计+本局」
            total = max(base, stored) + session_sec
        else:
            total = max(base, session_sec)
        prev_before = max(0.0, total - session_sec)
        first = prev_before < 0.5
        bucket[mode_key] = max(live, total)
        stats[legacy_key] = max(stored, total)
        try:
            _save_achievements(self.achievements)
        except Exception:
            pass
        pack = _MODE_SESSION_FINISH_LINES.get(kind) or _MODE_SESSION_FINISH_LINES["work"]
        lines = pack["first"] if first else pack["again"]
        last = (getattr(self, "_session_finish_last_line", {}) or {}).get(kind, "")
        candidates = [ln for ln in lines if ln != last]
        if not candidates:
            candidates = list(lines)
        template = random.choice(candidates)
        msg = template.format(
            owner=owner,
            session=desktop_clock.format_duration_cn(session_sec),
            total=desktop_clock.format_duration_cn(total),
        )
        self._session_finish_last_line[kind] = template
        return msg

    def _read_mode_session_seconds(self, slot: str, start_ms_attr: str) -> float:
        start = int(getattr(self, start_ms_attr, 0) or 0)
        info = self._desk_clocks.get(slot)
        if start <= 0 and not info:
            return 0.0
        now = int(time.time() * 1000)
        session = max(0.0, (now - start) / 1000.0) if start > 0 else 0.0
        if info and str(info.get("kind")) == "stopwatch":
            session = max(session, self._desk_clock_elapsed_ms(info) / 1000.0)
        elif info and str(info.get("kind")) == "countdown":
            dur = int(info.get("duration_ms") or 0) / 1000.0
            elapsed = dur - self._desk_clock_elapsed_ms(info) / 1000.0
            session = max(session, max(0.0, elapsed))
        return session

    def _complete_mode_timed_session(self, kind: str) -> bool:
        """结束工作/睡眠/音乐会话：时间显示相关结算文案。返回是否已提示。"""
        slot_attr = {
            "work": ("work", "_work_session_start_ms"),
            "sleep": ("sleep", "_sleep_session_start_ms"),
            "music": ("music", "_music_session_start_ms"),
        }.get(kind)
        if not slot_attr:
            return False
        slot, start_attr = slot_attr
        # 睡眠/音乐：仅在「时间显示」开（或本局有秒表面）时说结束语；仅媒体键不算
        if kind in ("sleep", "music"):
            info = self._desk_clocks.get(slot)
            had_face = bool(
                info
                and self._desk_clock_active(slot)
                and info.get("show_timer_face", True)
            )
            if not self._timers_display_enabled() and not had_face:
                setattr(self, start_attr, 0)
                return False
        session = self._read_mode_session_seconds(slot, start_attr)
        self._hide_desk_clock(slot)
        setattr(self, start_attr, 0)
        if session < 0.5:
            return False
        msg = self._mode_session_finish_message(kind, session)
        self._show_toast(msg, "#88ffcc", duration_ms=4200)
        return True

    def _work_finish_message(self, session_sec: float) -> str:
        return self._mode_session_finish_message("work", session_sec)

    def _complete_work_session(self, *, reason: str = "done") -> None:
        """结束工作会话：结算时长文案、收时钟。"""
        self._complete_mode_timed_session("work")

    def _on_work_countdown_done(self) -> None:
        if self.state != "work":
            return
        if (
            getattr(self, "_pomodoro_active", False)
            and str(getattr(self, "_pomodoro_phase", "") or "") == "work"
        ):
            self._on_pomodoro_work_done()
            return
        self._show_toast("工作定时到！", "#ffcc66", duration_ms=1800)
        # 自定义定时 / 自由运送定时：一律退出工作并回自由
        self._exit_work_to_free(reason="timer", celebrate=True)

    def _finish_game(self) -> None:
        if self.mode != "game":
            return
        catches = self.game_catches
        misses = self.game_misses
        score = self.game_score
        session_food = dict(self.game_session_food)
        self._stop_game_mode()
        self.mode = "free"
        self.state = "stand"
        self._set_image(self.sprites.stand)
        bonus_mood = min(5, catches // 3)
        if bonus_mood > 0:
            self.mood = min(100, self.mood + bonus_mood)
            self._refresh_panel()
        self._save_game_record(
            "gather",
            {
                "catches": catches,
                "misses": misses,
                "score": score,
                "difficulty": self.difficulty,
                "food": session_food,
            },
        )
        detail = self._format_food_counts(session_food)
        coin_gain = min(15, max(0, score // 25 + catches // 3))
        if coin_gain > 0:
            self.grant_coins(coin_gain, reason=f"采集奖励 +{coin_gain}")
        subtitle = f"接取 {catches} 个 · 得分 {score}\n错过 {misses}  ·  库存 {self._food_inventory_total()}\n{detail}"
        if coin_gain > 0:
            subtitle += f"\n金币 +{coin_gain}"
        self._show_game_clear(
            title="采集完成",
            subtitle=subtitle,
            accent="#ffcc44",
            on_done=self._resume_idle,
        )
        # 差劲：错过 ≥ 接住，或整局 0 接（与结算画面并存，hurt 仅附加）
        if misses >= catches or catches <= 0:
            self._play_game_fail_voice("hurt")

    def _hide_game_clear(self) -> None:
        if self.game_clear_job:
            try:
                self.root.after_cancel(self.game_clear_job)
            except Exception:
                pass
            self.game_clear_job = None
        if self.game_clear_win and self.game_clear_win.winfo_exists():
            self.game_clear_win.destroy()
        self.game_clear_win = None
        self.game_clear_canvas = None

    def _show_game_clear(
        self,
        *,
        title: str,
        subtitle: str = "",
        accent: str = "#44ff88",
        on_done=None,
        hold_ms: int = GAME_CLEAR_HOLD_MS,
        hero_grade: str | None = None,
        hero_color: str | None = None,
    ) -> None:
        self._hide_game_clear()
        self.game_clear_token += 1
        token = self.game_clear_token
        w, h = GAME_CLEAR_W, GAME_CLEAR_H
        sw = self.root.winfo_screenwidth()
        sh = self.root.winfo_screenheight()
        win = tk.Toplevel(self.root)
        self.game_clear_win = win
        win.overrideredirect(True)
        self._apply_window_layer(win)
        win.configure(bg="#060612")
        win.geometry(f"{w}x{h}+{(sw - w) // 2}+{(sh - h) // 2}")
        canvas = tk.Canvas(win, width=w, height=h, bg="#060612", highlightthickness=0)
        canvas.pack()
        self.game_clear_canvas = canvas
        particles = _spawn_game_clear_particles(w, h, hero_color or accent)
        meta = {
            "phase": 0,
            "title": title,
            "subtitle": subtitle,
            "accent": accent,
            "hero_grade": hero_grade,
            "hero_color": hero_color,
        }

        def finish() -> None:
            if token != self.game_clear_token:
                return
            self._hide_game_clear()
            if on_done:
                on_done()

        def tick() -> None:
            if token != self.game_clear_token or not canvas.winfo_exists():
                return
            _draw_game_clear_frame(
                canvas,
                w,
                h,
                meta["phase"],
                title=meta["title"],
                subtitle=meta["subtitle"],
                accent=meta["accent"],
                particles=particles,
                hero_grade=meta["hero_grade"],
                hero_color=meta["hero_color"],
            )
            meta["phase"] += 1
            if meta["phase"] < GAME_CLEAR_FRAMES:
                self.game_clear_job = self.root.after(GAME_CLEAR_MS, tick)
            else:
                self.game_clear_job = self.root.after(hold_ms, finish)

        tick()

    def _cancel_action_defer(self) -> None:
        if self.action_defer_job:
            try:
                self.root.after_cancel(self.action_defer_job)
            except Exception:
                pass
            self.action_defer_job = None

    def _cancel_action_end(self) -> None:
        job = self.action_end_job
        self.action_end_job = None
        if not job:
            return
        try:
            self.root.after_cancel(job)
        except Exception:
            pass

    def _defer_until_not_dragging(self, callback) -> None:
        if not self.dragging:
            callback()
            return
        self._cancel_action_defer()

        def step() -> None:
            self.action_defer_job = None
            if not self._alive():
                return
            if not self.dragging:
                callback()
                return
            self.action_defer_job = self._safe_after(120, step)

        self.action_defer_job = self._safe_after(120, step)

    def _schedule_action_end(
        self,
        *,
        dialog_text: str | None = None,
        callback=None,
        duration_ms: int | None = None,
        action: str | None = None,
        char_ms: int | None = None,
    ) -> None:
        self._cancel_action_end()
        if dialog_text:
            delay = _typing_duration_ms(dialog_text, char_ms=char_ms)
        elif duration_ms is not None:
            delay = duration_ms
        elif action:
            delay = INTERACT_DURATIONS.get(action, INTERACT_DURATIONS["default"])
        else:
            delay = INTERACT_DURATIONS["default"]
        cb = callback or self._after_action

        def _fire() -> None:
            # 先清 job，避免 after_cancel 抛错导致永远卡在 action
            self.action_end_job = None
            cb()

        self.action_end_job = self._safe_after(delay, _fire)

    def _open_food_menu(self, offset_x: int = 120) -> None:
        self._open_eat_food_menu(offset_x=offset_x)

    def _open_eat_food_menu(self, offset_x: int = 120) -> None:
        total = self._food_inventory_total()
        if total <= 0:
            self._show_toast("暂无食物。请先进行采集。", "#ff8844", duration_ms=3000)
            return
        items: list[tuple[str, callable, bool]] = []
        food_items = sorted(FOODS.items(), key=lambda item: (item[1]["mood"], item[1]["stamina"]), reverse=True)
        for food_id, info in food_items:
            count = self.food_inventory.get(food_id, 0)
            label = f"{info['label']} ×{count}  体+{info['stamina']} 心+{info['mood']}"
            enabled = count > 0
            items.append(
                (
                    label,
                    lambda fid=food_id: (self._hide_main_menu(), self._start_food_drag(fid)),
                    enabled,
                )
            )
        self._show_food_pick_menu(items, offset_x=offset_x)

    def _show_food_pick_menu(
        self, items: list[tuple[str, callable, bool]], offset_x: int = 0
    ) -> None:
        self._hide_sub_menu()
        self.sub_menu = tk.Toplevel(self.root)
        self.sub_menu.overrideredirect(True)
        try:
            setattr(self.sub_menu, "_vpet_no_glass", True)
            setattr(self.sub_menu, "_vpet_panel_glass", False)
            setattr(self.sub_menu, "_vpet_menu_overlay", True)
        except Exception:
            pass
        try:
            self.sub_menu.attributes("-topmost", True)
        except Exception:
            pass
        self.sub_menu.configure(bg=MENU_BG)
        frame = tk.Frame(self.sub_menu, bg=MENU_BG, padx=2, pady=2)
        frame.pack()
        tk.Label(
            frame,
            text=f"吃东西  拖给小人 ({self._food_inventory_total()})",
            font=PIXEL_FONT,
            fg=PIXEL_COLOR,
            bg=MENU_BG,
        ).pack(fill=tk.X, pady=(2, 4))
        food_ids = list(FOODS.keys())
        for idx, (label, cmd, enabled) in enumerate(items):
            row = tk.Frame(frame, bg=MENU_BG)
            row.pack(fill=tk.X, pady=1)
            icon = tk.Canvas(row, width=28, height=28, bg=MENU_BG, highlightthickness=0)
            icon.pack(side=tk.LEFT, padx=(4, 2))
            _draw_pixel_food(icon, food_ids[idx], 4, 2, px=3)
            btn = self._menu_btn(row, label, lambda c=cmd: c())
            if not enabled:
                btn.config(state=tk.DISABLED, fg="#666666")
            btn.pack(side=tk.LEFT, fill=tk.X, expand=True)
        self._sub_menu_offset_x = offset_x
        self._place_pet_attached_popup(self.sub_menu, self.x + offset_x, self._sub_menu_pref_y())
        self._bump_main_menu_auto_hide()
        self._lift_menu_above_pet(self.sub_menu)

    def _cancel_food_drag(self) -> None:
        self.food_drag_active = False
        self.food_drag_id = None
        if self.food_drag_win and self.food_drag_win.winfo_exists():
            self.food_drag_win.destroy()
        self.food_drag_win = None
        self.food_drag_canvas = None
        try:
            self.root.unbind("<B1-Motion>")
            self.root.unbind("<ButtonRelease-1>")
        except Exception:
            pass

    def _start_food_drag(self, food_id: str) -> None:
        if self.dragging or food_id not in FOODS:
            return
        if self.state == "action" and self.action_name == "eat":
            return
        if self.food_inventory.get(food_id, 0) <= 0:
            self._show_toast("这种食物没有了！", "#ff8844")
            return
        self._interrupt_current_interaction()
        self.food_drag_active = True
        self.food_drag_id = food_id
        size = FOOD_DRAG_ICON
        self.food_drag_win = tk.Toplevel(self.root)
        self.food_drag_win.overrideredirect(True)
        self._apply_window_layer(self.food_drag_win)
        self.food_drag_win.configure(bg="magenta")
        self.food_drag_win.wm_attributes("-transparentcolor", "magenta")
        self.food_drag_canvas = tk.Canvas(
            self.food_drag_win, width=size, height=size, bg="magenta", highlightthickness=0
        )
        self.food_drag_canvas.pack()
        px = max(3, size // 10)
        _draw_pixel_food(self.food_drag_canvas, food_id, 4, 4, px=px)
        mx = self.root.winfo_pointerx()
        my = self.root.winfo_pointery()
        self.food_drag_win.geometry(f"+{mx - size // 2}+{my - size // 2}")
        self.food_drag_ignore_release_until = int(time.time() * 1000) + 180
        self.root.bind("<B1-Motion>", self._food_drag_motion, add="+")
        self.root.bind("<ButtonRelease-1>", self._food_drag_release, add="+")
        if self.companion_bar_enabled and self.mini_pets:
            tip = "只拖给苍叶松开即可（智能伴侣不用吃，只消耗一份）"
        else:
            tip = "拖动食物到小人上方松开"
        self._show_toast(tip, "#44aa44", duration_ms=2200)

    def _food_drag_motion(self, event: tk.Event) -> None:
        if not self.food_drag_active or not self.food_drag_win:
            return
        if self.state == "action" and self.action_name == "eat":
            return
        size = FOOD_DRAG_ICON
        self.food_drag_win.geometry(f"+{event.x_root - size // 2}+{event.y_root - size // 2}")

    def _food_drop_hit_target(self, x: int, y: int) -> tuple[str, int, int] | None:
        """喂食落点：只喂苍叶。有智能伴侣时伴侣不用吃，也不作为喂食目标。"""
        pet_cx = self.x + self.display_size // 2
        pet_cy = self.y + self.display_size // 2
        if math.hypot(x - pet_cx, y - pet_cy) < self.display_size * 0.65:
            return ("pet", pet_cx, self.y + self.display_size // 4)
        return None

    def _food_drag_release(self, event: tk.Event) -> None:
        if not self.food_drag_active or not self.food_drag_id:
            return
        if self.state == "action" and self.action_name == "eat":
            self._cancel_food_drag()
            return
        if int(time.time() * 1000) < getattr(self, "food_drag_ignore_release_until", 0):
            return
        food_id = self.food_drag_id
        start_x = event.x_root
        start_y = event.y_root
        hit = self._food_drop_hit_target(start_x, start_y)
        self._cancel_food_drag()
        if hit:
            _, tx, ty = hit
            self._animate_food_drop_feed(food_id, start_x, start_y, target_x=tx, target_y=ty)
        else:
            hint = (
                "拖到苍叶上方松开（智能伴侣不用吃）"
                if self.companion_bar_enabled and self.mini_pets
                else "没喂到…再试一次吧"
            )
            self._show_toast(hint, "#ff8844")

    def _animate_food_drop_feed(
        self,
        food_id: str,
        start_x: int,
        start_y: int,
        *,
        target_x: int | None = None,
        target_y: int | None = None,
    ) -> None:
        if food_id not in FOODS or self.food_inventory.get(food_id, 0) <= 0:
            return
        if target_x is None:
            target_x = self.x + self.display_size // 2
        if target_y is None:
            target_y = self.y + self.display_size // 4
        size = FOOD_DRAG_ICON
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)
        self._apply_window_layer(win)
        win.configure(bg="magenta")
        win.wm_attributes("-transparentcolor", "magenta")
        canvas = tk.Canvas(win, width=size, height=size, bg="magenta", highlightthickness=0)
        canvas.pack()
        px = max(3, size // 10)
        _draw_pixel_food(canvas, food_id, 4, 4, px=px)

        start_ms = int(time.time() * 1000)

        def tick() -> None:
            elapsed = int(time.time() * 1000) - start_ms
            t = min(1.0, elapsed / FOOD_DROP_MS)
            ease = t * t
            x = int(start_x + (target_x - start_x) * ease - size // 2)
            arc = int(math.sin(t * math.pi) * FOOD_DROP_ARC)
            y = int(start_y + (target_y - start_y) * ease - size // 2 - arc)
            if t >= 1.0:
                if win.winfo_exists():
                    win.destroy()
                # 只喂苍叶：扣 1 份并只播苍叶吃东西（伴侣不跟吃）
                self._feed_food(food_id, from_drag=True)
                return
            win.geometry(f"+{x}+{y}")
            self.root.after(40, tick)

        tick()

    def _open_backpack_menu(self, offset_x: int = 120) -> None:
        self._open_eat_food_menu(offset_x=offset_x)

    def _feed_food(self, food_id: str, *, from_drag: bool = False) -> None:
        if self.dragging or food_id not in FOODS:
            return
        if self.food_inventory.get(food_id, 0) <= 0:
            self._show_toast("该食物已用尽，请进行采集。", "#ff8844")
            return
        if self.mode == "game":
            self._show_toast("游戏中请先 Esc 退出再接食物", "#ff8844")
            return
        self._interrupt_current_interaction()
        self._hide_main_menu()
        self.food_inventory[food_id] -= 1
        self._persist_food_inventory()
        self._refresh_panel()
        info = FOODS[food_id]
        old_stamina = self.stamina
        old_mood = self.mood
        self.stamina = min(100, self.stamina + info["stamina"])
        self.mood = min(100, self.mood + info["mood"])
        stamina_gain = self.stamina - old_stamina
        mood_gain = self.mood - old_mood
        self._refresh_panel()
        self._show_toast(f"{info['label']}  体力 +{stamina_gain}  心情 +{mood_gain}", "#44aa44")
        try:
            stats = self.achievements.setdefault("stats", {})
            stats["feed_count"] = int(stats.get("feed_count", 0) or 0) + 1
            _save_achievements(self.achievements)
            self._check_achievements(source="feed")
        except Exception:
            pass
        self._play_eat_food(food_id)

    def _play_eat_sound(self) -> None:
        sound = _get_eat_sound()
        self._play_sound_with_volume(sound, "sfx")

    def _play_eat_food(self, food_id: str) -> None:
        self._cancel_food_drag()
        if self.mode == "quiet" and self.state == "rest":
            self._stop_rest_bobble()
        self.state = "action"
        self.action_name = "eat"
        self.action_frame = 0
        frames = self.sprites.actions["eat"]
        self._set_image(frames[0])
        self._trigger_eat_banter()
        self._play_eat_sound()
        self._show_food_fx(food_id)
        if len(frames) > 1:
            self._action_animate()
        self._schedule_action_end(action="eat")

    def _start_music_wave_fx(self, *, force_rebuild: bool = True) -> None:
        if not self.music_sprite_mode:
            return
        if (
            not force_rebuild
            and self.music_wave_win
            and self.music_wave_win.winfo_exists()
            and self.music_wave_canvas
        ):
            if not getattr(self, "_music_wave_job", None):
                self._animate_music_wave()
            return
        self._stop_music_wave_fx()
        pad = MUSIC_WAVE_PAD
        size = self.display_size + pad * 2
        self.music_wave_win = tk.Toplevel(self.root)
        self.music_wave_win.overrideredirect(True)
        try:
            setattr(self.music_wave_win, "_vpet_no_glass", True)
        except Exception:
            pass
        self.music_wave_win.configure(bg="magenta")
        try:
            self.music_wave_win.wm_attributes("-transparentcolor", "magenta")
        except Exception:
            pass
        self._apply_window_layer(self.music_wave_win)
        self.music_wave_canvas = tk.Canvas(
            self.music_wave_win, width=size, height=size, bg="magenta", highlightthickness=0
        )
        self.music_wave_canvas.pack()
        self.music_wave_phase = 0
        self._music_wave_place_sig = None
        self._music_wave_lift_counter = 0
        self._place_music_wave(force=True)
        self._animate_music_wave()

    def _stop_music_wave_fx(self) -> None:
        job = getattr(self, "_music_wave_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
            self._music_wave_job = None
        if self.music_wave_win and self.music_wave_win.winfo_exists():
            try:
                self.music_wave_win.destroy()
            except Exception:
                pass
        self.music_wave_win = None
        self.music_wave_canvas = None
        self._music_wave_place_sig = None

    def _place_music_wave(self, *, force: bool = False) -> None:
        if not self.music_wave_win or not self.music_wave_win.winfo_exists():
            return
        pad = MUSIC_WAVE_PAD
        display_y = self.y + self.click_bounce_offset
        sig = (int(self.x - pad), int(display_y - pad))
        if not force and sig == getattr(self, "_music_wave_place_sig", None):
            return
        self._music_wave_place_sig = sig
        self.music_wave_win.geometry(f"+{sig[0]}+{sig[1]}")
        # 走动时跳过 z-order；静止时偶发把立绘抬到声波之上（勿全量 restack 防闪）
        if self.state == "walk" and not force:
            return
        self._music_wave_lift_counter = int(getattr(self, "_music_wave_lift_counter", 0) or 0) + 1
        if force or self._music_wave_lift_counter >= 24:
            self._music_wave_lift_counter = 0
            try:
                self.music_wave_win.lower(self.root)
            except Exception:
                pass
            try:
                self.root.lift()
            except Exception:
                pass

    def _animate_music_wave(self) -> None:
        self._music_wave_job = None
        if not self.music_wave_canvas or not self._music_wave_should_show():
            self._stop_music_wave_fx()
            return
        pad = MUSIC_WAVE_PAD
        size = self.display_size + pad * 2
        walking = self.state == "walk"
        # 统一轻量椭圆环（像素环 create 过多会拖主线程）
        _draw_music_wave(
            self.music_wave_canvas,
            size,
            size,
            self.music_wave_phase,
            colors=self._current_music_wave_colors(),
            lite=True,
        )
        self.music_wave_phase += 1
        self._place_music_wave()
        interval = MUSIC_WAVE_WALK_MS if walking else MUSIC_WAVE_MS
        self._music_wave_job = self.root.after(interval, self._animate_music_wave)

    def _open_panel_menu(self) -> None:
        companion_label = "智能伴侣 ✓" if self.companion_bar_enabled else "智能伴侣"
        jinmu_on = _persona_is_jinmu()
        persona_label = "人格切换 ✓" if jinmu_on else "人格切换"
        self._show_sub_menu(
            [
                ("打开面板", lambda: (self._hide_main_menu(), self._toggle_panel())),
                (companion_label, self._toggle_companion_bar),
                (persona_label, self._toggle_jinmu_persona),
                ("装扮", self._open_outfit_editor),
                ("家园", self._open_home),
                ("邀请", self._open_invite_stub),
                ("莱姆", self._open_rhyme_fight),
                ("暴露", self._play_expose_qte),
            ],
            offset_x=60,
        )

    def _open_invite_stub(self) -> None:
        self._hide_main_menu()
        self._show_toast("尚未开发完全", "#ffcc66", duration_ms=2800)

    def _open_ai_chat_stub(self) -> None:
        """AI 对话：功能未完成，与邀请相同提示。"""
        self._hide_main_menu()
        self._show_toast("尚未开发完全", "#ffcc66", duration_ms=2800)

    def _open_strip_black_stub(self) -> None:
        """立绘去黑框：功能未完成；不是人格切换。"""
        self._show_toast("尚未开发完全", "#ffcc66", duration_ms=2800)

    def _toggle_jinmu_persona(self) -> None:
        """单按钮切换：默认 ↔ 金目（nc 立绘）。"""
        self._hide_main_menu()
        target = PERSONA_DEFAULT if _persona_is_jinmu() else PERSONA_NC
        self._switch_persona(target, from_menu=False, show_dev_tip=True)

    def _regen_nc_outfit_sprites(self) -> None:
        self._hide_main_menu()
        n = ensure_nc_outfit_sprites(force=True)
        if n <= 0:
            self._show_toast("未找到 ncstand，请把金目站立图放到 assets/sprites/ncstand.png", "#ff8844")
            return
        self._show_toast(f"已更新 {n} 张金目动作图", "#88ffaa")
        if _persona_is_jinmu():
            self._reload_persona_sprites()

    def _switch_persona(self, persona: str, *, from_menu: bool = True, show_dev_tip: bool = False) -> None:
        if from_menu:
            self._hide_main_menu()
        key = str(persona or "").strip().lower()
        if key in ("jinmu", "金目"):
            key = PERSONA_NC
        if key not in PERSONA_LABELS:
            return
        if key == PERSONA_NC:
            ensure_nc_outfit_sprites()
            if _find_existing_asset("ncstand.png") is None and _find_existing_asset("ncstand.jpg") is None:
                self._show_toast("缺少 ncstand.png，无法切换金目人格", "#ff8844")
                return
        if key == get_active_persona():
            tip = PERSONA_DEV_TIP if show_dev_tip else f"当前已是「{PERSONA_LABELS[key]}」"
            self._show_toast(tip, "#88ccff" if not show_dev_tip else "#ffcc66", duration_ms=4200 if show_dev_tip else 2000)
            return
        set_active_persona(key)
        self.app_config["persona"] = key
        _save_app_config(self.app_config)
        self._reload_persona_sprites()
        label = PERSONA_LABELS[key]
        if show_dev_tip:
            self._show_toast(f"{PERSONA_DEV_TIP}\n已切换人格：{label}", "#ffcc66", duration_ms=5200)
        else:
            self._show_toast(f"已切换人格：{label}", "#ffcc66")
        if key == PERSONA_NC:
            speech = "……金目，在线。"
        else:
            speech = "嗯，变回原来的我了。"
        self._show_speech_dialog(speech, auto_hide_ms=2600)

    def _reload_persona_sprites(self) -> None:
        """切换人格后重建立绘缓存并刷新当前画面。"""
        persona = get_active_persona()
        cache_key = (self.display_size, persona)
        cached = self._persona_sprite_cache.get(cache_key)
        if cached is not None:
            self.sprites = cached
            self._sprite_cache[self.display_size] = cached
            try:
                self._interrupt_for_mode_switch()
            except Exception:
                pass
            self.state = "stand"
            self.action_name = ""
            self._set_image(self._current_stand_sprite())
            self._place_window()
            return

        # 不整表清空像素缓存，避免来回切换重复解码
        self._sprite_cache.pop(self.display_size, None)
        self._drag_handle_cache.clear()
        self._pet_click_zones_cache.clear()
        self._sprite_building.discard(self.display_size)
        try:
            self._refresh_drag_handle()
        except Exception:
            pass

        size = self.display_size
        self._show_wait_hint("切换人格中")
        self._sprite_building.add(size)

        def worker() -> None:
            pack: dict | None = None
            try:
                pack = _build_sprite_pack(size, persona)
            except Exception:
                pack = None
            self.root.after(0, lambda: self._on_persona_pack_ready(size, persona, pack))

        threading.Thread(target=worker, daemon=True).start()

    def _on_persona_pack_ready(self, size: int, persona: str, pack: dict | None) -> None:
        if self._closing:
            self._sprite_building.discard(size)
            self._hide_wait_hint()
            return
        if pack is None:
            self._sprite_building.discard(size)
            self._hide_wait_hint()
            self._show_toast("人格资源加载失败", "#ff6666")
            return
        if get_active_persona() != persona or size != self.display_size:
            self._sprite_building.discard(size)
            self._hide_wait_hint()
            return

        def on_ready(ss: SpriteSet) -> None:
            if self._closing:
                return
            self.sprites = ss
            self._sprite_cache[size] = ss
            self._persona_sprite_cache[(size, persona)] = ss
            self._sprite_building.discard(size)
            self._hide_wait_hint()
            try:
                self._interrupt_for_mode_switch()
            except Exception:
                pass
            self.state = "stand"
            self.action_name = ""
            img = self._current_stand_sprite()
            self._set_image(img)
            self._place_window()

        self._build_sprite_set_batched(
            size,
            pack,
            on_ready,
            batch_size=PERSONA_SPRITE_BATCH_SIZE,
            batch_ms=PERSONA_SPRITE_BATCH_MS,
        )

    def _close_home(self) -> None:
        """只关编辑窗；桌面家园保留。"""
        self._cancel_home_farm_tick()
        job = getattr(self, "_home_farm_fx_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        self._home_farm_fx_job = None
        self._home_farm_fx = None
        self._home_edit_mode = "decorate"
        if self._home_layout is not None:
            self._home_flush_save()
            self._persist_wallet()
        if self.home_win and self.home_win.winfo_exists():
            try:
                self.home_win.destroy()
            except Exception:
                pass
        self.home_win = None
        self._home_canvas = None
        self._home_status = None
        self._home_mode_btns = {}
        self._home_zone_btns = {}
        self._home_brush_btns = {}
        self._home_brush_host = None
        self._home_bg_host = None
        self._home_bg_brush_btns = {}
        self._home_farm_banner = None
        self._home_hero_canvas = None
        self._home_photos.clear()
        # 若桌面家园还在，继续走动/表情轮询
        if self._home_any_view_open():
            self._schedule_home_tick()
            self._schedule_home_day_cycle()
            return
        self._cancel_home_day_cycle()
        for job_name in ("_home_tick_job", "_home_pose_job"):
            job = getattr(self, job_name, None)
            if job:
                try:
                    self.root.after_cancel(job)
                except Exception:
                    pass
                setattr(self, job_name, None)
        self._home_pose = "stand"
        self._home_last_trigger = ""

    def _home_schedule_save(self, *, delay_ms: int = 400) -> None:
        """涂色/农场等频繁改动合并写盘，减轻卡顿。"""
        job = getattr(self, "_home_save_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        try:
            self._home_save_job = self.root.after(max(80, int(delay_ms)), self._home_flush_save)
        except Exception:
            self._home_flush_save()

    def _home_flush_save(self) -> None:
        job = getattr(self, "_home_save_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        self._home_save_job = None
        layout = self._home_layout
        if not layout:
            return
        try:
            home_room.save_layout(HOME_LAYOUT_FILE, layout)
        except Exception:
            pass

    def _close_home_desktop(self) -> None:
        if self._home_layout is not None:
            self._home_layout["on_desktop"] = False
            try:
                if self.home_desktop_win and self.home_desktop_win.winfo_exists():
                    self._home_layout["desktop_x"] = int(self.home_desktop_win.winfo_x())
                    self._home_layout["desktop_y"] = int(self.home_desktop_win.winfo_y())
            except Exception:
                pass
            self._home_flush_save()
        if self.home_desktop_win and self.home_desktop_win.winfo_exists():
            try:
                self.home_desktop_win.destroy()
            except Exception:
                pass
        self.home_desktop_win = None
        self._home_desktop_canvas = None
        self._home_desktop_photos.clear()
        self._home_desk_drag = None
        self._home_desktop_title = None
        if not self._home_any_view_open():
            self._cancel_home_day_cycle()
            for job_name in ("_home_tick_job", "_home_pose_job"):
                job = getattr(self, job_name, None)
                if job:
                    try:
                        self.root.after_cancel(job)
                    except Exception:
                        pass
                    setattr(self, job_name, None)
            self._home_pose = "stand"
            self._home_last_trigger = ""
        self._show_toast("已从桌面收起家园", "#88ccff")

    def _home_any_view_open(self) -> bool:
        ed = bool(self.home_win and self.home_win.winfo_exists())
        desk = bool(self.home_desktop_win and self.home_desktop_win.winfo_exists())
        return ed or desk

    def _maybe_restore_home_desktop(self) -> None:
        """启动后若上次已放到桌面，自动恢复桌面家园（无需再开编辑窗）。"""
        if self._closing or not self._alive():
            return
        if self.home_desktop_win and self.home_desktop_win.winfo_exists():
            return
        try:
            layout = home_room.load_layout(HOME_LAYOUT_FILE)
        except Exception:
            return
        if not layout.get("on_desktop"):
            return
        self._home_setup_assets()
        self._home_layout = layout
        self._place_home_on_desktop()

    def _home_setup_assets(self) -> None:
        rpg_root = resolve_bundled("Vpetgame", legacy=LEGACY_GAME_ROOT)
        rpg_assets = (rpg_root / "assets") if rpg_root else None
        HOME_PROPS_DIR.mkdir(parents=True, exist_ok=True)
        HOME_RPG_ASSETS_DIR.mkdir(parents=True, exist_ok=True)

        def _sync_art(name: str) -> None:
            src = HOME_PROPS_DIR / name
            if not src.is_file():
                # 也允许从 RPG userdata 回拷
                alt = HOME_RPG_ASSETS_DIR / name
                if alt.is_file():
                    try:
                        shutil.copy2(alt, src)
                    except Exception:
                        return
                else:
                    return
            for dest_dir in (HOME_RPG_ASSETS_DIR,):
                try:
                    dest_dir.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(src, dest_dir / name)
                except Exception:
                    pass
            try:
                local = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
                if local:
                    user_assets = Path(local) / "Vpet" / "rpg" / "assets"
                    user_assets.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(src, user_assets / name)
            except Exception:
                pass
            if rpg_assets is not None:
                try:
                    rpg_assets.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(src, rpg_assets / name)
                except Exception:
                    pass

        _sync_art("gift_art.png")
        _sync_art("user_paint.png")
        HOME_MATERIALS_DIR.mkdir(parents=True, exist_ok=True)
        mats = home_room.load_materials_index(HOME_MATERIALS_INDEX)
        home_room.set_materials_root(HOME_MATERIALS_DIR, mats)
        home_room.set_asset_roots(rpg_assets=rpg_assets, props_dir=HOME_PROPS_DIR)

    def _home_display_name(self) -> str:
        name = ""
        if self._home_layout:
            name = str(self._home_layout.get("house_name") or "").strip()
        return name or "我的小屋"

    def _companion_days(self) -> int:
        """相伴天数（至少 1）。"""
        set_at = str((self.pet_profile or {}).get("owner_set_at") or "")
        start_dt = self._parse_profile_time(set_at) or self._parse_profile_time(
            str((self.pet_profile or {}).get("created") or "")
        )
        if start_dt is None:
            return 1
        return max(1, (datetime.now().date() - start_dt.date()).days + 1)

    def _home_max_rooms(self) -> int:
        return home_room.max_rooms_for_companion_days(self._companion_days())

    def _ask_simple_name(
        self,
        *,
        title: str,
        prompt: str,
        default: str = "",
        max_len: int = 16,
        confirm_text: str = "确定",
    ) -> str | None:
        parent = self.home_win if (self.home_win and self.home_win.winfo_exists()) else self.root
        result: dict[str, str | None] = {"name": None}
        win = tk.Toplevel(parent)
        win.title(title)
        self._apply_window_layer(win)
        win.configure(bg=MENU_BG)
        win.resizable(False, False)
        try:
            win.transient(parent)
            win.grab_set()
            win.attributes("-topmost", True)
        except Exception:
            pass
        frame = tk.Frame(win, bg=MENU_BG, padx=14, pady=12)
        frame.pack()
        tk.Label(frame, text=prompt, font=PIXEL_FONT, fg=THEME_PINK, bg=MENU_BG).pack(anchor=tk.W)
        entry = tk.Entry(frame, width=18, font=PIXEL_FONT)
        entry.pack(anchor=tk.W, pady=(8, 0))
        if default:
            entry.insert(0, default[:max_len])
            entry.select_range(0, tk.END)
        tip = tk.Label(frame, text="", font=("Courier New", 9), fg="#ff8866", bg=MENU_BG)
        tip.pack(anchor=tk.W, pady=(4, 0))
        btns = tk.Frame(frame, bg=MENU_BG)
        btns.pack(fill=tk.X, pady=(10, 0))

        def confirm(_event=None) -> None:
            raw = entry.get().strip()[:max_len]
            if not raw:
                tip.config(text="名字不能为空哦")
                return
            result["name"] = raw
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        def cancel(_event=None) -> None:
            result["name"] = None
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        tk.Button(btns, text=confirm_text, font=PIXEL_FONT, bg=MENU_ACTIVE, fg=MENU_FG, command=confirm).pack(
            side=tk.LEFT
        )
        self._chrome_icon_btn(btns, "cancel", cancel).pack(side=tk.RIGHT)
        entry.bind("<Return>", confirm)
        win.protocol("WM_DELETE_WINDOW", cancel)
        entry.focus_set()
        try:
            win.wait_window()
        except Exception:
            return None
        return result["name"]

    def _ask_home_house_name(self) -> str | None:
        """放到桌面前为房屋命名；取消返回 None。"""
        cur = ""
        if self._home_layout:
            cur = str(self._home_layout.get("house_name") or "").strip()
        return self._ask_simple_name(
            title="房屋命名",
            prompt="给这间屋子起个名字",
            default=cur or "我的小屋",
            confirm_text="确定放到桌面",
        )
    def _place_home_on_desktop(self) -> None:
        """把当前搭好的小屋贴到桌面（无边框可拖动）；先命名房屋。"""
        if self._home_layout is None:
            self._home_setup_assets()
            self._home_layout = home_room.load_layout(HOME_LAYOUT_FILE)
        home_room.sync_active_zone(self._home_layout)

        name = self._ask_home_house_name()
        if name is None:
            return
        self._home_layout["house_name"] = name
        try:
            home_room.save_layout(HOME_LAYOUT_FILE, self._home_layout)
        except Exception:
            pass

        if self.home_desktop_win and self.home_desktop_win.winfo_exists():
            if self._home_desktop_title and self._home_desktop_title.winfo_exists():
                self._home_desktop_title.config(text=self._home_display_name())
            self._home_redraw()
            try:
                self.home_desktop_win.lift()
            except Exception:
                pass
            self._show_toast(f"已更新屋名：{self._home_display_name()}", "#88ccff")
            return

        cols = int(self._home_layout["cols"])
        rows = int(self._home_layout["rows"])
        tile = home_room.HOME_TILE
        room_w = cols * tile
        room_h = rows * tile + 18
        bar_h = 22

        win = tk.Toplevel(self.root)
        self.home_desktop_win = win
        win.overrideredirect(True)
        self._apply_window_layer(win)
        win.configure(bg="#1a2030")
        try:
            setattr(win, "_vpet_no_glass", True)
            setattr(win, "_vpet_panel_glass", False)
            # 明确不透明：清掉可能残留的色键
            win.wm_attributes("-transparentcolor", "")
        except Exception:
            pass
        try:
            win.attributes("-topmost", False)
        except Exception:
            pass

        bar = tk.Frame(win, bg="#243044", height=bar_h)
        bar.pack(fill=tk.X)
        bar.pack_propagate(False)
        title_lbl = tk.Label(
            bar,
            text=self._home_display_name(),
            font=("Courier New", 9),
            fg="#c8d8ff",
            bg="#243044",
        )
        title_lbl.pack(side=tk.LEFT, padx=6)
        self._home_desktop_title = title_lbl
        close_lbl = tk.Label(bar, text="×", font=("Courier New", 12, "bold"), fg="#ff8899", bg="#243044", cursor="hand2")
        close_lbl.pack(side=tk.RIGHT, padx=6)
        close_lbl.bind("<Button-1>", lambda _e: self._close_home_desktop())
        # 双击标题可改名
        def rename_house(_event=None) -> None:
            new_name = self._ask_home_house_name()
            if new_name is None or not self._home_layout:
                return
            self._home_layout["house_name"] = new_name
            title_lbl.config(text=self._home_display_name())
            try:
                home_room.save_layout(HOME_LAYOUT_FILE, self._home_layout)
            except Exception:
                pass
            self._show_toast(f"屋名：{self._home_display_name()}", "#88ccff")

        title_lbl.bind("<Double-Button-1>", rename_house)

        canvas = tk.Canvas(win, width=room_w, height=room_h, bg=home_room.HOME_WALL, highlightthickness=0)
        canvas.pack()
        self._home_desktop_canvas = canvas
        self._home_desktop_photos = []

        def start_drag(event: tk.Event) -> None:
            self._home_desk_drag = (event.x_root, event.y_root, win.winfo_x(), win.winfo_y())

        def do_drag(event: tk.Event) -> None:
            if not self._home_desk_drag:
                return
            ox, oy, wx, wy = self._home_desk_drag
            nx = wx + (event.x_root - ox)
            ny = wy + (event.y_root - oy)
            win.geometry(f"+{nx}+{ny}")

        def end_drag(_event: tk.Event | None = None) -> None:
            self._home_desk_drag = None
            if self._home_layout is not None and win.winfo_exists():
                self._home_layout["desktop_x"] = int(win.winfo_x())
                self._home_layout["desktop_y"] = int(win.winfo_y())
                self._home_layout["on_desktop"] = True
                try:
                    home_room.save_layout(HOME_LAYOUT_FILE, self._home_layout)
                except Exception:
                    pass

        for w in (bar, canvas):
            w.bind("<ButtonPress-1>", start_drag)
            w.bind("<B1-Motion>", do_drag)
            w.bind("<ButtonRelease-1>", end_drag)

        def on_key(event: tk.Event) -> None:
            if event.keysym == "Escape":
                self._close_home_desktop()
                return
            if not self._home_layout:
                return
            mapping = {
                "Up": (0, -1),
                "w": (0, -1),
                "W": (0, -1),
                "Down": (0, 1),
                "s": (0, 1),
                "S": (0, 1),
                "Left": (-1, 0),
                "a": (-1, 0),
                "A": (-1, 0),
                "Right": (1, 0),
                "d": (1, 0),
                "D": (1, 0),
            }
            delta = mapping.get(event.keysym)
            if not delta:
                return
            # 睡觉/坐下/表情时方向键先醒来再切操控走动
            if self._home_pose not in ("stand", "walk"):
                if self._home_pose_job:
                    try:
                        self.root.after_cancel(self._home_pose_job)
                    except Exception:
                        pass
                    self._home_pose_job = None
                self._home_pose_until_ms = 0
                self._home_last_trigger = ""
                self._home_float_tip = ""
                self._home_pose = "stand"
            self._home_layout["move_mode"] = "control"
            # 操控走动期间仍保留表情轮询
            self._schedule_home_tick()
            self._home_try_move_pet(delta[0], delta[1], check_interact=True)

        win.bind("<Key>", on_key)
        win.focus_set()

        dx = int(self._home_layout.get("desktop_x") or -1)
        dy = int(self._home_layout.get("desktop_y") or -1)
        sw = self.root.winfo_screenwidth()
        sh = self.root.winfo_screenheight()
        if dx < 0 or dy < 0:
            dx = max(20, (sw - room_w) // 2)
            dy = max(40, sh - room_h - bar_h - 80)
        dx = max(0, min(dx, sw - room_w - 8))
        dy = max(0, min(dy, sh - room_h - bar_h - 8))
        win.geometry(f"{room_w}x{room_h + bar_h}+{dx}+{dy}")
        self._home_layout["on_desktop"] = True
        self._home_layout["desktop_x"] = dx
        self._home_layout["desktop_y"] = dy
        try:
            home_room.save_layout(HOME_LAYOUT_FILE, self._home_layout)
        except Exception:
            pass

        self._home_redraw()
        self._schedule_home_tick()
        self._schedule_home_day_cycle()
        self._show_toast(
            f"「{self._home_display_name()}」已放到桌面 · 可拖动 · 双击标题改名",
            "#88ccff",
            duration_ms=3200,
            at=self._home_tip_anchor(),
            allow_center=False,
        )


    def _open_home(self) -> None:
        """面板→家园：编辑布置；可放到桌面。"""
        self._hide_main_menu()
        if self.home_win and self.home_win.winfo_exists():
            try:
                self.home_win.lift()
                self.home_win.focus_force()
            except Exception:
                pass
            return

        self._home_setup_assets()
        self.wallet = home_farm.load_wallet(WALLET_FILE)
        self._home_layout = home_room.load_layout(HOME_LAYOUT_FILE)
        self._note_achievement_flag("home_visit")
        zone = str(self._home_layout.get("zone") or "indoor")
        self._home_brush = "plant" if zone == "indoor" else "flower"
        self._home_photos = []
        self._home_drag_last = None
        if not (self.home_desktop_win and self.home_desktop_win.winfo_exists()):
            self._home_pet_dir = "front"
            self._home_walk_frame = 0
            self._home_pose = "stand"
            self._home_pose_until_ms = 0
            self._home_last_trigger = ""
        cols = int(self._home_layout["cols"])
        rows = int(self._home_layout["rows"])
        tile = home_room.HOME_TILE
        room_w = cols * tile
        room_h = rows * tile + 18
