        def on_diff_commit(_evt=None) -> None:
            t = max(0.0, min(1.0, int(diff_scale.get()) / 100.0))
            self._set_difficulty_t(t, toast=True)
            diff_val.config(text=f"{self.difficulty} {int(round(self.difficulty_t * 100))}%")
