    def _wire_panel_auto_hide(self, widget: tk.Misc) -> None:
        for seq in ("<Enter>", "<Button-1>", "<ButtonRelease-1>", "<B1-Motion>"):
            try:
                widget.bind(seq, self._bump_panel_auto_hide, add="+")
            except Exception:
                pass
        try:
            children = widget.winfo_children()
        except Exception:
            return
        for child in children:
            self._wire_panel_auto_hide(child)

    def _reposition_panel(self, *, force: bool = False) -> None:
        if not self.panel_win or not self.panel_win.winfo_exists():
            return
        try:
            self.panel_win.update_idletasks()
        except Exception:
            pass
        if self.panel_canvas and self.panel_canvas.winfo_exists():
            pw = max(self.panel_canvas.winfo_width(), self.panel_canvas.winfo_reqwidth(), 220)
            ph = max(self.panel_canvas.winfo_height(), self.panel_canvas.winfo_reqheight(), 140)
        else:
            pw = max(self.panel_win.winfo_reqwidth(), 220)
            ph = max(self.panel_win.winfo_reqheight(), 140)
        now_ms = int(time.time() * 1000)
        if (
            not force
            and self._panel_sticky_pos is not None
            and now_ms - self._panel_reposition_ms < PANEL_REPOSITION_MIN_MS
        ):
            # 内容变化时仅钳制原位置，避免频繁跳点导致点不到
            px, py = self._clamp_popup_rect(self._panel_sticky_pos[0], self._panel_sticky_pos[1], pw, ph)
            self.panel_win.geometry(f"+{px}+{py}")
            return
        if force or self._panel_sticky_pos is None:
            px, py = self._panel_popup_pos(pw, ph)
            self._panel_sticky_pos = (px, py)
            self._panel_reposition_ms = now_ms
        else:
            px, py = self._clamp_popup_rect(self._panel_sticky_pos[0], self._panel_sticky_pos[1], pw, ph)
            self._panel_sticky_pos = (px, py)
        self.panel_win.geometry(f"+{px}+{py}")

    def _draw_bar(self, canvas: tk.Canvas, value: int, color: str) -> None:
        _draw_panel_bar(canvas, value, color)

    def _food_backpack_signature(self) -> tuple:
        food = tuple(sorted((k, v) for k, v in self.food_inventory.items() if v > 0))
        items = (self.wallet.get("items") if isinstance(getattr(self, "wallet", None), dict) else None) or {}
        mat = tuple(sorted((str(k), int(v)) for k, v in items.items() if int(v or 0) > 0))
        return (food, mat, bool(self._wearing_flower()))

    def _food_backpack_total(self) -> int:
        food_n = sum(v for v in self.food_inventory.values() if v > 0)
        items = (self.wallet.get("items") if isinstance(getattr(self, "wallet", None), dict) else None) or {}
        mat_n = sum(int(v) for v in items.values() if int(v or 0) > 0)
        return food_n + mat_n

    def _draw_bag_material_icon(self, canvas: tk.Canvas, item_id: str, pad: int = 6) -> None:
        """面板背包里经营物资的简易色块图标。"""
        colors = {
            "wood": ("#8a6848", "#c8a878"),
            "fish": ("#3a7aaa", "#88ccee"),
            "flower_cut": ("#c06080", "#ff88aa"),
            "crop_wheat": ("#c8b070", "#f0e090"),
            "crop_berry": ("#aa6688", "#ee5588"),
            "crop_corn": ("#aaba44", "#ffe066"),
            "seed_wheat": ("#a09060", "#e8d888"),
            "seed_berry": ("#886070", "#cc6688"),
            "seed_corn": ("#889944", "#ccdd55"),
            "work_reward_box": ("#8a6040", "#e8c888"),
        }
        a, b = colors.get(item_id, ("#6688aa", "#aaccff"))
        canvas.create_rectangle(pad, pad, PANEL_FOOD_CANVAS - pad, PANEL_FOOD_CANVAS - pad, fill=a, outline=b, width=2)
        if item_id == "work_reward_box":
            # 简易箱形，贴近工作运送箱观感
            inner = pad + 4
            canvas.create_rectangle(
                inner,
                inner + 4,
                PANEL_FOOD_CANVAS - inner,
                PANEL_FOOD_CANVAS - inner,
                fill="#6a4830",
                outline="#f0d090",
                width=1,
            )
            canvas.create_rectangle(
                inner,
                inner,
                PANEL_FOOD_CANVAS - inner,
                inner + 8,
                fill="#a87848",
                outline="#f0d090",
                width=1,
            )
            return
        mark = {
            "wood": "木",
            "fish": "鱼",
            "flower_cut": "花",
            "crop_wheat": "麦",
            "crop_berry": "莓",
            "crop_corn": "玉",
            "seed_wheat": "种",
            "seed_berry": "种",
            "seed_corn": "种",
        }.get(item_id, "物")
        canvas.create_text(
            PANEL_FOOD_CANVAS // 2,
            PANEL_FOOD_CANVAS // 2,
            text=mark,
            fill="#ffffff",
            font=("Courier New", 12, "bold"),
        )

    def _update_panel_backpack_header(self) -> None:
        if not self.backpack_icon_canvas or not self.backpack_icon_canvas.winfo_exists():
            return
        self.backpack_icon_canvas.delete("all")
        _draw_pixel_backpack(
            self.backpack_icon_canvas,
            4,
            2,
            px=2,
            open_bag=self.panel_backpack_open,
        )
        total = self._food_backpack_total()
        if self.backpack_count_label and self.backpack_count_label.winfo_exists():
            self.backpack_count_label.config(text="（空）" if total <= 0 else f"×{total}")
        if self.backpack_hint_label and self.backpack_hint_label.winfo_exists():
            self.backpack_hint_label.config(text="▼" if self.panel_backpack_open else "▶")

    def _set_panel_backpack_open(self, open_bag: bool) -> None:
        self.panel_backpack_open = open_bag
        if self.backpack_content_frame and self.backpack_content_frame.winfo_exists():
            if open_bag:
                self.backpack_content_frame.pack(anchor=tk.W, pady=(4, 0), fill=tk.X)
                sig = self._food_backpack_signature()
                self._panel_backpack_sig = sig
                self._refresh_panel_backpack()
                self._wire_panel_auto_hide(self.backpack_content_frame)
            else:
                self.backpack_content_frame.pack_forget()
        self._update_panel_backpack_header()
        self._schedule_panel_border_layout()

    def _toggle_panel_backpack(self, _event=None) -> None:
        if not (self.panel_win and self.panel_win.winfo_exists()):
            return
        if self.backpack_header_frame and self.backpack_header_frame.winfo_exists():
            play_pixel_click_burst(self.root, self.backpack_header_frame)
        self._set_panel_backpack_open(not self.panel_backpack_open)
        self._bump_panel_auto_hide()

    def _toggle_panel_affinity(self, _event=None) -> None:
        if not (self.panel_win and self.panel_win.winfo_exists()):
            return
        self.panel_affinity_open = not bool(getattr(self, "panel_affinity_open", True))
        content = getattr(self, "panel_affinity_content", None)
        hint = getattr(self, "panel_affinity_hint", None)
        if content and content.winfo_exists():
            if self.panel_affinity_open:
                content.pack(anchor=tk.W, fill=tk.X, pady=(3, 0))
            else:
                content.pack_forget()
        if hint and hint.winfo_exists():
            hint.config(text="▼" if self.panel_affinity_open else "▶")
        self._schedule_panel_border_layout()
        self._bump_panel_auto_hide()

    def _refresh_panel_affinity(self) -> None:
        rows = getattr(self, "panel_affinity_rows", None) or {}
        if not rows:
            return
        peak = _update_affinity_peak_lv(self.music_affinity)
        peak_lbl = getattr(self, "panel_affinity_peak", None)
        if peak_lbl is not None and peak_lbl.winfo_exists():
            peak_lbl.config(text=f"历史最高 Lv.{peak}")
        for ch in _music_char_defs_runtime():
            row = rows.get(ch["id"])
            if not row:
                continue
            bar = row.get("bar")
            lbl = row.get("label")
            if not bar or not bar.winfo_exists():
                continue
            pts = float(self.music_affinity.get(ch["id"], 0) or 0)
            color = row.get("color") or _music_char_color(ch)
            _draw_affinity_panel_bar(bar, pts, color, width=PANEL_BAR_W, height=PANEL_BAR_H - 2)
            if lbl and lbl.winfo_exists():
                lv = _affinity_level(pts)
                pct = _affinity_bar_pct(pts)
                lbl.config(text=f"{ch['label']}  Lv.{lv}  {pct}%  ({int(pts)})", fg=color)

    def _refresh_panel_stats(self) -> None:
        if self.stamina_icon_canvas and self.stamina_icon_canvas.winfo_exists():
            _draw_stamina_pixel_icon(self.stamina_icon_canvas, PANEL_STAT_ICON)
        mood_label, mood_color = _mood_tier_label(self.mood)
        if self.mood_icon_canvas and self.mood_icon_canvas.winfo_exists():
            _draw_mood_pixel_icon(self.mood_icon_canvas, PANEL_STAT_ICON, fill=mood_color)
        self._draw_bar(self.stamina_bar, self.stamina, "#44aa44")
        self._draw_bar(self.mood_bar, self.mood, mood_color)
        self.stamina_label.config(text=f"体力  {self.stamina}")
        self.mood_label.config(text=f"心情  {self.mood}  {mood_label}", fg=mood_color)

    def _refresh_panel_backpack(self) -> None:
        if not self.backpack_grid or not self.backpack_grid.winfo_exists():
            return
        for w in self.backpack_grid.winfo_children():
            w.destroy()
        col = 0
        pad = max(2, (PANEL_FOOD_CANVAS - PANEL_FOOD_ICON_PX * 5) // 2)
        # 经营物资与食物同栏（木头/粮食/鱼/花等）
        bag_items = (self.wallet.get("items") if isinstance(getattr(self, "wallet", None), dict) else None) or {}
        prefer = (
            "work_reward_box",
            "wood",
            "fish",
            "flower_cut",
            "crop_wheat",
            "crop_berry",
            "crop_corn",
            "seed_wheat",
            "seed_berry",
            "seed_corn",
        )
        shown: set[str] = set()
        for item_id in prefer:
            count = max(0, int(bag_items.get(item_id, 0)))
            shown.add(item_id)
            label = home_farm.ITEM_LABELS.get(item_id, item_id)
            wearing = item_id == "flower_cut" and self._wearing_flower()
            if wearing:
                count = count  # 库存为未戴数量；戴着时额外提示
            cell = tk.Frame(self.backpack_grid, bg=PANEL_ITEM_BG, padx=4, pady=3)
            cell.grid(row=col // PANEL_FOOD_COLS, column=col % PANEL_FOOD_COLS, sticky=tk.NW, padx=4, pady=3)
            icon = tk.Canvas(cell, width=PANEL_FOOD_CANVAS, height=PANEL_FOOD_CANVAS, bg="#1e2640", highlightthickness=0)
            icon.pack()
            icon.create_rectangle(0, 0, PANEL_FOOD_CANVAS, PANEL_FOOD_CANVAS, fill="#1e2640", outline=THEME_BLUE_DEEP)
            self._draw_bag_material_icon(icon, item_id)
            name_fg = THEME_PINK if (count > 0 or wearing) else "#666688"
            title = f"{label} ×{count}"
            if wearing:
                title = f"{label} ×{count} ·戴中"
            tk.Label(cell, text=title, font=PIXEL_FONT, fg=name_fg, bg=PANEL_ITEM_BG).pack()
            if item_id == "work_reward_box":
                tip = "可开启 · 点击" if count > 0 else "累计搬箱可得"
            elif item_id == "flower_cut":
                tip = "点击戴/摘花"
            else:
                tip = "经营物资"
            tip_lbl = tk.Label(cell, text=tip, font=("Courier New", 9), fg="#888888", bg=PANEL_ITEM_BG)
            tip_lbl.pack()
            if item_id == "flower_cut":
                def _bind_flower_click(widget: tk.Misc) -> None:
                    widget.bind("<Button-1>", lambda _e: self._toggle_wear_flower(), add="+")
                    try:
                        widget.configure(cursor="hand2")
                    except Exception:
                        pass
                    for child in widget.winfo_children():
                        _bind_flower_click(child)

                _bind_flower_click(cell)
            elif item_id == "work_reward_box" and count > 0:
                def _bind_box_click(widget: tk.Misc) -> None:
                    widget.bind("<Button-1>", lambda _e: self._open_work_reward_box(), add="+")
                    try:
                        widget.configure(cursor="hand2")
                    except Exception:
                        pass
                    for child in widget.winfo_children():
                        _bind_box_click(child)

                _bind_box_click(cell)
            col += 1
        for item_id, count in sorted(bag_items.items()):
            if item_id in shown or int(count or 0) <= 0:
                continue
            label = home_farm.ITEM_LABELS.get(item_id, str(item_id))
            cell = tk.Frame(self.backpack_grid, bg=PANEL_ITEM_BG, padx=4, pady=3)
            cell.grid(row=col // PANEL_FOOD_COLS, column=col % PANEL_FOOD_COLS, sticky=tk.NW, padx=4, pady=3)
            icon = tk.Canvas(cell, width=PANEL_FOOD_CANVAS, height=PANEL_FOOD_CANVAS, bg="#1e2640", highlightthickness=0)
            icon.pack()
            icon.create_rectangle(0, 0, PANEL_FOOD_CANVAS, PANEL_FOOD_CANVAS, fill="#1e2640", outline=THEME_BLUE_DEEP)
            self._draw_bag_material_icon(icon, str(item_id))
            tk.Label(cell, text=f"{label} ×{int(count)}", font=PIXEL_FONT, fg=THEME_PINK, bg=PANEL_ITEM_BG).pack()
            if str(item_id) == "work_reward_box":
                tip = "可开启 · 点击"
                tip_lbl = tk.Label(cell, text=tip, font=("Courier New", 9), fg="#888888", bg=PANEL_ITEM_BG)
                tip_lbl.pack()

                def _bind_box_click2(widget: tk.Misc) -> None:
                    widget.bind("<Button-1>", lambda _e: self._open_work_reward_box(), add="+")
                    try:
                        widget.configure(cursor="hand2")
                    except Exception:
                        pass
                    for child in widget.winfo_children():
                        _bind_box_click2(child)

                _bind_box_click2(cell)
            else:
                tk.Label(cell, text="经营物资", font=("Courier New", 9), fg="#888888", bg=PANEL_ITEM_BG).pack()
            col += 1
        food_items = sorted(
            FOODS.items(),
            key=lambda item: (item[1]["mood"], item[1]["stamina"]),
            reverse=True,
        )
        for food_id, info in food_items:
            count = max(0, int(self.food_inventory.get(food_id, 0)))
            # 全部种类都显示（含 ×0），避免「种类变少」观感
            cell = tk.Frame(self.backpack_grid, bg=PANEL_ITEM_BG, padx=4, pady=3)
            cell.grid(row=col // PANEL_FOOD_COLS, column=col % PANEL_FOOD_COLS, sticky=tk.NW, padx=4, pady=3)
            icon = tk.Canvas(cell, width=PANEL_FOOD_CANVAS, height=PANEL_FOOD_CANVAS, bg="#1e2640", highlightthickness=0)
            icon.pack()
            icon.create_rectangle(0, 0, PANEL_FOOD_CANVAS, PANEL_FOOD_CANVAS, fill="#1e2640", outline=THEME_BLUE_DEEP)
            _draw_pixel_food(icon, food_id, pad, pad, px=PANEL_FOOD_ICON_PX)
            name_fg = THEME_PINK if count > 0 else "#666688"
            tk.Label(cell, text=f"{info['label']} ×{count}", font=PIXEL_FONT, fg=name_fg, bg=PANEL_ITEM_BG).pack()
            tk.Label(
                cell,
                text=f"体+{info['stamina']} 心+{info['mood']}",
                font=("Courier New", 9),
                fg="#888888",
                bg=PANEL_ITEM_BG,
            ).pack()
            col += 1
        if col == 0:
            tk.Label(self.backpack_grid, text="空", font=PIXEL_FONT, fg="#666666", bg=PANEL_ITEM_BG).grid(
                row=0, column=0
            )
        if self.panel_win and self.panel_win.winfo_exists():
            self._wire_panel_auto_hide(self.backpack_grid)

    def _refresh_panel(self) -> None:
        if not self.panel_win or not self.panel_win.winfo_exists():
            return
        self._refresh_panel_stats()
        self._refresh_panel_affinity()
        self._update_panel_backpack_header()
        if self.panel_backpack_open and self.backpack_grid and self.backpack_grid.winfo_exists():
            sig = self._food_backpack_signature()
            if sig != self._panel_backpack_sig:
                self._panel_backpack_sig = sig
                self._refresh_panel_backpack()
        self._schedule_panel_border_layout()

    def _cancel_game_countdown(self) -> None:
        self._countdown_token = getattr(self, "_countdown_token", 0) + 1
        self._countdown_active = False
        self._hide_countdown_overlay()

    def _hide_countdown_overlay(self) -> None:
        win = getattr(self, "countdown_win", None)
        if win and win.winfo_exists():
            win.destroy()
        self.countdown_win = None
        self.countdown_label = None

    def _show_countdown_overlay(self, text: str) -> None:
        self._hide_countdown_overlay()
        self.countdown_win = tk.Toplevel(self.root)
        self.countdown_win.overrideredirect(True)
        self._apply_window_layer(self.countdown_win)
        try:
            self.countdown_win.attributes("-alpha", 0.92)
        except Exception:
            pass
        self.countdown_win.configure(bg="#101018")
        border = tk.Frame(self.countdown_win, bg="#88ccff", padx=2, pady=2)
        border.pack()
        inner = tk.Frame(border, bg="#101018", width=GAME_COUNTDOWN_W, height=GAME_COUNTDOWN_H)
        inner.pack()
        inner.pack_propagate(False)
        self.countdown_label = tk.Label(
            inner,
            text=text,
            font=COUNTDOWN_FONT,
            fg="#ffee88",
            bg="#101018",
        )
        self.countdown_label.place(relx=0.5, rely=0.5, anchor=tk.CENTER)
        cx = self.x + self.display_size // 2 - GAME_COUNTDOWN_W // 2
        cy = self.y + self.display_size // 2 - GAME_COUNTDOWN_H // 2
        self._place_popup(self.countdown_win, max(8, cx), max(8, cy))

    def _start_game_countdown(self, on_ready, *, title: str = "", on_show=None) -> None:
        self._cancel_game_countdown()
        self._countdown_active = True
        token = self._countdown_token
        steps = ("3", "2", "1", "开始")

        def step(i: int = 0) -> None:
            if token != self._countdown_token:
                return
            if i >= len(steps):
                self._countdown_active = False
                self._hide_countdown_overlay()
                if self.mode in ("work",) or self.state == "work":
                    return
                on_ready()
                return
            if i == 0 and on_show:
                on_show()
            self._show_countdown_overlay(steps[i])
            self.root.after(GAME_COUNTDOWN_STEP_MS, lambda: step(i + 1))

        step()

    def _show_toast(
        self,
        text: str,
        color: str = PIXEL_COLOR,
        *,
        duration_ms: int = TOAST_DURATION_MS,
        at: tuple[int, int] | None = None,
        allow_center: bool = True,
    ) -> None:
        self._hide_toast()

        self.toast_win = tk.Toplevel(self.root)
        self.toast_win.overrideredirect(True)
        self._apply_window_layer(self.toast_win)
        self.toast_win.configure(bg="#111122")

        border = tk.Frame(self.toast_win, bg=color, padx=1, pady=1)
        border.pack()
        inner = tk.Frame(border, bg="#111122", padx=10, pady=6)
        inner.pack()
        tk.Label(inner, text=text, font=PIXEL_FONT, fg=color, bg="#111122", justify=tk.LEFT, wraplength=320).pack()

        try:
            self.toast_win.update_idletasks()
            tw = max(int(self.toast_win.winfo_reqwidth()), 1)
            th = max(int(self.toast_win.winfo_reqheight()), 1)
        except Exception:
            tw, th = 160, 40
        if at is not None:
            x, y = self._clamp_popup_rect(int(at[0]), int(at[1]), tw, th)
            try:
                self.toast_win.geometry(f"+{x}+{y}")
            except Exception:
                pass
        else:
            toast_y = max(0, self.y - 36)
            pref_x = self.x + self.display_size + 8
            if allow_center:
                self._place_popup(self.toast_win, pref_x, toast_y)
            else:
                # 勿落到屏幕正中（家园大窗时常会把宠旁位置挤掉）
                gap = POPUP_PET_GAP
                candidates = [
                    (pref_x, toast_y),
                    (self.x + self.display_size + gap, self.y),
                    (self.x - tw - gap, self.y),
                    (self.x, self.y + self.display_size + gap),
                    (self.x + self.display_size // 2 - tw // 2, self.y - th - gap),
                ]
                x, y = self._best_popup_pos(candidates, tw, th)
                try:
                    self.toast_win.geometry(f"+{x}+{y}")
                except Exception:
                    pass
        self.root.after(duration_ms, self._hide_toast)

    def _hide_toast(self) -> None:
        if self.toast_win and self.toast_win.winfo_exists():
            self.toast_win.destroy()
        self.toast_win = None

    def _stamina_tick(self) -> None:
        if not self._alive():
            return
        params = self._difficulty_params()
        if not self._startup_ready:
            self._safe_after(400, self._stamina_tick)
            return
        if self.state == "sleep" or self.mode == "quiet":
            pass
        elif self.stamina > 0:
            self.stamina = max(0, self.stamina - int(params["stamina_decay"]))
            self._refresh_panel()
            if self.stamina <= SLEEP_STAMINA_THRESHOLD:
                self._start_sleep(forced=True)
        if self.mode not in ("game",) and self.mood > 0:
            self._mood_decay_counter += 1
            every = max(1, int(params["mood_decay_every"]))
            if self._mood_decay_counter >= every:
                self._mood_decay_counter = 0
                self.mood = max(0, self.mood - int(params["mood_decay"]))
                self._refresh_panel()
        self._check_hunger_reminder()
        self._safe_after(int(params["stamina_tick_ms"]), self._stamina_tick)

    def _check_hunger_reminder(self) -> None:
        if self.stamina > LOW_STAMINA_THRESHOLD:
            return
        now_ms = int(time.time() * 1000)
        if now_ms - self.last_hunger_reminder_ms < HUNGER_REMINDER_COOLDOWN_MS:
            return
        self.last_hunger_reminder_ms = now_ms
        self._show_toast("肚子饿了，去模式→游戏接食物，再来喂我吧！", "#ff8844", duration_ms=3000)
        # 开语音且有 hungry 资源：强制播（与 eat 同源），不 50/50 丢掉
        if self._vpet_voice_category_ready("hungry"):
            self._addon_voice_vpet("hungry", chain=False, interrupt_busy=True)

    def _add_interact_mood(self) -> None:
        self.mood = min(100, self.mood + INTERACT_MOOD_GAIN)
        self._refresh_panel()

    def _check_mood_happy(self) -> bool:
        if self.mood < MOOD_HAPPY_THRESHOLD or self.dragging:
            return False
        if self.state == "action" and self.action_name in ("happy", "angry", "question"):
            return False
        self.mood = MOOD_AFTER_HAPPY
        self._refresh_panel()
        self._show_toast("心情超好！", PIXEL_COLOR)
        self._play_happy()
        return True

    def _hide_interact_fx(self) -> None:
        if not self.interact_fx_stop_job and not self.interact_fx_win:
            return
        if self.interact_fx_stop_job:
            self.root.after_cancel(self.interact_fx_stop_job)
            self.interact_fx_stop_job = None
        if self.interact_fx_win and self.interact_fx_win.winfo_exists():
            self.interact_fx_win.destroy()
        self.interact_fx_win = None
        self.interact_fx_canvas = None
        self.interact_fx_action = ""
        self._notify_bg_fx_change()

    def _place_interact_fx(self) -> None:
        if not self.interact_fx_win or not self.interact_fx_win.winfo_exists():
            return
        pad = INTERACT_FX_PAD
        display_y = self.y + self.click_bounce_offset
        self.interact_fx_win.geometry(f"+{self.x - pad}+{display_y - pad}")
        self._lift_pet_above_bg_fx()

    def _show_interact_fx(self, action: str) -> None:
        self._hide_interact_fx()
        self.interact_fx_action = action
        self.interact_fx_phase = 0
        pad = INTERACT_FX_PAD
        size = self.display_size + pad * 2
        self.interact_fx_win = tk.Toplevel(self.root)
        self.interact_fx_win.overrideredirect(True)
        self._apply_window_layer(self.interact_fx_win)
        self.interact_fx_win.configure(bg="magenta")
        self.interact_fx_win.wm_attributes("-transparentcolor", "magenta")
        self.interact_fx_canvas = tk.Canvas(
            self.interact_fx_win, width=size, height=size, bg="magenta", highlightthickness=0
        )
        self.interact_fx_canvas.pack()
        self._place_interact_fx()
        self._animate_interact_fx()
        if self.interact_fx_stop_job:
            self.root.after_cancel(self.interact_fx_stop_job)
        self.interact_fx_stop_job = self.root.after(INTERACT_FX_DURATION_MS, self._hide_interact_fx)
        self._notify_bg_fx_change()
        self._lift_pet_above_bg_fx()

    def _animate_interact_fx(self) -> None:
        if not self.interact_fx_canvas or not self.interact_fx_action:
            return
        size = self.interact_fx_canvas.winfo_width() or (self.display_size + INTERACT_FX_PAD * 2)
        _draw_interact_fx(self.interact_fx_canvas, self.interact_fx_action, size, self.interact_fx_phase)
        self.interact_fx_phase += 1
        self._place_interact_fx()
        self.root.after(INTERACT_FX_MS, self._animate_interact_fx)

    def _hide_like_fx(self) -> None:
        if not self.like_glow_job and not self.like_fx_win:
            return
        if self.like_glow_job:
            try:
                self.root.after_cancel(self.like_glow_job)
            except Exception:
                pass
            self.like_glow_job = None
        if self.like_fx_win and self.like_fx_win.winfo_exists():
            self.like_fx_win.destroy()
        self.like_fx_win = None
        self.like_fx_canvas = None
        self._notify_bg_fx_change()

    def _animate_like_glow(self) -> None:
        if not self.like_fx_canvas or self.action_name not in ("like", "wink"):
            self.like_glow_job = None
            return
        size = self.like_fx_canvas.winfo_width() or (self.display_size + 40)
        _draw_like_glow(self.like_fx_canvas, size, self.like_glow_phase)
        self.like_glow_phase += 1
        self._place_like_fx()
        self.like_glow_job = self.root.after(90, self._animate_like_glow)

    def _hide_wink_fx(self) -> None:
        if not self.wink_fx_job and not self.wink_fx_win:
            return
        if self.wink_fx_job:
            try:
                self.root.after_cancel(self.wink_fx_job)
            except Exception:
                pass
            self.wink_fx_job = None
        if self.wink_fx_win and self.wink_fx_win.winfo_exists():
            self.wink_fx_win.destroy()
        self.wink_fx_win = None
        self.wink_fx_canvas = None
        self._wink_fx_size = 0
        self._notify_bg_fx_change()

    def _place_wink_fx(self) -> None:
        if not self.wink_fx_win or not self.wink_fx_win.winfo_exists():
            return
        pad = 20
        display_y = self.y + self.click_bounce_offset
        size = int(getattr(self, "_wink_fx_size", 0) or (self.display_size + pad * 2))
        self.wink_fx_win.geometry(f"{size}x{size}+{self.x - pad}+{display_y - pad}")
        self._lift_pet_above_bg_fx()

    def _paint_wink_fx_frame(self) -> None:
        """wink 背景：星光 + 光环 + 爱心波。用锁定尺寸，勿信 winfo_width()==1。"""
        canvas = self.wink_fx_canvas
        if not canvas or not canvas.winfo_exists():
            return
        size = int(getattr(self, "_wink_fx_size", 0) or 0)
        if size < 16:
            size = self.display_size + 40
            self._wink_fx_size = size
        canvas.delete("all")
        px = max(3, size // 28)
        sparkle = ("#ffff88", "#ffccff", "#ffffff", "#ff88aa", "#88ccff", "#ffddee")
        # 相位驱动的闪点，避免每帧全随机导致乱跳
        phase = int(self.wink_fx_phase)
        rng = random.Random(0x57494E4B ^ (phase // 2))
        for i in range(12):
            sx, sy = _scatter_xy_on_ring(size, rng=rng)
            _draw_pixel_star(canvas, sx, sy, px=max(2, px - (i % 3)), color=sparkle[(i + phase) % len(sparkle)])
        _draw_like_glow(canvas, size, phase)
        _draw_heart_wave(canvas, size, phase, clear=False)

    def _animate_wink_fx(self) -> None:
        if not self.wink_fx_canvas:
            self.wink_fx_job = None
            return
        # 动作已结束/被打断：只收特效，绝不在此二次结束动作（否则会卡站姿）
        if self.action_name != "wink" or self.state != "action":
            self.wink_fx_job = None
            self._hide_wink_fx()
            return
        if int(time.time() * 1000) - self.wink_fx_started_ms >= WINK_DURATION_MS:
            # 时长到：只停特效；动作结束由 _schedule_action_end 统一负责
            self.wink_fx_job = None
            self._hide_wink_fx()
            return
        self._paint_wink_fx_frame()
        self.wink_fx_phase += 1
        self._place_wink_fx()
        self.wink_fx_job = self.root.after(100, self._animate_wink_fx)

    def _show_wink_fx(self) -> None:
        self._hide_wink_fx()
        self._hide_bixin_fx()
        pad = 20
        size = self.display_size + pad * 2
        self.wink_fx_win = tk.Toplevel(self.root)
        self.wink_fx_win.overrideredirect(True)
        try:
            setattr(self.wink_fx_win, "_vpet_no_glass", True)
        except Exception:
            pass
        self.wink_fx_win.configure(bg="magenta")
        try:
            self.wink_fx_win.wm_attributes("-transparentcolor", "magenta")
        except Exception:
            pass
        self._apply_window_layer(self.wink_fx_win)
        self.wink_fx_canvas = tk.Canvas(
            self.wink_fx_win, width=size, height=size, bg="magenta", highlightthickness=0
        )
        self.wink_fx_canvas.pack()
        self._win32_set_click_through(self.wink_fx_win, True)
        self._wink_fx_size = size
        self.wink_fx_phase = 0
        self.wink_fx_started_ms = int(time.time() * 1000)
        # 首帧立刻绘制（勿等 after；且勿用 winfo_width()==1 的假尺寸）
        self._paint_wink_fx_frame()
        self._place_wink_fx()
        self.wink_fx_job = self.root.after(100, self._animate_wink_fx)
        self._notify_bg_fx_change()
        self._lift_pet_above_bg_fx()

    def _bixin_fx_pad(self) -> int:
        return max(96, self.display_size // 2 + 24)

    def _hide_bixin_fx(self) -> None:
        self._bixin_fx_gen = int(getattr(self, "_bixin_fx_gen", 0)) + 1
        if self.bixin_fx_job:
            try:
                self.root.after_cancel(self.bixin_fx_job)
            except Exception:
                pass
            self.bixin_fx_job = None
        if self.bixin_fx_win and self.bixin_fx_win.winfo_exists():
            try:
                self.bixin_fx_win.destroy()
            except Exception:
                pass
        self.bixin_fx_win = None
        self.bixin_fx_canvas = None
        self._bixin_particles = []
        self._notify_bg_fx_change()

    def _place_bixin_fx(self) -> None:
        if not self.bixin_fx_win or not self.bixin_fx_win.winfo_exists():
            return
        pad = self._bixin_fx_pad()
        display_y = self.y + self.click_bounce_offset
        self.bixin_fx_win.geometry(f"+{self.x - pad}+{display_y - pad}")
        # 爱心在立绘前方，朝使用者放大
        try:
            self.root.lift()
            self.bixin_fx_win.lift()
        except Exception:
            pass

    def _show_bixin_fx(self) -> None:
        self._hide_bixin_fx()
        self._hide_like_fx()
        self._hide_wink_fx()
        self._hide_shy_fx()
        pad = self._bixin_fx_pad()
        size = self.display_size + pad * 2
        self.bixin_fx_win = tk.Toplevel(self.root)
        self.bixin_fx_win.overrideredirect(True)
        self._apply_window_layer(self.bixin_fx_win)
        self.bixin_fx_win.configure(bg="magenta")
        self.bixin_fx_win.wm_attributes("-transparentcolor", "magenta")
        self.bixin_fx_canvas = tk.Canvas(
            self.bixin_fx_win, width=size, height=size, bg="magenta", highlightthickness=0
        )
        self.bixin_fx_canvas.pack()
        try:
            self._win32_set_click_through(self.bixin_fx_win, True)
        except Exception:
            pass
        self.bixin_fx_phase = 0
        self.bixin_fx_started_ms = int(time.time() * 1000)
        self._bixin_particles = []
        self._place_bixin_fx()
        self._animate_bixin_fx()

    def _animate_bixin_fx(self) -> None:
        self.bixin_fx_job = None
        gen = int(getattr(self, "_bixin_fx_gen", 0))
        canvas = self.bixin_fx_canvas
        if not canvas or not canvas.winfo_exists():
            return
        if self.action_name != "bixin" or self.state != "action":
            self._hide_bixin_fx()
            return
        if int(time.time() * 1000) - int(self.bixin_fx_started_ms or 0) >= BIXIN_DURATION_MS:
            self._hide_bixin_fx()
            return
        pad = self._bixin_fx_pad()
        size = self.display_size + pad * 2
        # 胸口偏右下出发，避开脸部；放大时往外侧飘
        chest_x = pad + int(self.display_size * 0.64)
        chest_y = pad + int(self.display_size * 0.55)
        phase = int(self.bixin_fx_phase)
        colors = ("#ff4d7a", "#ff6688", "#ff88aa", "#ff3366", "#ff99bb")
        glow_colors = ("#ff99bb", "#ffc0d0", "#ffe0ea")
        # 持续从胸口涌出
        if phase % 3 == 0:
            self._bixin_particles.append(
                {
                    "age": 0,
                    "life": random.randint(34, 50),
                    "ox": random.uniform(2, 16),
                    "oy": random.uniform(0, 12),
                    # 主要往右外侧飘，少往脸中间跑
                    "vx": random.uniform(0.25, 0.95),
                    "vy": random.uniform(-1.4, -0.2),
                    "px0": 2,
                    "px1": random.randint(14, max(18, self.display_size // 8)),
                    "color": random.choice(colors),
                    "glow": random.choice(glow_colors),
                }
            )
        canvas.delete("all")
        alive: list[dict] = []
        for p in list(self._bixin_particles):
            p["age"] = int(p.get("age", 0)) + 1
            life = max(1, int(p.get("life", 40)))
            t = min(1.0, p["age"] / life)
            if t >= 1.0:
                continue
            # 越接近使用者越大（先慢后快）
            grow = t * t
            px0 = int(p.get("px0", 2))
            px1 = int(p.get("px1", 18))
            draw_px = max(2, int(round(px0 + (px1 - px0) * grow)))
            x = (
                chest_x
                + float(p.get("ox", 0))
                + float(p.get("vx", 0)) * p["age"] * 1.15
                + grow * (18 + self.display_size * 0.06)
            )
            y = (
                chest_y
                + float(p.get("oy", 0))
                + float(p.get("vy", 0)) * p["age"] * 1.05
                - grow * (10 + self.display_size * 0.03)
            )
            cx, cy = int(x), int(y)
            glow_px = max(draw_px + 1, int(draw_px * 1.35))
            gw = glow_px * 3
            dw = draw_px * 3
            _draw_pixel_heart(
                canvas,
                cx - gw // 2,
                cy - gw // 2,
                px=glow_px,
                color=str(p.get("glow") or "#ffc0d0"),
            )
            _draw_pixel_heart(
                canvas,
                cx - dw // 2,
                cy - dw // 2,
                px=draw_px,
                color=str(p.get("color") or "#ff6688"),
            )
            # 靠近结束时加一圈更淡的大心，强化「扑向屏幕」感
            if grow > 0.55:
                ring = max(draw_px + 3, int(draw_px * 1.7))
                rw = ring * 3
                _draw_pixel_heart(
                    canvas,
                    cx - rw // 2,
                    cy - rw // 2,
                    px=ring,
                    color="#ffdde8",
                )
            alive.append(p)
        self._bixin_particles = alive[-18:]
        self.bixin_fx_phase = phase + 1
        self._place_bixin_fx()
        if gen == getattr(self, "_bixin_fx_gen", 0):
            self.bixin_fx_job = self.root.after(BIXIN_FX_MS, self._animate_bixin_fx)

