    def _interact_flair(self, action: str, *, banter: bool = True, show_fx: bool = True) -> None:
        if self.music_sprite_mode:
            return
        if show_fx and action == "kick":
            self._show_interact_fx(action)
        if not banter or action not in INTERACT_BANTER:
            return
        voice_cat = self._ACTION_VOICE_CATEGORY.get(action)
        # 互动→动作专用目录（kick/eat/sleep/work）：有资源则强制播，不被 50/50 打字框「看起来像没语音」
        if voice_cat and self._vpet_voice_category_ready(voice_cat):
            if self._addon_voice_vpet(voice_cat, chain=False, interrupt_busy=True):
                return
            self._show_interact_banter_dialog(action)
            return
        self._show_interact_banter_dialog(action)

    def _get_mini_pet_sprites(self, size: int) -> dict:
        if size not in self._mini_pet_sprite_cache:
            # 同步兜底（极少路径）；常规走 _ensure_mini_pet_sprites 异步构建
            self._build_mini_pet_sprites_sync(size)
        return self._mini_pet_sprite_cache[size]

    def _mini_pet_size_for(self, display_size: int) -> int:
        """按主宠目标尺寸换算 Allmate 尺寸（中档=120）。"""
        return max(72, min(220, int(round(int(display_size) * MINI_PET_SIZE / DEFAULT_SIZE))))

    def _mini_pet_display_size(self) -> int:
        """Allmate 随主宠三档缩放（中=120 基准）。"""
        return self._mini_pet_size_for(self.display_size)

    def _apply_mini_pets_size_now(self, new_size: int) -> None:
        """立刻把已有 Allmate 切到指定像素尺寸（与主宠同帧生效）。"""
        if not self.mini_pets:
            return
        if new_size not in self._mini_pet_sprite_cache:
            try:
                self._build_mini_pet_sprites_sync(new_size)
            except Exception:
                self._ensure_mini_pet_sprites(new_size)
                return
        sprites = self._get_mini_pet_sprites(new_size)
        for entry in list(self.mini_pets):
            win = entry.get("win")
            lbl = entry.get("label")
            if not win or not win.winfo_exists():
                continue
            entry["size"] = new_size
            entry["sprites"] = sprites
            move_dir = str(entry.get("move_dir") or "front")
            if move_dir == "stand":
                photo = sprites["stand"]
            else:
                frames = sprites.get(move_dir) or sprites["front"]
                photo = frames[0] if isinstance(frames, (tuple, list)) else frames
            entry["photo"] = photo
            try:
                if lbl and lbl.winfo_exists():
                    lbl.config(image=photo)
                    lbl.image = photo
            except Exception:
                pass
            # 只重定位，不重开 follow 链（由外层统一）
            try:
                side = entry.get("side", "left")
                gap = MINI_PET_SIDE_GAP
                if side == "left":
                    tx = self.x - new_size - gap
                else:
                    tx = self.x + self.display_size + gap
                ty = self.y + self.display_size - new_size
                tx, ty = self._clamp_mini_pet_xy(tx, ty, new_size)
                entry["x"], entry["y"] = float(tx), float(ty)
                win.geometry(f"+{int(tx)}+{int(ty)}")
            except Exception:
                pass
        self._sync_mini_pet_music_waves()
        self._notify_bg_fx_change()

    def _resync_mini_pets_size(self) -> None:
        """主宠改尺寸后，同步刷新已存在的 Allmate（优先即时，缺缓存再异步）。"""
        if not self.mini_pets:
            return
        new_size = self._mini_pet_display_size()
        if new_size in self._mini_pet_sprite_cache:
            self._apply_mini_pets_size_now(new_size)
            for entry in self.mini_pets:
                self._mini_pet_follow_tick(entry)
            return

        def apply() -> None:
            self._apply_mini_pets_size_now(new_size)
            for entry in self.mini_pets:
                self._mini_pet_follow_tick(entry)

        self._ensure_mini_pet_sprites(new_size, on_done=apply)

    def _build_mini_pet_sprites_sync(self, size: int) -> dict:
        ref = _reference_scale(size)

        def load(filename: str, *, flip: bool = False) -> ImageTk.PhotoImage:
            canvas = _get_processed_canvas(filename, size, ref, flip=flip)
            return ImageTk.PhotoImage(canvas)

        sprites = {
            "stand": load("petstand.jpg"),
            "front": (load("petfront1.jpg"), load("petfront2.jpg")),
            "back": (load("petback1.jpg"), load("petback2.jpg")),
            "left": (load("petleft1.jpg"), load("petleft2.jpg")),
            "right": (load("petleft1.jpg", flip=True), load("petleft2.jpg", flip=True)),
        }
        self._mini_pet_sprite_cache[size] = sprites
        return sprites

    def _ensure_mini_pet_sprites(self, size: int, *, on_done=None) -> None:
        if size in self._mini_pet_sprite_cache:
            if on_done:
                on_done()
            return
        building = getattr(self, "_mini_pet_building", None)
        if building is None:
            self._mini_pet_building = set()
            building = self._mini_pet_building
        if size in building:
            return
        building.add(size)

        def worker() -> None:
            pack: dict | None = None
            try:
                ref = _reference_scale(size)
                raw = {
                    "stand": _get_processed_canvas("petstand.jpg", size, ref),
                    "front1": _get_processed_canvas("petfront1.jpg", size, ref),
                    "front2": _get_processed_canvas("petfront2.jpg", size, ref),
                    "back1": _get_processed_canvas("petback1.jpg", size, ref),
                    "back2": _get_processed_canvas("petback2.jpg", size, ref),
                    "left1": _get_processed_canvas("petleft1.jpg", size, ref),
                    "left2": _get_processed_canvas("petleft2.jpg", size, ref),
                    "right1": _get_processed_canvas("petleft1.jpg", size, ref, flip=True),
                    "right2": _get_processed_canvas("petleft2.jpg", size, ref, flip=True),
                }
                pack = raw
            except Exception:
                pack = None

            def apply() -> None:
                self._mini_pet_building.discard(size)
                if pack is None:
                    try:
                        self._build_mini_pet_sprites_sync(size)
                    except Exception:
                        pass
                    if on_done:
                        on_done()
                    return
                keys = list(pack.keys())
                photos: dict[str, ImageTk.PhotoImage] = {}

                def step(idx: int = 0) -> None:
                    if self._closing:
                        return
                    end = min(idx + 3, len(keys))
                    for i in range(idx, end):
                        k = keys[i]
                        photos[k] = ImageTk.PhotoImage(pack[k])
                    if end < len(keys):
                        self.root.after(SPRITE_BATCH_MS, lambda: step(end))
                        return
                    self._mini_pet_sprite_cache[size] = {
                        "stand": photos["stand"],
                        "front": (photos["front1"], photos["front2"]),
                        "back": (photos["back1"], photos["back2"]),
                        "left": (photos["left1"], photos["left2"]),
                        "right": (photos["right1"], photos["right2"]),
                    }
                    if on_done:
                        on_done()

                step(0)

            try:
                self.root.after(0, apply)
            except Exception:
                building.discard(size)

        threading.Thread(target=worker, daemon=True).start()

    def _toggle_companion_bar(self) -> None:
        self._hide_main_menu()
        self.companion_bar_enabled = not self.companion_bar_enabled
        if self.companion_bar_enabled:
            self._try_voice_companion_startup()
            open_n = 0
            try:
                stats = self.achievements.setdefault("stats", {})
                open_n = int(stats.get("companion_open_count", 0) or 0) + 1
                stats["companion_open_count"] = open_n
                stats["companion_enabled"] = True
                _save_achievements(self.achievements)
                self._check_achievements(source="companion")
            except Exception:
                open_n = 1

            def after_ready() -> None:
                def try_hearts(attempt: int = 0) -> None:
                    if self._closing or not self.companion_bar_enabled:
                        return
                    if self._allmate_speech_anchor() is None:
                        if attempt < 12:
                            self.root.after(160, lambda: try_hearts(attempt + 1))
                        return
                    hearts = min(4 + max(0, open_n) // 2, 8)
                    # 出场只先送爱心；飞完后再播开心/点赞等正向表情
                    self._play_companion_heart_transfer(
                        heart_count=hearts,
                        on_done=self._play_companion_open_positive,
                    )

                self.root.after(200, lambda: try_hearts(0))

            if not self.mini_pets:
                def after_spawn() -> None:
                    self._spawn_mini_pet_impl(silent=True, skip_enter_anim=True)
                    after_ready()

                self._show_companion_loading(after_spawn)
            else:
                for entry in self.mini_pets:
                    self._mini_pet_follow_tick(entry)
                self._sync_mini_pet_music_waves()
                after_ready()
            self._show_toast("智能伴侣栏已开启", "#88ccff", duration_ms=1500)
            self._show_once_hint("companion_bar", duration_ms=3500)
        else:
            self._hide_companion_heart_transfer()
            self._destroy_all_mini_pets(animated=True)
            self._show_toast("智能伴侣栏已关闭", PIXEL_COLOR, duration_ms=1500)

    def _play_companion_open_positive(self) -> None:
        """智能伴侣出场：爱心送完后触发正向情绪表情。"""
        if self._closing or not self.companion_bar_enabled:
            return
        if self.dragging or getattr(self, "_holding_allmate", False):
            return
        if self.mode == "game" or self.state == "work":
            return
        pool = (
            self._play_happy,
            self._play_expression_like,
            lambda: self._play_action("hi"),
        )
        try:
            random.choice(pool)()
        except Exception:
            try:
                self._play_happy()
            except Exception:
                pass

    def _hide_companion_heart_transfer(self) -> None:
        self._companion_heart_protect = False
        self._companion_heart_gen = int(getattr(self, "_companion_heart_gen", 0)) + 1
        if self._companion_heart_job:
            try:
                self.root.after_cancel(self._companion_heart_job)
            except Exception:
                pass
            self._companion_heart_job = None
        if self._companion_heart_win and self._companion_heart_win.winfo_exists():
            try:
                self._companion_heart_win.destroy()
            except Exception:
                pass
        self._companion_heart_win = None
        self._companion_heart_canvas = None
        self._companion_heart_on_done = None

    def _play_companion_heart_transfer(self, *, heart_count: int = 4, on_done=None) -> None:
        """爱心从桌宠飞向智能伴侣（每次开启伴侣都会送）。"""
        if self._closing or not self.companion_bar_enabled:
            return
        anchor = self._allmate_speech_anchor()
        if anchor is None:
            return
        ax, ay, asz, abounce = anchor
        sx = int(self.x + self.display_size // 2)
        sy = int(self.y + self.click_bounce_offset + self.display_size // 3)
        ex = int(ax + asz // 2)
        ey = int(ay + abounce + asz // 3)

        self._hide_companion_heart_transfer()
        self._companion_heart_on_done = on_done
        self._companion_heart_protect = True
        gen = int(self._companion_heart_gen)
        # 大爱心需要更大飞行窗口与弧线空间
        base_px = max(6, min(12, self.display_size // 14))
        pad = max(72, base_px * 8)
        left = min(sx, ex) - pad
        top = min(sy, ey) - pad
        right = max(sx, ex) + pad
        bottom = max(sy, ey) + pad
        width = max(160, right - left)
        height = max(160, bottom - top)

        win = tk.Toplevel(self.root)
        self._companion_heart_win = win
        win.overrideredirect(True)
        try:
            setattr(win, "_vpet_no_glass", True)
        except Exception:
            pass
        win.configure(bg="magenta")
        try:
            win.wm_attributes("-transparentcolor", "magenta")
            win.attributes("-topmost", True)
        except Exception:
            pass
        self._apply_window_layer(win)
        canvas = tk.Canvas(win, width=width, height=height, bg="magenta", highlightthickness=0)
        canvas.pack()
        self._companion_heart_canvas = canvas
        win.geometry(f"{width}x{height}+{left}+{top}")

        colors = ("#ff4d7a", "#ff6688", "#ff88aa", "#ff3366", "#ff99bb", "#ffccdd")
        glow_colors = ("#ff99bb", "#ffc0d0", "#ffe0ea")
        n = max(3, min(10, int(heart_count)))
        particles: list[dict] = []
        for i in range(n):
            px = base_px + random.choice((0, 0, 1, 2, 3))
            particles.append(
                {
                    "t": -i * 0.07,
                    "ox": random.uniform(-18, 18),
                    "oy": random.uniform(-22, 12),
                    "arc": random.uniform(-48, 48),
                    "px": px,
                    "color": random.choice(colors),
                    "glow": random.choice(glow_colors),
                }
            )

        steps = 26
        state = {"i": 0}

        def tick() -> None:
            self._companion_heart_job = None
            if gen != getattr(self, "_companion_heart_gen", 0):
                return
            if not canvas.winfo_exists() or not self.companion_bar_enabled:
                self._hide_companion_heart_transfer()
                return
            canvas.delete("all")
            progress = state["i"] / max(1, steps - 1)
            for p in particles:
                t = min(1.0, max(0.0, progress + p["t"]))
                # 更明显的弧线：从桌宠到莲
                x = sx + (ex - sx) * t + p["ox"] + p["arc"] * (4 * t * (1 - t))
                y = sy + (ey - sy) * t + p["oy"] - abs(p["arc"]) * 0.55 * math.sin(math.pi * t)
                px = int(p["px"])
                # 轻微放大又缩小：中段最大
                scale = 0.85 + 0.45 * math.sin(math.pi * t)
                draw_px = max(5, int(round(px * scale)))
                cx = int(x - left)
                cy = int(y - top)
                # 外发光（浅色大心垫底）
                glow_px = max(draw_px + 2, int(draw_px * 1.35))
                gw = glow_px * 3
                dw = draw_px * 3
                _draw_pixel_heart(
                    canvas,
                    cx - gw // 2,
                    cy - gw // 2,
                    px=glow_px,
                    color=str(p["glow"]),
                )
                _draw_pixel_heart(
                    canvas,
                    cx - dw // 2,
                    cy - dw // 2,
                    px=draw_px,
                    color=str(p["color"]),
                )
                # 高光点，让爱心更立体醒目
                hl = max(2, draw_px // 3)
                canvas.create_rectangle(
                    cx - dw // 2 + hl,
                    cy - dw // 2 + hl // 2,
                    cx - dw // 2 + hl * 2,
                    cy - dw // 2 + hl + hl // 2,
                    fill="#fff5f8",
                    outline="",
                )
            state["i"] += 1
            if state["i"] >= steps:
                def finish(expected: int = gen) -> None:
                    if expected != getattr(self, "_companion_heart_gen", 0):
                        return
                    cb = getattr(self, "_companion_heart_on_done", None)
                    self._hide_companion_heart_transfer()
                    if cb:
                        try:
                            self.root.after(80, cb)
                        except Exception:
                            pass

                self.root.after(220, finish)
                return
            self._companion_heart_job = self.root.after(48, tick)

        tick()

    def _spawn_mini_pet(self, *, silent: bool = False) -> None:
        if not silent:
            self._hide_main_menu()
        if not self.companion_bar_enabled:
            self.companion_bar_enabled = True
        if len(self.mini_pets) >= MINI_PET_MAX:
            if not silent:
                self._show_toast(f"最多同时存在 {MINI_PET_MAX} 只莲哦~", "#ff8844")
            return
        self._show_companion_loading(lambda: self._spawn_mini_pet_impl(silent=silent, skip_enter_anim=True))

    def _spawn_mini_pet_impl(self, *, silent: bool = False, skip_enter_anim: bool = False) -> None:
        size = self._mini_pet_display_size()
        try:
            sprites = self._get_mini_pet_sprites(size)
            photo = sprites["stand"]
        except Exception:
            self._show_toast("智能伴侣立绘加载失败", "#ff8844", duration_ms=2200)
            return
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)
        try:
            setattr(win, "_vpet_no_glass", True)
        except Exception:
            pass
        win.configure(bg="magenta")
        try:
            win.wm_attributes("-transparentcolor", "magenta")
        except Exception:
            pass
        # 色键窗禁止设 -alpha（与 transparentcolor 冲突会整窗消失）
        self._apply_window_layer(win)
        lbl = tk.Label(win, image=photo, bg="magenta", bd=0)
        lbl.image = photo
        lbl.pack()
        idx = len(self.mini_pets)
        side = "left" if idx % 2 == 0 else "right"
        gap = MINI_PET_SIDE_GAP
        if side == "left":
            start_x = self.x - size - gap
        else:
            start_x = self.x + self.display_size + gap
        start_y = self.y + self.display_size - size
        start_x, start_y = self._clamp_mini_pet_xy(start_x, start_y, size)
        # 偏好边若完全出界则改另一侧
        try:
            sw = int(self.root.winfo_screenwidth())
        except Exception:
            sw = 1280
        if side == "left" and self.x - size - gap < 0 and self.x + self.display_size + gap + size <= sw:
            side = "right"
            start_x, start_y = self._clamp_mini_pet_xy(self.x + self.display_size + gap, start_y, size)
        elif side == "right" and self.x + self.display_size + gap + size > sw and self.x - size - gap >= 0:
            side = "left"
            start_x, start_y = self._clamp_mini_pet_xy(self.x - size - gap, start_y, size)
        win.geometry(f"+{int(start_x)}+{int(start_y)}")
        entry: dict = {
            "win": win,
            "label": lbl,
            "photo": photo,
            "sprites": sprites,
            "x": float(start_x),
            "y": float(start_y),
            "size": size,
            "index": idx,
            "side": side,
            "move_dir": "front",
            "move_dir_ms": 0,
            "follow_job": None,
            "bounce_offset": 0,
            "last_pet_x": self.x,
            "last_pet_y": self.y,
            "wave_win": None,
            "wave_canvas": None,
            "wave_phase": 0,
            "wave_job": None,
        }
        lbl.bind("<Button-1>", lambda _e, ent=entry: self._on_mini_pet_click(ent), add="+")
        self.mini_pets.append(entry)
        if skip_enter_anim:
            entry["entering"] = False
            self._mini_pet_follow_tick(entry)
            self._sync_mini_pet_music_waves()
            self._notify_bg_fx_change()
            if not silent:
                self._show_toast("噗~ 莲来陪你啦！", "#88ccff", duration_ms=1500)
            return
        # 无前置加载时：像素聚拢入场后再显示精灵
        lbl.pack_forget()
        anim_canvas = tk.Canvas(win, width=size, height=size, bg="magenta", highlightthickness=0)
        anim_canvas.pack()
        entry["entering"] = True
        img = _sprite_rgba_image("petstand.jpg", size)

        def finish_enter() -> None:
            if entry not in self.mini_pets:
                return
            try:
                if anim_canvas.winfo_exists():
                    anim_canvas.destroy()
            except Exception:
                pass
            if lbl.winfo_exists():
                lbl.pack()
            entry["entering"] = False
            self._mini_pet_follow_tick(entry)
            self._sync_mini_pet_music_waves()
            self._notify_bg_fx_change()
            if not silent:
                self._show_toast("噗~ 莲来陪你啦！", "#88ccff", duration_ms=1500)

        _run_pixel_block_dissolve_animation(
            self.root,
            anim_canvas,
            img,
            size,
            reverse=False,
            on_done=finish_enter,
            palette=COMPANION_ANIM_PALETTE,
            lively=True,
        )

    def _on_mini_pet_click(self, entry: dict) -> None:
        if entry not in self.mini_pets:
            return
        self._try_voice_companion_startup()
        now = int(time.time() * 1000)
        times = [t for t in getattr(self, "_companion_click_times", []) if now - t <= COMPANION_HOLD_CLICK_WINDOW_MS]
        times.append(now)
        self._companion_click_times = times
        if len(times) >= COMPANION_HOLD_CLICKS:
            self._companion_click_times = []
            self._begin_hold_allmate_approach(entry)

    def _clamp_mini_pet_xy(self, x: float, y: float, size: int) -> tuple[float, float]:
        """把智能伴侣（莲）位置钳在屏幕内，避免超出边界。"""
        try:
            sw = int(self.root.winfo_screenwidth())
            sh = int(self.root.winfo_screenheight())
        except Exception:
            sw, sh = 1280, 720
        size = max(1, int(size))
        mx = max(0.0, min(float(x), float(max(0, sw - size))))
        my = max(0.0, min(float(y), float(max(0, sh - size))))
        return mx, my

    def _mini_pet_side_target(self, entry: dict) -> tuple[float, float]:
        size = int(entry["size"])
        gap = MINI_PET_SIDE_GAP
        if self.mode == "game" or self.state == "game":
            gap = MINI_PET_GATHER_GAP
        elif self.state == "action" and self.action_name == "sad" and self.companion_bar_enabled:
            gap = MINI_PET_SAD_GAP
        elif self.state == "action" and self.action_name == "angry" and self.companion_bar_enabled:
            gap = MINI_PET_ANGRY_GAP
        left_x = float(self.x - size - gap)
        right_x = float(self.x + self.display_size + gap)
        target_y = float(self.y + self.display_size - size)
        preferred = entry.get("side", "left")
        try:
            sw = int(self.root.winfo_screenwidth())
        except Exception:
            sw = 1280
        left_ok = left_x >= 0 and left_x + size <= sw
        right_ok = right_x >= 0 and right_x + size <= sw
        if preferred == "left":
            target_x = left_x if left_ok or not right_ok else right_x
        else:
            target_x = right_x if right_ok or not left_ok else left_x
        return self._clamp_mini_pet_xy(target_x, target_y, size)

    def _mini_pet_main_moving(self, entry: dict) -> bool:
        last_x = entry.get("last_pet_x", self.x)
        last_y = entry.get("last_pet_y", self.y)
        entry["last_pet_x"] = self.x
        entry["last_pet_y"] = self.y
        if abs(self.x - last_x) > 0 or abs(self.y - last_y) > 0:
            return True
        return self.state == "walk" or self.follow_animating or self.work_animating

    def _mini_pet_move_dir(self, dx: float, dy: float, *, current: str = "front") -> str:
        """按位移取朝向；对当前轴向加迟滞，避免 45° 附近左右/前后狂切。"""
        ax, ay = abs(dx), abs(dy)
        if ax < 0.35 and ay < 0.35:
            return current or "front"
        horiz = (current or "front") in ("left", "right")
        ratio = MINI_PET_TURN_AXIS_RATIO
        if horiz:
            # 保持左右，除非纵向明显更强
            if ay > ax * ratio:
                return "front" if dy > 0 else "back"
            if ax < 0.35:
                return current or "front"
            return "left" if dx < 0 else "right"
        # 保持前后，除非横向明显更强
        if ax > ay * ratio:
            return "left" if dx < 0 else "right"
        if ay < 0.35:
            return current or "front"
        return "front" if dy > 0 else "back"

    def _mini_pet_apply_move_dir(self, entry: dict, proposed: str) -> str:
        """最短转向间隔：未满 hold 则维持原朝向。"""
        cur = str(entry.get("move_dir") or "front")
        if not proposed or proposed == cur:
            return cur
        now = int(time.time() * 1000)
        last = int(entry.get("move_dir_ms", 0) or 0)
        if last and (now - last) < MINI_PET_TURN_HOLD_MS:
            return cur
        entry["move_dir"] = proposed
        entry["move_dir_ms"] = now
        return proposed

    def _set_mini_pet_sprite(self, entry: dict, photo: ImageTk.PhotoImage) -> None:
        lbl = entry.get("label")
        if lbl and lbl.winfo_exists():
            lbl.config(image=photo)
            lbl.image = photo
        entry["photo"] = photo

    def _mini_pet_follow_tick(self, entry: dict) -> None:
        if entry not in self.mini_pets or not self.companion_bar_enabled:
            return
        if entry.get("entering"):
            entry["follow_job"] = self.root.after(
                MINI_PET_FOLLOW_MS, lambda e=entry: self._mini_pet_follow_tick(e)
            )
            return
        # 主宠三击去抱抱：伴侣原地等，避免边跟边跑永远追不上
        if getattr(self, "_hold_approach_active", False) or getattr(self, "_holding_allmate", False):
            entry["follow_job"] = self.root.after(
                MINI_PET_FOLLOW_MS, lambda e=entry: self._mini_pet_follow_tick(e)
            )
            return
        win = entry.get("win")
        if not win or not win.winfo_exists():
            return

        size = entry["size"]
        sprites = entry["sprites"]
        angry_active = self.state == "action" and self.action_name == "angry"
        gather_mode = self.mode == "game" or self.state == "game"
        last_x = entry.get("last_pet_x", self.x)
        last_y = entry.get("last_pet_y", self.y)
        pet_moved = abs(self.x - last_x) > 0 or abs(self.y - last_y) > 0
        if angry_active:
            entry["last_pet_x"] = self.x
            entry["last_pet_y"] = self.y
            main_moving = pet_moved
        else:
            main_moving = self._mini_pet_main_moving(entry)

        target_x, target_y = self._mini_pet_side_target(entry)
        mx, my = entry["x"], entry["y"]
        dx = target_x - mx
        dy = target_y - my
        dist = math.hypot(dx, dy)
        if angry_active:
            step = MINI_PET_FOLLOW_STEP * 2.5
            follow_ms = max(20, MINI_PET_FOLLOW_MS // 2)
        elif gather_mode:
            # 采集：更快跟上鼠标拖动的苍叶；间距已加大，不藏窗
            step = MINI_PET_GAME_FOLLOW_STEP
            follow_ms = MINI_PET_GAME_FOLLOW_MS
        elif self.music_sprite_mode:
            # 音乐模式降频跟随，减轻与光圈抢主线程
            step = MINI_PET_FOLLOW_STEP
            follow_ms = max(70, MINI_PET_FOLLOW_MS * 2)
        else:
            step = MINI_PET_FOLLOW_STEP
            follow_ms = MINI_PET_FOLLOW_MS
        mini_moving = dist > 1.5
        if dist > step:
            mx += dx / dist * step
            my += dy / dist * step
            mini_moving = True
        else:
            mx, my = target_x, target_y

        mx, my = self._clamp_mini_pet_xy(mx, my, size)

        use_walk = (not angry_active) and (mini_moving or main_moving)
        angry_walk = angry_active and self.angry_walk_phase

        if angry_walk:
            frame_idx = (int(time.time() * 1000) // WALK_FRAME_MS) % 2
            walk_frames = sprites.get("back", sprites["front"])
            self._set_mini_pet_sprite(entry, walk_frames[frame_idx])
        elif use_walk:
            cur_dir = str(entry.get("move_dir") or "front")
            if dist <= 0.5 and main_moving:
                # 贴身时跟桌宠朝向，但仍走防抖，避免桌宠微抖带动狂切
                proposed = self.direction or cur_dir
            else:
                proposed = self._mini_pet_move_dir(
                    dx if dist > 0.5 else 0.0,
                    dy if dist > 0.5 else 0.0,
                    current=cur_dir,
                )
            move_dir = self._mini_pet_apply_move_dir(entry, proposed)
            frame_idx = (int(time.time() * 1000) // WALK_FRAME_MS) % 2
            walk_frames = sprites.get(move_dir, sprites["front"])
            self._set_mini_pet_sprite(entry, walk_frames[frame_idx])
        else:
            self._set_mini_pet_sprite(entry, sprites["stand"])

        entry["x"], entry["y"] = mx, my
        bounce = int(entry.get("bounce_offset", 0))
        try:
            if entry.get("gather_hidden"):
                entry["gather_hidden"] = False
                win.deiconify()
            win.geometry(f"+{int(mx)}+{int(my) + bounce}")
        except Exception:
            pass
        self._place_mini_pet_music_wave(entry)
        self._place_mini_pet_bg_fx(entry)
        # Allmate 标题框跟智能伴侣走
        if (
            getattr(self, "_voice_subtitle_active", False)
            and str(getattr(self, "_voice_subtitle_source", "")).lower() == "allmate"
            and self.voice_subtitle_win
            and self.voice_subtitle_win.winfo_exists()
        ):
            self._place_voice_subtitle_popup(self.voice_subtitle_win)
        entry["follow_job"] = self.root.after(follow_ms, lambda e=entry: self._mini_pet_follow_tick(e))

    def _mini_pet_desired_bg_fx_kind(self) -> str | None:
        if not self.companion_bar_enabled:
            return None
        # 采集中伴侣可见，但不同步晕眩等氛围特效
        if self.mode == "game" or self.state == "game" or self.game_dizzy:
            return None
        if self._dizzy_fx_active():
            return "dizzy"
        if self.happy_fx_win and self.happy_fx_win.winfo_exists():
            return "happy"
        if self.shy_fx_win and self.shy_fx_win.winfo_exists():
            return "shy"
        if self.wink_fx_win and self.wink_fx_win.winfo_exists():
            return "wink"
        if self.interact_fx_win and self.interact_fx_win.winfo_exists():
            return f"interact:{self.interact_fx_action}"
        # 喂食 / 吃东西特效只给苍叶，智能伴侣不同步（不用吃）
        return None

    def _mini_pet_bg_pad(self, entry: dict, base_pad: int) -> int:
        return max(6, int(base_pad * entry["size"] / max(1, self.display_size)))

    def _stop_mini_pet_bg_fx(self, entry: dict) -> None:
        job = entry.get("bg_fx_job")
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        win = entry.get("bg_fx_win")
        if win and win.winfo_exists():
            win.destroy()
        entry["bg_fx_win"] = None
        entry["bg_fx_canvas"] = None
        entry["bg_fx_kind"] = None
        entry["bg_fx_job"] = None
        entry["bg_fx_phase"] = 0
        entry["bg_fx_elapsed"] = 0

    def _place_mini_pet_bg_fx(self, entry: dict) -> None:
        win = entry.get("bg_fx_win")
        if not win or not win.winfo_exists():
            return
        pad = entry.get("bg_fx_pad", 10)
        entry_x = int(entry["x"])
        entry_y = int(entry["y"]) + int(entry.get("bounce_offset", 0))
        win.geometry(f"+{entry_x - pad}+{entry_y - pad}")
        try:
            pet_win = entry.get("win")
            if pet_win is not None and pet_win.winfo_exists():
                pet_win.lift()
        except Exception:
            pass

    def _create_mini_pet_bg_fx_window(self, entry: dict, pad: int) -> tuple[tk.Canvas, int]:
        size = entry["size"]
        canvas_size = size + pad * 2
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)
        try:
            setattr(win, "_vpet_no_glass", True)
        except Exception:
            pass
        win.configure(bg="magenta")
        try:
            win.wm_attributes("-transparentcolor", "magenta")
        except Exception:
            pass
        self._apply_window_layer(win)
        canvas = tk.Canvas(
            win, width=canvas_size, height=canvas_size, bg="magenta", highlightthickness=0
        )
        canvas.pack()
        entry["bg_fx_win"] = win
        entry["bg_fx_canvas"] = canvas
        entry["bg_fx_pad"] = pad
        entry["bg_fx_size"] = canvas_size
        self._place_mini_pet_bg_fx(entry)
        return canvas, canvas_size

    def _animate_mini_pet_bg_fx(self, entry: dict) -> None:
        # 采集中绝不继续伴侣特效（含已在跑的晕眩动画）
        if self.mode == "game" or self.state == "game" or self.game_dizzy:
            self._stop_mini_pet_bg_fx(entry)
            return
        kind = entry.get("bg_fx_kind")
        canvas = entry.get("bg_fx_canvas")
        if not kind or not canvas:
            return
        pad = entry.get("bg_fx_pad", 10)
        size = int(entry.get("bg_fx_size") or 0)
        if size < 16:
            try:
                cw = int(canvas.winfo_width())
            except Exception:
                cw = 0
            size = cw if cw > 8 else (entry["size"] + pad * 2)
            entry["bg_fx_size"] = size
        pet_size = entry["size"]
        scale = pet_size / max(1, self.display_size)
        delay = 120
        if kind == "dizzy":
            _draw_dizzy_sticker(canvas, size, entry.get("bg_fx_phase", 0))
            entry["bg_fx_phase"] = entry.get("bg_fx_phase", 0) + 1
        elif kind == "like":
            # 点赞光波已移到音乐模式，伴侣不再同步 like glow
            self._stop_mini_pet_bg_fx(entry)
            return
        elif kind == "wink":
            if self.action_name != "wink":
                self._stop_mini_pet_bg_fx(entry)
                self._sync_all_mini_pet_bg_fx()
                return
            canvas.delete("all")
            phase = int(entry.get("bg_fx_phase", 0))
            px = max(2, size // 28)
            sparkle = ("#ffff88", "#ffccff", "#ffffff", "#ff88aa", "#88ccff")
            rng = random.Random(0x57494E4B ^ (phase // 2) ^ int(entry.get("index", 0)))
            for i in range(8):
                sx, sy = _scatter_xy_on_ring(size, rng=rng)
                _draw_pixel_star(canvas, sx, sy, px=max(2, px - 1), color=sparkle[(i + phase) % len(sparkle)])
            _draw_like_glow(canvas, size, phase)
            _draw_heart_wave(canvas, size, phase, clear=False)
            entry["bg_fx_phase"] = phase + 1
            delay = 100
        elif kind.startswith("interact:"):
            action = kind.split(":", 1)[1]
            _draw_interact_fx(canvas, action, size, entry.get("bg_fx_phase", 0))
            entry["bg_fx_phase"] = entry.get("bg_fx_phase", 0) + 1
            delay = INTERACT_FX_MS
        elif kind.startswith("food:"):
            food_id = kind.split(":", 1)[1]
            elapsed = entry.get("bg_fx_elapsed", 0)
            total_ms = FOOD_APPEAR_MS + FOOD_HOLD_MS + FOOD_VANISH_MS
            if elapsed >= total_ms or not (self.food_fx_win and self.food_fx_win.winfo_exists()):
                self._stop_mini_pet_bg_fx(entry)
                return
            canvas.delete("all")
            px = max(3, int(max(4, self.display_size // FOOD_FX_PIXEL_DIV) * scale))
            if elapsed < FOOD_APPEAR_MS:
                progress = elapsed / FOOD_APPEAR_MS
            elif elapsed < FOOD_APPEAR_MS + FOOD_HOLD_MS:
                progress = 1.0
            else:
                vanish = elapsed - FOOD_APPEAR_MS - FOOD_HOLD_MS
                progress = max(0.0, 1.0 - vanish / FOOD_VANISH_MS)
            food_scale = max(2, int(px * (0.6 + 0.4 * progress)))
            offset_y = int((1.0 - progress) * food_scale * 2)
            base_x = size - food_scale * 5
            base_y = size // 2 + food_scale - offset_y
            _draw_pixel_food(canvas, food_id, base_x, base_y, px=food_scale)
            entry["bg_fx_elapsed"] = elapsed + 50
            delay = 50
        else:
            return
        self._place_mini_pet_bg_fx(entry)
        entry["bg_fx_job"] = self.root.after(delay, lambda e=entry: self._animate_mini_pet_bg_fx(e))

    def _start_mini_pet_bg_fx(self, entry: dict, kind: str) -> None:
        if self.mode == "game" or self.state == "game" or self.game_dizzy:
            self._stop_mini_pet_bg_fx(entry)
            return
        self._stop_mini_pet_bg_fx(entry)
        entry["bg_fx_kind"] = kind
        entry["bg_fx_phase"] = 0
        entry["bg_fx_elapsed"] = 0
        pet_size = entry["size"]
        scale = pet_size / max(1, self.display_size)
        if kind == "happy":
            pad = self._mini_pet_bg_pad(entry, 24)
            canvas, canvas_size = self._create_mini_pet_bg_fx_window(entry, pad)
            px = max(2, int(3 * scale))
            colors = ("#ff88cc", "#ffcc44", "#88dd88", "#ff6688", "#cc88ff", "#88ccff")
            for _ in range(8):
                fx, fy = _scatter_xy_on_ring(canvas_size)
                self._draw_pixel_flower(canvas, fx, fy, random.choice(colors), px=px)
        elif kind == "shy":
            pad = self._mini_pet_bg_pad(entry, 20)
            canvas, canvas_size = self._create_mini_pet_bg_fx_window(entry, pad)
            px = max(2, int(max(2, self.display_size // 36) * scale))
            heart_colors = ("#ff6688", "#ff88aa", "#ff4466", "#ff99bb")
            for _ in range(6):
                hx, hy = _scatter_xy_on_ring(canvas_size)
                _draw_pixel_heart(canvas, hx, hy, px=px, color=random.choice(heart_colors))
        elif kind == "wink":
            pad = self._mini_pet_bg_pad(entry, 20)
            self._create_mini_pet_bg_fx_window(entry, pad)
            self._animate_mini_pet_bg_fx(entry)
        elif kind == "dizzy":
            pad = self._mini_pet_bg_pad(entry, 16)
            self._create_mini_pet_bg_fx_window(entry, pad)
            self._animate_mini_pet_bg_fx(entry)
        elif kind.startswith("interact:"):
            pad = self._mini_pet_bg_pad(entry, INTERACT_FX_PAD)
            self._create_mini_pet_bg_fx_window(entry, pad)
            self._animate_mini_pet_bg_fx(entry)
        elif kind.startswith("food:"):
            # 兼容旧态：若此前误绑了喂食特效，直接停掉
            self._stop_mini_pet_bg_fx(entry)

    def _sync_all_mini_pet_bg_fx(self, *, place_only: bool = False) -> None:
        if not self.companion_bar_enabled:
            for entry in self.mini_pets:
                self._stop_mini_pet_bg_fx(entry)
            return
        kind = self._mini_pet_desired_bg_fx_kind()
        for entry in self.mini_pets:
            cur = entry.get("bg_fx_kind")
            if place_only:
                if cur is not None:
                    self._place_mini_pet_bg_fx(entry)
                continue
            if kind is None:
                if cur is not None:
                    self._stop_mini_pet_bg_fx(entry)
            elif cur != kind:
                self._start_mini_pet_bg_fx(entry, kind)
            else:
                self._place_mini_pet_bg_fx(entry)

    def _notify_bg_fx_change(self) -> None:
        # interrupt 清场会连点多次 hide；合并成一次同步，避免切模式卡顿
        if int(getattr(self, "_bg_fx_notify_paused", 0) or 0) > 0:
            self._bg_fx_notify_pending = True
            return
        self._sync_all_mini_pet_bg_fx()

    def _pause_bg_fx_notify(self) -> None:
        self._bg_fx_notify_paused = int(getattr(self, "_bg_fx_notify_paused", 0) or 0) + 1

    def _resume_bg_fx_notify(self) -> None:
        depth = max(0, int(getattr(self, "_bg_fx_notify_paused", 0) or 0) - 1)
        self._bg_fx_notify_paused = depth
        if depth == 0 and getattr(self, "_bg_fx_notify_pending", False):
            self._bg_fx_notify_pending = False
            self._sync_all_mini_pet_bg_fx()

    def _stop_mini_pet_music_wave(self, entry: dict) -> None:
        job = entry.get("wave_job")
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
            entry["wave_job"] = None
        wave_win = entry.get("wave_win")
        if wave_win and wave_win.winfo_exists():
            wave_win.destroy()
        entry["wave_win"] = None
        entry["wave_canvas"] = None

    def _start_mini_pet_music_wave(self, entry: dict) -> None:
        if entry.get("wave_canvas"):
            return
        pad = MUSIC_WAVE_MINI_PAD
        size = entry["size"] + pad * 2
        wave_win = tk.Toplevel(self.root)
        wave_win.overrideredirect(True)
        try:
            setattr(wave_win, "_vpet_no_glass", True)
        except Exception:
            pass
        wave_win.configure(bg="magenta")
        try:
            wave_win.wm_attributes("-transparentcolor", "magenta")
        except Exception:
            pass
        self._apply_window_layer(wave_win)
        wave_canvas = tk.Canvas(wave_win, width=size, height=size, bg="magenta", highlightthickness=0)
        wave_canvas.pack()
        entry["wave_win"] = wave_win
        entry["wave_canvas"] = wave_canvas
        entry["wave_phase"] = 0
        entry["wave_pad"] = pad
        self._place_mini_pet_music_wave(entry)
        self._animate_mini_pet_music_wave(entry)

    def _place_mini_pet_music_wave(self, entry: dict) -> None:
        wave_win = entry.get("wave_win")
        if not wave_win or not wave_win.winfo_exists():
            return
        pad = entry.get("wave_pad", MUSIC_WAVE_MINI_PAD)
        bounce = int(entry.get("bounce_offset", 0))
        wx = int(entry["x"] - pad)
        wy = int(entry["y"] + bounce - pad)
        wave_win.geometry(f"+{wx}+{wy}")
        # 偶发抬宠，避免每帧 z-order
        lift_n = int(entry.get("_wave_lift_n", 0) or 0) + 1
        entry["_wave_lift_n"] = lift_n
        if lift_n < 12:
            return
        entry["_wave_lift_n"] = 0
        try:
            pet_win = entry.get("win")
            if pet_win is not None and pet_win.winfo_exists():
                pet_win.lift()
        except Exception:
            pass

    def _place_all_mini_pet_waves(self) -> None:
        for entry in self.mini_pets:
            self._place_mini_pet_music_wave(entry)

    def _animate_mini_pet_music_wave(self, entry: dict) -> None:
        canvas = entry.get("wave_canvas")
        if (
            not canvas
            or not self.companion_bar_enabled
            or not self._music_wave_should_show()
        ):
            self._stop_mini_pet_music_wave(entry)
            return
        pad = entry.get("wave_pad", MUSIC_WAVE_MINI_PAD)
        size = entry["size"] + pad * 2
        _draw_music_wave(
            canvas,
            size,
            size,
            entry.get("wave_phase", 0),
            colors=self._current_music_wave_colors(),
            lite=True,
        )
        entry["wave_phase"] = entry.get("wave_phase", 0) + 1
        # 位置未变时跳过；勿每帧 lift（多宠会卡）
        pad = entry.get("wave_pad", MUSIC_WAVE_MINI_PAD)
        bounce = int(entry.get("bounce_offset", 0))
        wx = int(entry["x"] - pad)
        wy = int(entry["y"] + bounce - pad)
        prev = entry.get("_wave_place_sig")
        if prev != (wx, wy):
            entry["_wave_place_sig"] = (wx, wy)
            self._place_mini_pet_music_wave(entry)
        entry["wave_job"] = self.root.after(
            MUSIC_WAVE_MINI_MS, lambda e=entry: self._animate_mini_pet_music_wave(e)
        )

    def _sync_mini_pet_music_waves(self) -> None:
        show = self.companion_bar_enabled and self._music_wave_should_show()
        for entry in self.mini_pets:
            if show:
                self._start_mini_pet_music_wave(entry)
            else:
                self._stop_mini_pet_music_wave(entry)

    def _destroy_mini_pet(self, entry: dict, *, animated: bool = False) -> None:
        job = entry.get("follow_job")
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
            entry["follow_job"] = None
        self._stop_mini_pet_music_wave(entry)
        self._stop_mini_pet_bg_fx(entry)

        def finalize() -> None:
            win = entry.get("win")
            if win and win.winfo_exists():
                win.destroy()
            if entry in self.mini_pets:
                self.mini_pets.remove(entry)
            for i, pet in enumerate(self.mini_pets):
                pet["index"] = i
                pet["side"] = "left" if i % 2 == 0 else "right"

        if not animated:
            finalize()
            return
        win = entry.get("win")
        if not win or not win.winfo_exists():
            finalize()
            return
        size = int(entry.get("size", MINI_PET_SIZE))
        x = int(entry.get("x", 0))
        y = int(entry.get("y", 0))
        lbl = entry.get("label")
        if lbl and lbl.winfo_exists():
            try:
                lbl.pack_forget()
            except Exception:
                pass
        self._run_exit_dissolve_at(
            x,
            y,
            size,
            on_done=finalize,
            image_filename="petstand.jpg",
            palette=COMPANION_ANIM_PALETTE,
        )
        if win.winfo_exists():
            try:
                win.withdraw()
            except Exception:
                pass

    def _destroy_all_mini_pets(self, *, animated: bool = False) -> None:
        pets = list(self.mini_pets)
        if not animated:
            for entry in pets:
                self._destroy_mini_pet(entry, animated=False)
            return
        for entry in pets:
            self._destroy_mini_pet(entry, animated=True)

    def _show_reserved(self, name: str) -> None:
        self._hide_main_menu()
        self._show_toast(f"{name}（预留）\n{RESERVED_TOAST}", "#888888", duration_ms=2500)

    def _play_adult_reserved(self) -> None:
        if self.dragging or self.state == "work":
            return
        self._interrupt_current_interaction()
        self._hide_main_menu()
        self.state = "action"
        self.action_name = "adult_msg"
        self._show_speech_dialog(ADULT_CONTENT_TEXT, auto_hide_ms=6500)
        self._schedule_action_end(duration_ms=_typing_duration_ms(ADULT_CONTENT_TEXT) + 1500, callback=self._after_adult_msg)

    def _after_adult_msg(self) -> None:
        if self.dragging or self.state != "action" or self.action_name != "adult_msg":
            return
        self._hide_speech_dialog()
        self._cancel_action_end()
        self._finish_expression()

    def _play_expression_pop(self, *, times: int = 1) -> None:
        """表情轻弹（click_bounce_offset）。默认 1 次；伤心/生气传 times=3。"""
        times = max(1, int(times))
        # 取消上一轮未完成的多段弹
        job = getattr(self, "expression_bounce_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
            self.expression_bounce_job = None
        self.click_bounce_offset = 0
        self.click_bouncing = True
        self._expression_bounce_left = times
        self._expression_bounce_tok = self.interaction_token
        self._expression_bounce_up()

    def _expression_bounce_up(self) -> None:
        if int(getattr(self, "_expression_bounce_tok", 0) or 0) != self.interaction_token:
            return
        if int(getattr(self, "_expression_bounce_left", 0) or 0) <= 0:
            self.click_bouncing = False
            self.click_bounce_offset = 0
            return
        self.click_bouncing = True
        self.click_bounce_offset = -EXPRESSION_BOUNCE_PX
        self._place_window()
        self._place_sleep_zzz()
        self._place_ai_chat()
        tok = self._expression_bounce_tok
        self.expression_bounce_job = self.root.after(
            EXPRESSION_BOUNCE_MS, lambda t=tok: self._expression_bounce_down_guarded(t)
        )

    def _expression_bounce_down_guarded(self, tok: int) -> None:
        if tok != self.interaction_token:
            return
        self.expression_bounce_job = None
        self._expression_bounce_down()

    def _expression_bounce_down(self) -> None:
        if int(getattr(self, "_expression_bounce_tok", 0) or 0) != self.interaction_token:
            return
        self.click_bounce_offset = 0
        self._place_window()
        self._place_sleep_zzz()
        self._place_ai_chat()
        left = int(getattr(self, "_expression_bounce_left", 0) or 0) - 1
        self._expression_bounce_left = left
        if left <= 0:
            self.click_bouncing = False
            return
        tok = self._expression_bounce_tok
        self.expression_bounce_job = self.root.after(
            EXPRESSION_BOUNCE_GAP_MS, lambda t=tok: self._expression_bounce_up_guarded(t)
        )

    def _expression_bounce_up_guarded(self, tok: int) -> None:
        if tok != self.interaction_token:
            return
        self.expression_bounce_job = None
        self._expression_bounce_up()

    def _expression_pop_down(self) -> None:
        # 兼容旧调用：落到一次弹的收尾
        self._expression_bounce_left = 1
        self._expression_bounce_down()

    def _play_kick(self) -> None:
        if self.dragging or self.state == "work":
            return
        self._interrupt_current_interaction()
        self._hide_main_menu()
        self.state = "action"
        self.action_name = "kick"
        self._show_interact_fx("kick")
        # 延后一帧再播：interrupt 刚 stop 后作废旧异步回调，同帧立刻播易被抢/冷却踩到
        tok = self.interaction_token

        def play_kick_voice(expected: int = tok) -> None:
            if expected != self.interaction_token or self.action_name != "kick":
                return
            if self._trigger_kick_banter() != "voice":
                self._try_voice_collision()

        self.root.after(60, play_kick_voice)
        # 仅用 y 弹跳（勿叠 expression_pop，否则易停在半空）
        self._set_image(self.sprites.kick)
        self.kick_base_y = self.y
        self.y = self.kick_base_y - KICK_BOUNCE_PX
        self._place_window(light=True)
        self._place_interact_fx()
        self.root.after(KICK_BOUNCE_MS, lambda t=tok: self._kick_bounce_down_guarded(t))
        self._schedule_action_end(action="kick", callback=self._after_simple_expression)

    def _kick_bounce_down_guarded(self, tok: int) -> None:
        if tok != self.interaction_token:
            return
        self._kick_bounce_down()

    def _kick_bounce_down(self) -> None:
        if self.action_name != "kick":
            return
        base = getattr(self, "kick_base_y", None)
        if base is None:
            return
        self.y = int(base)
        self._place_window(light=True)
        self._place_interact_fx()

    def _restore_kick_y(self) -> None:
        """侧踢结束/打断时收回上弹，避免停在半空。"""
        base = getattr(self, "kick_base_y", None)
        if base is None:
            return
        if abs(self.y - int(base)) <= KICK_BOUNCE_PX + 2:
            self.y = int(base)
    def _play_expression_shy(self) -> None:
        if self.dragging or self.state == "work" or self._app_scene_blocks_actions():
            return
        # 睡眠中可被点红：先打断睡眠链路，结束后若仍是睡眠模式会回到 rest
        was_quiet = self.mode == "quiet"
        self._interrupt_current_interaction()
        if was_quiet:
            self.mode = "quiet"
        self.state = "action"
        self.action_name = "shy"
        self.shy_frame_idx = 0
        self.shy_last_click_ms = 0
        self._interact_flair("shy", banter=False)
        self._set_image(self.sprites.shy[0])
        self._play_shy_bounce()
        self._show_shy_fx()
        self._schedule_action_end(action="shy", callback=self._after_simple_expression)

    def _handle_shy_click(self) -> None:
        if self.state != "action" or self.action_name != "shy":
            return
        frames = getattr(self.sprites, "shy", ()) or ()
        if not frames:
            return
        now_ms = int(time.time() * 1000)
        max_idx = len(frames) - 1
        # 连击：shy1 → shy2 → shy3（封顶）；间隔过大回到 shy1
        if now_ms - self.shy_last_click_ms <= SHY_DOUBLE_CLICK_MS:
            self.shy_frame_idx = min(max_idx, int(self.shy_frame_idx) + 1)
        else:
            self.shy_frame_idx = 0
        self.shy_frame_idx = max(0, min(max_idx, int(self.shy_frame_idx)))
        self._set_image(frames[self.shy_frame_idx])
        self.shy_last_click_ms = now_ms
        self._play_shy_bounce()
        # 切到更深害羞帧时再弹一次小心心
        if self.shy_frame_idx >= 1:
            self._show_shy_fx()
        self._schedule_action_end(action="shy", callback=self._after_simple_expression)

    def _play_shy_bounce(self) -> None:
        """脸红点击时弹跳一下。"""
        # 若仍在上一段弹跳中，从落地高度再起跳，避免叠高
        base = getattr(self, "shy_base_y", None)
        if base is not None and abs(self.y - base) <= SHY_BOUNCE_PX + 1:
            self.y = base
        self.shy_base_y = self.y
        self.y = self.shy_base_y - SHY_BOUNCE_PX
        self._place_window(light=True)
        self._place_shy_fx()
        self.root.after(SHY_BOUNCE_MS, self._shy_bounce_down)

    def _shy_bounce_down(self) -> None:
        if self.action_name != "shy":
            return
        base = getattr(self, "shy_base_y", None)
        if base is None:
            return
        self.y = base
        self._place_window(light=True)
        self._place_shy_fx()
    def _play_expression_like(self) -> None:
        self._play_like_or_wink("like", self.sprites.like)

    def _play_expression_bixin(self) -> None:
        """站姿比心：胸口涌出爱心并不断放大，传向屏幕前的使用者。"""
        if self.dragging or self.state == "work" or self._app_scene_blocks_actions():
            return
        self._interrupt_current_interaction()
        self.state = "action"
        self.action_name = "bixin"
        self.bixin_fx_started_ms = int(time.time() * 1000)
        self._interact_flair("bixin", banter=True)
        self._play_expression_pop()
        self._set_image(self.sprites.stand)
        self._show_bixin_fx()
        self._schedule_action_end(
            action="bixin",
            duration_ms=BIXIN_DURATION_MS,
            callback=self._after_bixin_expression,
        )

    def _after_bixin_expression(self) -> None:
        self._after_simple_expression()
        self.root.after(720, lambda: self._maybe_meta_banter("bixin_end"))

    def _play_expression_wink(self, *, restore_free: bool = False) -> None:
        del restore_free
        self._play_like_or_wink("wink", self.sprites.wink)

    def _play_like_or_wink(self, name: str, sprite: ImageTk.PhotoImage) -> None:
        if self.dragging or self.state == "work" or self._app_scene_blocks_actions():
            return
        self._interrupt_current_interaction()
        self.state = "action"
        self.action_name = name
        self._wink_restore_free = False
        self._wink_started_ms = int(time.time() * 1000)
        # D04：wink / like 无台词打断；时长固定约 3s
        self._interact_flair(name, banter=False)
        self._set_image(sprite)
        # wink：整窗上弹一下；点赞仍用轻量表情弹
        if name == "wink":
            self._play_wink_bounce()
            self._show_wink_fx()
        else:
            self._play_expression_pop()
            self._show_like_fx()
        self._schedule_action_end(
            action=name,
            duration_ms=WINK_DURATION_MS,
            callback=self._after_wink_or_like,
        )

    def _play_wink_bounce(self) -> None:
        """wink 弹跳一下（改 y，与侧踢同路）。"""
        self.wink_base_y = self.y
        self.y = self.wink_base_y - WINK_BOUNCE_PX
        self._place_window(light=True)
        self._place_wink_fx()
        self.root.after(WINK_BOUNCE_MS, self._wink_bounce_down)

    def _wink_bounce_down(self) -> None:
        if self.action_name != "wink":
            return
        base = getattr(self, "wink_base_y", None)
        if base is None:
            return
        self.y = base
        self._place_window(light=True)
        self._place_wink_fx()

    def _after_wink_or_like(self) -> None:
        """wink/like 专用结束：强制退出 action，恢复自由走动。"""
        if self.dragging:
            self._defer_until_not_dragging(self._after_wink_or_like)
            return
        if self.state == "action" and self.action_name not in ("wink", "like", ""):
            return
        self._force_end_wink_like()

    def _force_end_wink_like(self) -> None:
        # 中途上弹时收回，避免结束留在半空
        if self.action_name == "wink":
            base = getattr(self, "wink_base_y", None)
            if base is not None and abs(self.y - base) <= WINK_BOUNCE_PX + 1:
                self.y = base
        self._clear_all_action_fx()
        self._cancel_action_end()
        self._cancel_action_defer()
        if self.state == "action" and self.action_name in ("wink", "like"):
            self._add_interact_mood()
        self.action_name = ""
        self._wink_started_ms = 0
        if self.mode == "quiet":
            self.state = "rest"
            self._set_image(self.sprites.sleep[1])
            self._show_sleep_zzz()
            self._schedule_rest_bobble()
            return
        self.state = "stand"
        self._set_image(self._current_stand_sprite())
        if not self._check_mood_happy():
            self._resume_idle(quick=True)

    def _after_wink_expression(self) -> None:
        # 兼容旧调度/看门狗
        self._after_wink_or_like()

    def _play_expression_sprite(self, name: str, sprite: ImageTk.PhotoImage, *, banter: bool = True) -> None:
        if self.dragging or self.state == "work" or self._app_scene_blocks_actions():
            return
        self._interrupt_current_interaction()
        self.state = "action"
        self.action_name = name
        self._interact_flair(name, banter=banter)
        self._play_expression_pop()
        self._set_image(sprite)
        self._schedule_action_end(action=name, callback=self._after_simple_expression)

    def _play_yesno_judge(self) -> None:
        if self.dragging or self.state == "work" or self._app_scene_blocks_actions():
            return
        self._interrupt_current_interaction()
        self._hide_main_menu()
        self._cancel_yesno_overlay()
        self.yesno_is_yes = random.choice([True, False])
        pool = YESNO_YES_LINES if self.yesno_is_yes else YESNO_NO_LINES
        self.yesno_oracle_line = random.choice(pool)
        self.state = "action"
        self.action_name = "yesno"
        self._set_image(self.sprites.stand)
        # 赛博答案之书面板（不再用普通气泡作主界面）
        self._open_yesno_overlay(mode="wait")
        self.yesno_reveal_job = self.root.after(YESNO_WAIT_MS, self._yesno_reveal)

    def _yesno_reveal(self) -> None:
        self.yesno_reveal_job = None
        if self.action_name != "yesno":
            self._cancel_yesno_overlay()
            return
        self._hide_speech_dialog()
        is_yes = bool(getattr(self, "yesno_is_yes", True))
        line = str(getattr(self, "yesno_oracle_line", "") or "")
        if not line:
            line = random.choice(YESNO_YES_LINES if is_yes else YESNO_NO_LINES)
            self.yesno_oracle_line = line
        self._interact_flair("yesno", banter=False, show_fx=False)
        self._play_expression_pop()
        self._set_image(self.sprites.yes if is_yes else self.sprites.no)
        # 切到揭示态：保留面板动画，文案换成答案之书句
        if self.yesno_overlay_win and self.yesno_overlay_win.winfo_exists():
            self.yesno_overlay_mode = "yes" if is_yes else "no"
            self.yesno_overlay_phase = 0
            self._paint_yesno_overlay()
            if not getattr(self, "yesno_anim_job", None):
                self.yesno_anim_job = self.root.after(YESNO_ANIM_MS, self._tick_yesno_overlay)
        else:
            self._open_yesno_overlay(mode="yes" if is_yes else "no")
        self._schedule_action_end(action="yesno", callback=self._after_simple_expression)

    def _after_simple_expression(self) -> None:
        if self.state != "action":
            return
        if self.dragging:
            self._defer_until_not_dragging(self._after_simple_expression)
            return
        if self.action_name in ("wink", "like"):
            self._force_end_wink_like()
            return
        if self.action_name == "shy":
            base = getattr(self, "shy_base_y", None)
            if base is not None and abs(self.y - base) <= SHY_BOUNCE_PX + 1:
                self.y = base
                self._place_window(light=True)
        elif self.action_name == "kick":
            self._restore_kick_y()
            self._place_window(light=True)
        self._clear_all_action_fx()
        self._cancel_action_end()
        self._cancel_action_defer()
        self._add_interact_mood()
        self._finish_expression()

    def _play_expression_angry(self) -> None:
        if self.dragging or self.state == "work":
            return
        self._interrupt_current_interaction(reset_y=True)
        self.state = "action"
        self.action_name = "angry"
        self.angry_base_y = self.y
        self.angry_lift_offset = 0
        self.angry_walk_phase = False
        self._interact_flair("angry", banter=True)
        self._play_expression_pop(times=3)
        self._angry_anim_step(0)

    def _angry_anim_step(self, step: int) -> None:
        if self.dragging or self.state != "action" or self.action_name != "angry":
            return
        sequence = [
            self.sprites.stand_angry,
            self.sprites.front[0],
            self.sprites.stand_angry,
            self.sprites.back[0],
            self.sprites.back[1],
            self.sprites.back[0],
            self.sprites.back[1],
            self.sprites.back[0],
            self.sprites.back[1],
            self.sprites.stand_angry,
        ]
        if step >= len(sequence):
            self.angry_walk_phase = False
            self._place_window()
            self._schedule_action_end(action="angry", callback=self._after_simple_expression)
            return
        self.angry_walk_phase = 3 <= step <= 8
        if 3 <= step <= 8:
            self.angry_lift_offset = min(ANGRY_WALK_MAX_LIFT, self.angry_lift_offset + ANGRY_WALK_UP_PER_STEP)
            self.y = self.angry_base_y - self.angry_lift_offset
        elif step < 3:
            self.y = self.angry_base_y
        self._set_image(sequence[step])
        self._place_window()
        self.angry_anim_job = self.root.after(ANGRY_FRAME_MS, lambda: self._angry_anim_step(step + 1))

    def _cancel_expose_qte(self) -> None:
        # 不在这里取消倒计时：开局会先 cancel 再 start countdown，否则会误伤刚开的 3-2-1
        self.expose_qte_active = False
        self.expose_session_active = False
        self.expose_enter_armed = False
        self.expose_enter_was_down = False
        self.expose_phase = "storm"
        if self.expose_anim_job:
            self.root.after_cancel(self.expose_anim_job)
            self.expose_anim_job = None
        if self.expose_glitch_job:
            self.root.after_cancel(self.expose_glitch_job)
            self.expose_glitch_job = None
        if self.expose_qte_win and self.expose_qte_win.winfo_exists():
            self.expose_qte_win.destroy()
        self._destroy_expose_fault_stack()
        self.expose_qte_win = None
        self.expose_qte_canvas = None
        # 不用 unbind_all，避免拆掉其它 Return 绑定；靠 expose_enter_armed 开关

    def _destroy_expose_fault_stack(self) -> None:
        for item in list(getattr(self, "expose_glitch_wins", []) or []):
            win = item.get("win") if isinstance(item, dict) else None
            if win is not None:
                try:
                    if win.winfo_exists():
                        win.destroy()
                except Exception:
                    pass
        self.expose_glitch_wins = []
        self.expose_glitch_win = None
        self.expose_glitch_canvas = None
        self._destroy_expose_glitch_bg()

    def _destroy_expose_glitch_bg(self) -> None:
        win = getattr(self, "expose_bg_win", None)
        if win is not None:
            try:
                if win.winfo_exists():
                    win.destroy()
            except Exception:
                pass
        self.expose_bg_win = None
        self.expose_bg_canvas = None

    def _expose_fault_intensity(self) -> float:
        """故障轻重：窗越多/失手越多越重，命中越多越轻。"""
        n = float(self._expose_fault_count())
        miss = float(getattr(self, "expose_miss_count", 0) or 0)
        hits = float(getattr(self, "expose_hit_streak", 0) or 0)
        dens = n / float(max(1, EXPOSE_FAULT_MAX))
        raw = dens * 0.62 + min(1.0, miss * 0.16) - min(0.5, hits * 0.07)
        return max(0.08, min(1.0, raw))

    def _sync_expose_glitch_intensity(self) -> None:
        self.expose_glitch_intensity = self._expose_fault_intensity()
        self._ensure_expose_glitch_bg()

    def _ensure_expose_glitch_bg(self) -> None:
        """全屏故障氛围底：轻重随 intensity 变化。"""
        if not getattr(self, "expose_session_active", False):
            self._destroy_expose_glitch_bg()
            return
        inten = float(getattr(self, "expose_glitch_intensity", 0.35) or 0.35)
        theme = str(getattr(self, "expose_fault_theme", "blue") or "blue")
        try:
            sw = int(self.root.winfo_screenwidth())
            sh = int(self.root.winfo_screenheight())
        except Exception:
            return
        win = getattr(self, "expose_bg_win", None)
        canvas = getattr(self, "expose_bg_canvas", None)
        if win is None or not win.winfo_exists():
            win = tk.Toplevel(self.root)
            self.expose_bg_win = win
            win.overrideredirect(True)
            self._apply_window_layer(win)
            try:
                win.attributes("-topmost", True)
            except Exception:
                pass
            key = "magenta"
            win.configure(bg=key)
            try:
                win.wm_attributes("-transparentcolor", key)
            except Exception:
                pass
            canvas = tk.Canvas(win, width=sw, height=sh, bg=key, highlightthickness=0)
            canvas.pack()
            self.expose_bg_canvas = canvas
            win.geometry(f"{sw}x{sh}+0+0")
        if canvas is None or not canvas.winfo_exists():
            return
        canvas.delete("all")
        key = "magenta"
        canvas.create_rectangle(0, 0, sw, sh, fill=key, outline="")
        col = "#2266aa" if theme.lower().startswith("b") else "#aa2244"
        # 扫描线稀疏一些，减轻全屏重绘压力
        step = max(48, int(120 - inten * 40))
        phase = int(getattr(self, "expose_glitch_phase", 0) or 0)
        for y in range(0, sh, step):
            if (y + phase * 5) % (step * 2) < max(2, int(2 + inten * 4)):
                canvas.create_line(0, y, sw, y, fill=col)
        block = int(28 + inten * 56)
        for x0, y0 in ((0, 0), (sw - block, 0), (0, sh - block), (sw - block, sh - block)):
            canvas.create_rectangle(x0, y0, x0 + block, y0 + max(8, block // 3), fill=col, outline="")
        if inten > 0.55:
            tip = "SIGNAL LOST" if inten > 0.75 else "NOISE"
            canvas.create_text(sw // 2, 36, text=tip, fill=col, font=("Courier New", 14, "bold"))
        try:
            for item in list(getattr(self, "expose_glitch_wins", []) or []):
                w = item.get("win") if isinstance(item, dict) else None
                if w is not None and w.winfo_exists():
                    w.lift()
            if self.expose_qte_win and self.expose_qte_win.winfo_exists():
                self.expose_qte_win.lift()
        except Exception:
            pass

    def _expose_medium_params(self) -> tuple[float, float]:
        mid = DIFFICULTY_PRESETS["中"]
        return float(mid["expose_blue_span"]), float(mid["expose_pointer_speed"])

    def _expose_fault_count(self) -> int:
        alive = []
        for item in list(getattr(self, "expose_glitch_wins", []) or []):
            win = item.get("win") if isinstance(item, dict) else None
            try:
                if win is not None and win.winfo_exists():
                    alive.append(item)
            except Exception:
                pass
        self.expose_glitch_wins = alive
        if alive:
            self.expose_glitch_win = alive[-1].get("win")
            self.expose_glitch_canvas = alive[-1].get("canvas")
        else:
            self.expose_glitch_win = None
            self.expose_glitch_canvas = None
        return len(alive)

    def _make_expose_fault_window(self, *, theme: str, layer: int) -> dict:
        """创建一枚故障小窗（尺寸同旧版告警框）；多枚散落叠出近似霸屏。"""
        sw = int(self.root.winfo_screenwidth())
        sh = int(self.root.winfo_screenheight())
        gw, gh = EXPOSE_GLITCH_ALERT_W, EXPOSE_GLITCH_ALERT_H
        margin = 10
        max_x = max(margin, sw - gw - margin)
        max_y = max(margin, sh - gh - margin)
        # 按格子散开，再加抖动，避免全挤在一角（多窗用更密网格）
        cols, rows = 7, 5
        cell_w = max(gw // 2, sw // cols)
        cell_h = max(gh // 2, sh // rows)
        col = int(layer) % cols
        row = (int(layer) // cols) % rows
        x = col * cell_w + random.randint(0, max(0, cell_w - gw))
        y = row * cell_h + random.randint(0, max(0, cell_h - gh))
        x = max(margin, min(max_x, x + random.randint(-28, 28)))
        y = max(margin, min(max_y, y + random.randint(-22, 22)))
        bg = "#061428" if str(theme).lower().startswith("b") else "#1a0610"
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)
        self._apply_window_layer(win)
        win.configure(bg=bg)
        try:
            win.attributes("-topmost", True)
        except Exception:
            pass
        canvas = tk.Canvas(win, width=gw, height=gh, bg=bg, highlightthickness=0)
        canvas.pack()
        win.geometry(f"{gw}x{gh}+{x}+{y}")
        for seq in ("<Return>", "<KP_Enter>", "<KeyPress-Return>", "<KeyPress-KP_Enter>"):
            win.bind(seq, self._expose_qte_enter)
        return {"win": win, "canvas": canvas, "theme": theme, "w": gw, "h": gh}

    def _apply_expose_fault_theme(self, theme: str) -> None:
        """切换故障窗配色（蓝↔红），已有窗立即重绘。"""
        theme = "blue" if str(theme).lower().startswith("b") else "red"
        self.expose_fault_theme = theme
        bg = "#061428" if theme == "blue" else "#1a0610"
        for item in list(getattr(self, "expose_glitch_wins", []) or []):
            item["theme"] = theme
            item.pop("_static_drawn", None)
            win = item.get("win")
            canvas = item.get("canvas")
            try:
                if win is not None and win.winfo_exists():
                    win.configure(bg=bg)
                if canvas is not None and win is not None and win.winfo_exists():
                    canvas.configure(bg=bg)
                    _draw_glitch_fault(
                        canvas,
                        int(item.get("w") or EXPOSE_GLITCH_ALERT_W),
                        int(item.get("h") or EXPOSE_GLITCH_ALERT_H),
                        "",
                        int(getattr(self, "expose_glitch_phase", 0) or 0),
                        theme=theme,
                        lite=True,
                        intensity=float(getattr(self, "expose_glitch_intensity", 0.45) or 0.45),
                    )
                    item["_static_drawn"] = True
            except Exception:
                pass
        self._sync_expose_glitch_intensity()

    def _sync_expose_fault_stack(self, target: int) -> None:
        """把故障窗数量调整到 target（增加新建、减少销毁最上层）。"""
        target = max(0, int(target))
        cur = self._expose_fault_count()
        theme = getattr(self, "expose_fault_theme", "blue") or "blue"
        while cur < target:
            item = self._make_expose_fault_window(theme=theme, layer=cur)
            self.expose_glitch_wins.append(item)
            cur += 1
        while cur > target:
            item = self.expose_glitch_wins.pop()
            win = item.get("win")
            try:
                if win is not None and win.winfo_exists():
                    win.destroy()
            except Exception:
                pass
            cur -= 1
        # 不批量清 _static_drawn，避免层数变化时整批重绘
        self._expose_fault_count()
        self._sync_expose_glitch_intensity()
        # 成功减轻：刷新底层静态窗的 intensity；失败加重时清 _static_drawn 让顶层更重
        inten = float(getattr(self, "expose_glitch_intensity", 0.45) or 0.45)
        if inten >= 0.85:
            for item in list(getattr(self, "expose_glitch_wins", []) or [])[:-1]:
                item.pop("_static_drawn", None)
        if self.expose_session_active and self.expose_glitch_job is None and self._expose_fault_count() > 0:
            self._animate_glitch_fault()

    def _animate_glitch_fault(self) -> None:
        if not self.expose_session_active:
            self.expose_glitch_job = None
            return
        # 失败展示：保持静态窗，不再重绘（多窗 create 会卡主线程）
        if getattr(self, "_expose_fail_holding", False):
            self.expose_glitch_job = None
            return
        items = list(getattr(self, "expose_glitch_wins", []) or [])
        if not items:
            self.expose_glitch_job = None
            return
        phase = int(getattr(self, "expose_glitch_phase", 0) or 0)
        inten = float(getattr(self, "expose_glitch_intensity", 0.45) or 0.45)
        # 只动画最上层；其余首帧静态后不再动（高强度时偶尔重绘底窗）
        top = items[-1]
        for item in items:
            canvas = item.get("canvas")
            win = item.get("win")
            try:
                if canvas is None or win is None or not win.winfo_exists():
                    continue
                w = int(item.get("w") or EXPOSE_GLITCH_ALERT_W)
                h = int(item.get("h") or EXPOSE_GLITCH_ALERT_H)
                is_top = item is top
                if not is_top and item.get("_static_drawn") and inten < 0.85:
                    continue
                _draw_glitch_fault(
                    canvas,
                    w,
                    h,
                    "",
                    phase if is_top else 0,
                    theme=str(item.get("theme") or self.expose_fault_theme or "blue"),
                    lite=not is_top,
                    intensity=inten,
                )
                if not is_top:
                    item["_static_drawn"] = True
                # 高强度：顶窗轻微抖动
                if is_top and inten > 0.55:
                    try:
                        geo = win.geometry()
                        # WxH+X+Y
                        parts = geo.split("+")
                        if len(parts) >= 3:
                            x = int(parts[1]) + random.randint(-int(1 + inten * 3), int(1 + inten * 3))
                            y = int(parts[2]) + random.randint(-int(1 + inten * 2), int(1 + inten * 2))
                            win.geometry(f"{w}x{h}+{x}+{y}")
                    except Exception:
                        pass
            except Exception:
                pass
        self.expose_glitch_phase = phase + 1
        if phase % 8 == 0:
            try:
                self._ensure_expose_glitch_bg()
            except Exception:
                pass
        anim_ms = max(260, int(EXPOSE_GLITCH_ANIM_MS - inten * 80))
        self.expose_glitch_job = self.root.after(anim_ms, self._animate_glitch_fault)

    def _spawn_expose_qte_only(self) -> None:
        """仅刷新圆环判定（故障叠层已存在时复用）。"""
        if not self.expose_session_active:
            return
        if self.expose_qte_win and self.expose_qte_win.winfo_exists():
            self.expose_qte_win.destroy()
        qte_size = self.display_size + EXPOSE_RING_PAD
        sw = int(self.root.winfo_screenwidth())
        sh = int(self.root.winfo_screenheight())
        qx = max(8, (sw - qte_size) // 2)
        qy = max(8, (sh - qte_size) // 2)
        span, speed = self._expose_medium_params()
        self.expose_pointer_base_speed = speed
        round_idx = min(max(0, self.expose_hit_streak), max(0, EXPOSE_GLITCH_HITS_REQUIRED - 1))
        # 最终判定更难一档
        if getattr(self, "expose_phase", "storm") == "final":
            round_idx = max(round_idx, len(EXPOSE_BLUE_SPAN_RATIOS) - 1)
        self._expose_blue_span = _expose_blue_span_for_round(span, round_idx)
        self._expose_pointer_speed = min(
            EXPOSE_POINTER_MAX_SPEED,
            speed * (1 + self.expose_hit_streak * EXPOSE_SPEED_STREAK_MULT),
        )
        self.expose_blue_start = random.uniform(0, 360)
        self.expose_qte_angle = 0.0
        self.expose_qte_win = tk.Toplevel(self.root)
        self.expose_qte_win.overrideredirect(True)
        self._apply_window_layer(self.expose_qte_win)
        self.expose_qte_win.configure(bg="magenta")
        self.expose_qte_win.wm_attributes("-transparentcolor", "magenta")
        self.expose_qte_canvas = tk.Canvas(
            self.expose_qte_win, width=qte_size, height=qte_size, bg="magenta", highlightthickness=0
        )
        self.expose_qte_canvas.pack()
        try:
            self.expose_qte_win.update_idletasks()
        except Exception:
            pass
        self.expose_qte_win.geometry(f"{qte_size}x{qte_size}+{qx}+{qy}")
        self.expose_qte_active = True
        self.expose_qte_done = False
        self.expose_enter_armed = True
        self.expose_enter_was_down = self._expose_enter_key_down()
        for seq in ("<Return>", "<KP_Enter>", "<KeyPress-Return>", "<KeyPress-KP_Enter>"):
            self.expose_qte_win.bind(seq, self._expose_qte_enter)
            for item in list(getattr(self, "expose_glitch_wins", []) or []):
                win = item.get("win")
                if win is not None:
                    try:
                        if win.winfo_exists():
                            win.bind(seq, self._expose_qte_enter)
                    except Exception:
                        pass
        try:
            for item in self.expose_glitch_wins:
                win = item.get("win")
                if win is not None and win.winfo_exists():
                    win.lift()
            self.expose_qte_win.lift()
            self.expose_qte_win.focus_force()
        except Exception:
            pass
        self.root.after(30, self._focus_expose_qte)
        self.root.after(120, self._focus_expose_qte)
        self._expose_qte_tick()

    def _expose_required_taps(self) -> int:
        """本局所需命中次数：首次约 12，每次完美通关 +1，上限 EXPOSE_TAPS_MAX（约 28）。"""
        try:
            stats = self.achievements.get("stats") or {}
            perfect = int(stats.get("expose_perfect_clears", 0) or 0)
        except Exception:
            perfect = 0
        return max(
            EXPOSE_TAPS_FIRST,
            min(EXPOSE_TAPS_MAX, EXPOSE_TAPS_FIRST + perfect * EXPOSE_TAPS_STEP),
        )

    def _spawn_expose_glitch_round(self) -> None:
        """开局/续局：确保故障霸屏叠层 + 圆环判定。"""
        if not self.expose_session_active:
            return
        if not getattr(self, "expose_glitch_wins", None):
            self.expose_glitch_wins = []
        if self._expose_fault_count() <= 0 and getattr(self, "expose_phase", "storm") == "storm":
            self.expose_fault_theme = "blue"
            self.expose_glitch_phase = 0
            n = int(getattr(self, "_expose_fault_start_n", 0) or self._expose_required_taps())
            self._sync_expose_fault_stack(n)
            self._show_toast(f"暴露 · Enter×{n}", "#66aaff", duration_ms=1100)
        self._spawn_expose_qte_only()

    def _focus_expose_qte(self) -> None:
        if not self.expose_session_active:
            return
        try:
            # 不 lift 全部故障窗（多窗会明显卡顿）；只把判定环置顶
            if self.expose_qte_win and self.expose_qte_win.winfo_exists():
                self.expose_qte_win.lift()
                self.expose_qte_win.focus_force()
            else:
                self.root.focus_force()
        except Exception:
            pass

    def _expose_enter_key_down(self) -> bool:
        if sys.platform != "win32":
            return False
        try:
            # VK_RETURN = 0x0D
            return bool(ctypes.windll.user32.GetAsyncKeyState(0x0D) & 0x8000)
        except Exception:
            return False

    def _expose_qte_tick(self) -> None:
        if not self.expose_qte_active or not self.expose_qte_canvas:
            return
        # 无焦点时也能用 Enter：轮询物理按键边沿
        if self.expose_enter_armed and not self.expose_qte_done:
            down = self._expose_enter_key_down()
            if down and not self.expose_enter_was_down:
                self._expose_qte_enter()
            self.expose_enter_was_down = down
        if not self.expose_qte_active or not self.expose_qte_canvas:
            return
        cur = getattr(self, "_expose_pointer_speed", EXPOSE_POINTER_SPEED)
        self._expose_pointer_speed = min(EXPOSE_POINTER_MAX_SPEED, cur + EXPOSE_SPEED_TICK_BOOST)
        # tick 变稀后按时间补偿角速度，判定难度不变
        step = float(self._expose_pointer_speed) * (float(EXPOSE_QTE_TICK_MS) / 16.0)
        self.expose_qte_angle = (self.expose_qte_angle + step) % 360
        size = self.expose_qte_canvas.winfo_width() or 80
        span = getattr(self, "_expose_blue_span", EXPOSE_BLUE_SPAN)
        _draw_expose_qte_ring(self.expose_qte_canvas, size, self.expose_blue_start, self.expose_qte_angle, blue_span=span)
        self.expose_anim_job = self.root.after(EXPOSE_QTE_TICK_MS, self._expose_qte_tick)

    def _expose_qte_enter(self, _event=None) -> None:
        if not self.expose_enter_armed:
            return
        if not self.expose_qte_active or self.expose_qte_done or not self.expose_session_active:
            return
        hit = _angle_in_arc(
            self.expose_qte_angle,
            self.expose_blue_start,
            getattr(self, "_expose_blue_span", EXPOSE_BLUE_SPAN),
        )
        self._resolve_expose_qte_hit(hit)

    def _play_expose_qte(self) -> None:
        if self.dragging or self.state == "work":
            return
        self._interrupt_current_interaction()
        self._cancel_game_countdown()
        self._cancel_idle_chain()
        self._hide_main_menu()
        if self.mode == "quiet" and self.state == "rest":
            self._stop_rest_bobble()
        self.state = "action"
        self.action_name = "expose"
        self.expose_hit_streak = 0
        self._cancel_expose_qte()
        self.expose_session_active = False
        self.expose_enter_armed = False
        _, base = self._expose_medium_params()
        self.expose_pointer_base_speed = base

        def begin() -> None:
            # 倒计时期间看门狗可能改过状态：强制拉回暴露
            self.state = "action"
            self.action_name = "expose"
            self.expose_session_active = True
            self.expose_phase = "storm"
            self.expose_hit_streak = 0
            self.expose_miss_count = 0
            self._expose_had_miss = False
            self.expose_fault_theme = "blue"
            self._expose_fault_start_n = self._expose_required_taps()
            self.expose_enter_armed = True
            self.expose_enter_was_down = self._expose_enter_key_down()
            self._cancel_idle_chain()
            # 整场绑定 root（覆盖同键位，不叠多层）；靠 expose_enter_armed 开关
            for seq in ("<Return>", "<KP_Enter>", "<KeyPress-Return>", "<KeyPress-KP_Enter>"):
                self.root.bind(seq, self._expose_qte_enter)
            try:
                self._spawn_expose_glitch_round()
            except Exception:
                try:
                    self._spawn_expose_glitch_round()
                except Exception as exc:
                    self._show_toast(f"暴露界面打开失败：{exc}", "#ff6666")
                    self._finish_expose_session(cleared=False)
                    return
            if not self.expose_qte_win or self._expose_fault_count() <= 0:
                self._show_toast("暴露界面未生成，请重试", "#ff6666")
                self._finish_expose_session(cleared=False)
                return
            self._focus_expose_qte()
            self.root.after(80, self._focus_expose_qte)
            self.root.after(250, self._focus_expose_qte)

        def after_guide() -> None:
            self.state = "action"
            self.action_name = "expose"
            self._start_game_countdown(begin, title="暴露")

        self._ensure_first_play_guide("expose", after_guide)

    def _resolve_expose_qte_hit(self, success: bool) -> None:
        if self.action_name != "expose" or not self.expose_session_active:
            return
        if self.expose_qte_done:
            return
        self.expose_qte_done = True
        self.expose_qte_active = False
        self.expose_enter_armed = False
        if self.expose_anim_job:
            self.root.after_cancel(self.expose_anim_job)
            self.expose_anim_job = None
        phase = getattr(self, "expose_phase", "storm")

        # 最终判定已并入故障清光；清光即通关
        if phase == "final":
            if success:
                self._finish_expose_session(cleared=True)
            else:
                self._expose_had_miss = True
                self.expose_miss_count = int(getattr(self, "expose_miss_count", 0) or 0) + 1
                if self.expose_miss_count > 2:
                    self._apply_expose_fault_theme("red")
                self.expose_phase = "storm"
                n = int(getattr(self, "_expose_fault_start_n", 0) or self._expose_required_taps())
                self._sync_expose_fault_stack(max(n, 3))
                self._apply_expose_fail_penalty()
                self._finish_expose_session(cleared=False)
            return

        if success:
            self.expose_hit_streak += 1
            left = max(0, self._expose_fault_count() - EXPOSE_FAULT_REMOVE_ON_HIT)
            self._sync_expose_fault_stack(left)
            if left <= 0:
                self._finish_expose_session(cleared=True)
                return
            self._show_toast(f"消除故障 · 剩余 {left}", "#44ff88", duration_ms=800)
            self.root.after(EXPOSE_GLITCH_REFRESH_MS, self._spawn_expose_qte_only)
            return

        self._expose_had_miss = True
        self.expose_miss_count = int(getattr(self, "expose_miss_count", 0) or 0) + 1
        # 失手超过 2 次：故障弹窗由蓝变红
        if self.expose_miss_count > 2 and str(getattr(self, "expose_fault_theme", "blue") or "") != "red":
            self._apply_expose_fault_theme("red")
        # 失手：增加弹窗；顶满则失败，约 3s 后清窗
        added = self._expose_fault_count() + EXPOSE_FAULT_ADD_ON_MISS
        self._sync_expose_fault_stack(min(EXPOSE_FAULT_MAX, added))
        if self._expose_fault_count() >= EXPOSE_FAULT_MAX:
            self._apply_expose_fail_penalty()
            self._finish_expose_session(cleared=False)
            return
        tip_col = "#ff4466" if self.expose_miss_count > 2 else "#ff8866"
        self._show_toast(f"故障扩散 · {self._expose_fault_count()}", tip_col, duration_ms=800)
        self.root.after(EXPOSE_GLITCH_REFRESH_MS, self._spawn_expose_qte_only)

    def _finish_expose_session(self, *, cleared: bool) -> None:
        self.expose_session_active = False
        self._cancel_game_countdown()
        if cleared:
            self._cancel_expose_qte()
            self.mood = min(100, self.mood + 5)
            self._refresh_panel()
            try:
                stats = self.achievements.setdefault("stats", {})
                stats["expose_clears"] = int(stats.get("expose_clears", 0) or 0) + 1
                if not bool(getattr(self, "_expose_had_miss", False)):
                    stats["expose_perfect_clears"] = int(stats.get("expose_perfect_clears", 0) or 0) + 1
                    nxt = self._expose_required_taps()
                    self._show_toast(
                        f"完美通关 · 下次 Enter×{nxt}（上限 {EXPOSE_TAPS_MAX}）",
                        "#88ffcc",
                        duration_ms=2200,
                    )
                _save_achievements(self.achievements)
                self._check_achievements(source="expose")
            except Exception:
                pass
            self._show_game_clear(
                title="暴露通关！",
                subtitle="",
                accent="#44ff88",
                on_done=self._after_expose,
            )
        else:
            # 失败：故障窗再留约 3s +「暴露失败…」，到点必须关掉，不能卡住
            self.expose_enter_armed = False
            self.expose_qte_active = False
            if self.expose_qte_win and self.expose_qte_win.winfo_exists():
                try:
                    self.expose_qte_win.destroy()
                except Exception:
                    pass
                self.expose_qte_win = None
                self.expose_qte_canvas = None
            # 失败展示：停掉故障动画，窗口静态保留约 3s（避免持续重绘卡死）
            self.expose_session_active = True
            self._expose_fail_holding = True
            if self.expose_glitch_job:
                try:
                    self.root.after_cancel(self.expose_glitch_job)
                except Exception:
                    pass
                self.expose_glitch_job = None
            if self._expose_fault_count() <= 0:
                fail_theme = "red" if int(getattr(self, "expose_miss_count", 0) or 0) > 2 else "blue"
                self._apply_expose_fault_theme(fail_theme)
                self._sync_expose_fault_stack(max(EXPOSE_FAULT_START, 6))
            elif int(getattr(self, "expose_miss_count", 0) or 0) > 2:
                self._apply_expose_fault_theme("red")
            # 失败瞬间拉满故障感
            self.expose_glitch_intensity = max(
                0.75, float(getattr(self, "expose_glitch_intensity", 0.45) or 0.45)
            )
            try:
                self._ensure_expose_glitch_bg()
            except Exception:
                pass
            # 只画一次静态帧，不再开动画循环
            inten = float(getattr(self, "expose_glitch_intensity", 0.85) or 0.85)
            for item in list(getattr(self, "expose_glitch_wins", []) or []):
                canvas = item.get("canvas")
                win = item.get("win")
                try:
                    if canvas is None or win is None or not win.winfo_exists():
                        continue
                    _draw_glitch_fault(
                        canvas,
                        int(item.get("w") or EXPOSE_GLITCH_ALERT_W),
                        int(item.get("h") or EXPOSE_GLITCH_ALERT_H),
                        "",
                        0,
                        theme=str(item.get("theme") or self.expose_fault_theme or "blue"),
                        lite=True,
                        intensity=inten,
                    )
                    item["_static_drawn"] = True
                except Exception:
                    pass
            self._play_game_fail_voice("hurt", show_subtitle=False)
            self._show_speech_dialog(
                "暴露失败…",
                auto_hide_ms=1800,
                typewriter_ms=TYPEWRITER_MS,
                use_border5=False,
            )

            def finish_fail() -> None:
                # 先停动画再毁窗，避免 after 回调踩到已销毁控件而卡死
                self.expose_session_active = False
                self.expose_enter_armed = False
                self._expose_fail_holding = False
                if self.expose_glitch_job:
                    try:
                        self.root.after_cancel(self.expose_glitch_job)
                    except Exception:
                        pass
                    self.expose_glitch_job = None
                if self.expose_anim_job:
                    try:
                        self.root.after_cancel(self.expose_anim_job)
                    except Exception:
                        pass
                    self.expose_anim_job = None
                try:
                    self._destroy_expose_fault_stack()
                except Exception:
                    self.expose_glitch_wins = []
                    self.expose_glitch_win = None
                    self.expose_glitch_canvas = None
                try:
                    self._cancel_expose_qte()
                except Exception:
                    pass
                try:
                    self._after_expose()
                except Exception:
                    try:
                        self._finish_expression()
                    except Exception:
                        pass

            self.root.after(EXPOSE_FAIL_HOLD_MS, finish_fail)

    def _after_expose(self) -> None:
        if self.dragging or self.state != "action" or self.action_name != "expose":
            return
        self._cancel_action_end()
        self._finish_expression()

    def _open_expression_menu(self) -> None:
        self._show_sub_menu(
            [
                ("有主意", self._play_expression_idea),
                ("开心", self._play_happy),
                ("生气", self._play_expression_angry),
                ("疑问", lambda: self._play_expression("question")),
                ("伤心", self._play_expression_sad),
                ("脸红", self._play_expression_shy),
                ("wink", self._play_expression_wink),
                ("点赞", self._play_expression_like),
                ("比心", self._play_expression_bixin),
            ],
            offset_x=200,
        )

    def _play_expression_sad(self) -> None:
        if self.dragging or self.state == "work":
            return
        self._interrupt_current_interaction()
        self.state = "action"
        self.action_name = "sad"
        self.sad_phase = "squat"
        self._interact_flair("sad", banter=True)
        self._set_image(self.sprites.actions["squat"][0])
        self._play_expression_pop(times=3)
        self._show_rain_fx()
        tok = self.interaction_token
        self.root.after(SAD_SQUAT_MS, lambda t=tok: self._sad_phase_sad1(t))
        self._schedule_action_end(
            duration_ms=SAD_SQUAT_MS + SAD_SAD1_MS + SAD_SAD2_MS,
            action="sad",
            callback=self._after_expression_sad,
        )

    def _sad_phase_sad1(self, tok: int) -> None:
        if tok != self.interaction_token or self.action_name != "sad":
            return
        self.sad_phase = "sad1"
        self._set_image(self.sprites.sad1)
        self.root.after(SAD_SAD1_MS, lambda t=tok: self._sad_phase_sad2(t))

    def _sad_phase_sad2(self, tok: int) -> None:
        if tok != self.interaction_token or self.action_name != "sad":
            return
        self.sad_phase = "sad2"
        self._set_image(self.sprites.sad2)

    def _after_expression_sad(self) -> None:
        if self.dragging or self.state != "action" or self.action_name != "sad":
            return
        self.sad_phase = ""
        self._hide_rain_fx()
        self._cancel_action_end()
        self.mood = max(0, self.mood - 2)
        self._refresh_panel()
        self._finish_expression()

    def _play_expression_idea(self) -> None:
        if self.dragging or self.state == "work":
            return
        self._interrupt_current_interaction()
        self.state = "action"
        self.action_name = "idea"
        self._interact_flair("idea", banter=False)
        self._play_expression_pop()
        self._set_image(self.sprites.stand)
        self._show_bulb_fx()
        self.root.after(IDEA_STAND_MS, self._idea_to_eat2)

    def _idea_to_eat2(self) -> None:
        if self.dragging or self.state != "action" or self.action_name != "idea":
            return
        self._set_image(self.sprites.eat2_only)
        self._schedule_action_end(action="idea", callback=self._after_expression_idea)

    def _after_expression_idea(self) -> None:
        if self.dragging or self.state != "action" or self.action_name != "idea":
            return
        self._hide_bulb_fx()
        self._cancel_action_end()
        self.mood = min(100, self.mood + 4)
        self._refresh_panel()
        self._finish_expression()

    def _play_expression(self, name: str) -> None:
        if self.dragging or self._app_scene_blocks_actions():
            return
        sprites = {"angry": self.sprites.stand_angry, "question": self.sprites.stand_question}
        if name not in sprites:
            return
        self._interrupt_current_interaction()
        self.state = "action"
        self.action_name = name
        self._interact_flair(name, banter=True)
        self._play_expression_pop()
        self._set_image(sprites[name])
        self._schedule_action_end(action=name, callback=self._after_expression)

    def _finish_expression(self) -> None:
        self._clear_all_action_fx()
        self.action_name = ""
        if self.mode == "quiet":
            self.state = "rest"
            self._set_image(self.sprites.sleep[1])
            self._show_sleep_zzz()
            self._schedule_rest_bobble()
        else:
            self.state = "stand"
            self._set_image(self._current_stand_sprite())
        if not self._check_mood_happy():
            self._resume_idle(quick=True)

    def _after_expression(self) -> None:
        if self.dragging or self.state != "action":
            return
        self._add_interact_mood()
        self._finish_expression()

    def _follow_tick(self) -> None:
        self.follow_tick_job = None
        if not self._alive() or self.dragging or self.mode != "follow" or self.state in ("action", "sleep"):
            return
        if self.follow_dizzy:
            self._schedule_follow_tick(100)
            return
        self._follow_move()

    def _follow_dir_rotation(self, old_dir: str, new_dir: str) -> int:
        if not old_dir or old_dir == new_dir:
            return 0
        order = FOLLOW_DIR_ORDER
        if old_dir not in order or new_dir not in order:
            return 0
        diff = (order.index(new_dir) - order.index(old_dir)) % 4
        if diff == 1:
            return 1
        if diff == 3:
            return -1
        return 0

    def _track_follow_spin(self, direction: str) -> None:
        old_dir = self.follow_last_dir
        step = self._follow_dir_rotation(old_dir, direction)
        if step == 0:
            # 同向连续移动不重置；只有对向急转才打断
            if old_dir and old_dir != direction:
                self.follow_spin_dir = 0
                self.follow_spin_steps = 0
            return
        if self.follow_spin_dir == 0:
            self.follow_spin_dir = step
            self.follow_spin_steps = 1
        elif step == self.follow_spin_dir:
            self.follow_spin_steps += 1
        else:
            self.follow_spin_dir = step
            self.follow_spin_steps = 1
        if self.follow_spin_steps >= FOLLOW_DIZZY_SPIN_STEPS:
            self.follow_spin_dir = 0
            self.follow_spin_steps = 0
            self._start_follow_dizzy()

    def _hide_follow_dizzy_fx(self) -> None:
        if not self.follow_dizzy_fx_job and not self.follow_dizzy_fx_win:
            return
        if self.follow_dizzy_fx_job:
            self.root.after_cancel(self.follow_dizzy_fx_job)
            self.follow_dizzy_fx_job = None
        if self.follow_dizzy_fx_win and self.follow_dizzy_fx_win.winfo_exists():
            self.follow_dizzy_fx_win.destroy()
        self.follow_dizzy_fx_win = None
        self.follow_dizzy_fx_canvas = None
        self._notify_bg_fx_change()

    def _place_follow_dizzy_fx(self) -> None:
        if not self.follow_dizzy_fx_win or not self.follow_dizzy_fx_win.winfo_exists():
            return
        pad = 16
        display_y = self.y + self.click_bounce_offset
        self.follow_dizzy_fx_win.geometry(f"+{self.x - pad}+{display_y - pad}")

    def _show_follow_dizzy_fx(self) -> None:
        self._hide_follow_dizzy_fx()
        pad = 16
        size = self.display_size + pad * 2
        self.follow_dizzy_fx_win = tk.Toplevel(self.root)
        self.follow_dizzy_fx_win.overrideredirect(True)
        self._apply_window_layer(self.follow_dizzy_fx_win)
        self.follow_dizzy_fx_win.configure(bg="magenta")
        self.follow_dizzy_fx_win.wm_attributes("-transparentcolor", "magenta")
        self.follow_dizzy_fx_canvas = tk.Canvas(
            self.follow_dizzy_fx_win, width=size, height=size, bg="magenta", highlightthickness=0
        )
        self.follow_dizzy_fx_canvas.pack()
        self.follow_dizzy_fx_phase = 0
        self._animate_follow_dizzy_fx()
        self._notify_bg_fx_change()

    def _dizzy_fx_active(self) -> bool:
        return self.follow_dizzy or self.drag_dizzy or self.game_dizzy

    def _start_game_dizzy_stun(self) -> None:
        if self.mode != "game":
            return
        if self.game_dizzy_job:
            try:
                self.root.after_cancel(self.game_dizzy_job)
            except Exception:
                pass
            self.game_dizzy_job = None
        self.game_dizzy = True
        self.game_stunned_until_ms = int(time.time() * 1000) + GAME_DIZZY_STUN_MS
        # 定格站姿，避免走动帧停在半空像「没了」
        if self.sprites:
            try:
                self._set_image(self.sprites.stand)
            except Exception:
                pass
        if not self.follow_dizzy_fx_win or not self.follow_dizzy_fx_win.winfo_exists():
            self._show_follow_dizzy_fx()
        else:
            self._place_follow_dizzy_fx()
        # 晕眩时伴侣仍可见；只清同步特效，层级由 _stack_game_drops_visible 保证苍叶最上
        self._clear_mini_pet_fx_for_gather()
        self._sync_all_mini_pet_bg_fx()
        # 新建晕眩窗默认在最前，立刻把立绘抬回其上（避免被色键大窗盖住）
        self._stack_game_drops_visible()
        # 开语音且有 dizzy：强制播；否则保留打字框
        if self._vpet_voice_category_ready("dizzy"):
            self._addon_voice_vpet("dizzy", chain=False, interrupt_busy=True)
        else:
            self._show_speech_dialog(random.choice(GAME_DIZZY_LINES), auto_hide_ms=3200)
        self.game_dizzy_job = self.root.after(GAME_DIZZY_STUN_MS, self._end_game_dizzy_stun)

    def _end_game_dizzy_stun(self) -> None:
        if self.game_dizzy_job:
            try:
                self.root.after_cancel(self.game_dizzy_job)
            except Exception:
                pass
            self.game_dizzy_job = None
        self.game_dizzy = False
        self.game_stunned_until_ms = 0
        if not self.follow_dizzy and not self.drag_dizzy:
            self._hide_follow_dizzy_fx()
        if self.mode == "game":
            self._stack_game_drops_visible()

    def _animate_follow_dizzy_fx(self) -> None:
        if not self.follow_dizzy_fx_canvas or not self._dizzy_fx_active():
            self._hide_follow_dizzy_fx()
            return
        size = self.follow_dizzy_fx_canvas.winfo_width() or (self.display_size + 32)
        _draw_dizzy_sticker(self.follow_dizzy_fx_canvas, size, self.follow_dizzy_fx_phase)
        self.follow_dizzy_fx_phase += 1
        self._place_follow_dizzy_fx()
        # 保持晕眩特效在立绘下方；勿每帧 lift（Win32 很贵）
        self._dizzy_lift_counter = int(getattr(self, "_dizzy_lift_counter", 0) or 0) + 1
        if self._dizzy_lift_counter >= 8:
            self._dizzy_lift_counter = 0
            try:
                if self.follow_dizzy_fx_win and self.follow_dizzy_fx_win.winfo_exists():
                    self.follow_dizzy_fx_win.lift()
                self.root.lift()
            except Exception:
                pass
        self.follow_dizzy_fx_job = self.root.after(140, self._animate_follow_dizzy_fx)

    def _start_follow_dizzy(self) -> None:
        if self.follow_dizzy or self.mode != "follow":
            return
        self.follow_dizzy = True
        self.follow_animating = False
        self.follow_spin_dir = 0
        self.follow_spin_steps = 0
        self.follow_last_dir = ""
        self.state = "stand"
        self._set_image(self.sprites.stand)
        self._place_window()
        self._show_follow_dizzy_fx()
        if self._vpet_voice_category_ready("dizzy"):
            self._addon_voice_vpet("dizzy", chain=False, interrupt_busy=True)
        else:
            self._show_speech_dialog(FOLLOW_DIZZY_TEXT, auto_hide_ms=FOLLOW_DIZZY_STAND_MS)
        if self.follow_dizzy_job:
            self.root.after_cancel(self.follow_dizzy_job)
        self.follow_dizzy_job = self.root.after(FOLLOW_DIZZY_STAND_MS, self._end_follow_dizzy)

    def _drag_move_dir(self, dx: int, dy: int) -> str:
        if abs(dx) < DRAG_DIZZY_MIN_DELTA and abs(dy) < DRAG_DIZZY_MIN_DELTA:
            return ""
        if abs(dx) >= abs(dy):
            return "left" if dx < 0 else "right"
        return "front" if dy < 0 else "back"

    def _maybe_drag_dizzy_dialog(self) -> None:
        now_ms = int(time.time() * 1000)
        if now_ms - self.drag_dizzy_dialog_ms < DRAG_DIZZY_DIALOG_COOLDOWN_MS:
            return
        if self.speech_dialog and self.speech_dialog.winfo_exists():
            return
        self._show_speech_dialog(random.choice(DRAG_DIZZY_LINES), auto_hide_ms=2400)
        self.drag_dizzy_dialog_ms = now_ms

    def _track_drag_spin(self, direction: str) -> None:
        old_dir = self.drag_last_dir
        step = self._follow_dir_rotation(old_dir, direction)
        self.drag_last_dir = direction
        if step == 0:
            # 同一方向持续拖动不打断累积；对向急转才重置
            if old_dir and old_dir != direction:
                self.drag_spin_dir = 0
                self.drag_spin_steps = 0
            return
        if self.drag_spin_dir == 0:
            self.drag_spin_dir = step
            self.drag_spin_steps = 1
        elif step == self.drag_spin_dir:
            self.drag_spin_steps += 1
        else:
            self.drag_spin_dir = step
            self.drag_spin_steps = 1
        if self.drag_dizzy:
            self.drag_dizzy_extra_spins += 1
            if self.drag_dizzy_extra_spins >= DRAG_DIZZY_EXTRA_DIALOG_SPINS:
                self.drag_dizzy_extra_spins = 0
                self._maybe_drag_dizzy_dialog()
            return
        if self.drag_spin_steps >= DRAG_DIZZY_SPIN_STEPS:
            self.drag_spin_dir = 0
            self.drag_spin_steps = 0
            self._start_drag_dizzy()

    def _start_drag_dizzy(self) -> None:
        if self.drag_dizzy or not self.dragging or self.state != "drag":
            return
        self.drag_dizzy = True
        self.drag_dizzy_extra_spins = 0
        if not self.follow_dizzy_fx_win or not self.follow_dizzy_fx_win.winfo_exists():
            self._show_follow_dizzy_fx()
        else:
            self._place_follow_dizzy_fx()
        self._maybe_drag_dizzy_dialog()
        self._notify_bg_fx_change()

    def _end_drag_dizzy(self) -> None:
        if not self.drag_dizzy:
            return
        self.drag_dizzy = False
        self.drag_last_dir = ""
        self.drag_spin_dir = 0
        self.drag_spin_steps = 0
        self.drag_dizzy_extra_spins = 0
        if not self.follow_dizzy:
            self._hide_follow_dizzy_fx()

    def _end_follow_dizzy(self) -> None:
        self.follow_dizzy_job = None
        self.follow_dizzy = False
        self.follow_last_dir = ""
        self._hide_follow_dizzy_fx()
        if self.mode != "follow":
            return
        self.state = "stand"
        self._set_image(self.sprites.stand)
        self._follow_tick()

    def _follow_animate(self) -> None:
        self.follow_anim_job = None
        if not self._alive() or self.dragging or self.mode != "follow" or self.state != "walk":
            self.follow_animating = False
            return

        frames = self._walk_sprites[self.direction]
        self._set_image(frames[self.walk_frame % 2])
        self.walk_frame += 1
        self.follow_anim_job = self._safe_after(WALK_FRAME_MS, self._follow_animate)

    def _follow_move(self) -> None:
        if not self._alive() or self.dragging or self.mode != "follow" or self.state in ("action", "sleep"):
            self._schedule_follow_tick()
            return

        mx = self.root.winfo_pointerx()
        my = self.root.winfo_pointery()
        cx = self.x + self.display_size // 2
        cy = self.y + self.display_size // 2
        dx = mx - cx
        dy = my - cy
        dist = (dx * dx + dy * dy) ** 0.5

        if dist > FOLLOW_FAR_DIST:
            self._maybe_show_follow_wait()

        if dist < FOLLOW_STOP_DIST:
            if self.state != "stand":
                self.state = "stand"
                self._set_image(self.sprites.stand)
            self.follow_animating = False
            self._schedule_follow_tick()
            return

        if abs(dx) > abs(dy):
            direction = "right" if dx > 0 else "left"
        else:
            direction = "front" if dy > 0 else "back"

        direction = self._resolve_walk_direction(direction, current=self.follow_last_dir or self.direction)
        if self.follow_last_dir and direction != self.follow_last_dir:
            self._track_follow_spin(direction)
            if self.follow_dizzy:
                return
        self.follow_last_dir = direction

        self.state = "walk"
        self.direction = direction
        step_x, step_y = self.FOLLOW_DELTAS[direction]
        self.x += step_x
        self.y += step_y
        self._place_window(light=True)

        if not self.follow_animating:
            self.follow_animating = True
            self._follow_animate()

        self._schedule_follow_tick()

    def _maybe_show_follow_wait(self) -> None:
        now_ms = int(time.time() * 1000)
        if now_ms - self.last_follow_wait_ms < FOLLOW_WAIT_COOLDOWN_MS:
            return
        self.last_follow_wait_ms = now_ms
        self._show_speech_dialog(random.choice(FOLLOW_WAIT_TEXTS), auto_hide_ms=2500)

